class RecoveryEngine {
public:
    static void replay_wal(const std::string& wal_path, ConcurrentMVCCMap& target_map) {
        int fd = open(wal_path.c_str(), O_RDONLY);
        if (fd < 0) return; // Empty or uncreated WAL

        std::vector<uint8_t> buffer(ALIGN_BLOCK_SIZE * 16);
        ssize_t bytes_read = 0;
        size_t offset = 0;

        while ((bytes_read = pread(fd, buffer.data(), buffer.size(), offset)) > 0) {
            size_t cursor = 0;
            while (cursor + sizeof(LogHeader) <= static_cast<size_t>(bytes_read)) {
                LogHeader hdr;
                std::memcpy(&hdr, buffer.data() + cursor, sizeof(LogHeader));

                if (hdr.magic != WAL_MAGIC) {
                    // Reached unwritten / zero-padded block boundary
                    break;
                }

                if (cursor + sizeof(LogHeader) + hdr.data_len > static_cast<size_t>(bytes_read)) {
                    // Torn frame at block boundary
                    break;
                }

                const uint8_t* payload_ptr = buffer.data() + cursor + sizeof(LogHeader);
                uint64_t key = 0;
                std::memcpy(&key, payload_ptr, sizeof(uint64_t));

                const uint8_t* val_ptr = payload_ptr + sizeof(uint64_t);
                size_t val_size = hdr.data_len - sizeof(uint64_t);

                // Verify Checksum
                uint32_t expected_crc = calculate_crc32c(0, reinterpret_cast<const uint8_t*>(&key), sizeof(uint64_t));
                if (val_size > 0) {
                    expected_crc = calculate_crc32c(expected_crc, val_ptr, val_size);
                }

                if (expected_crc != hdr.crc32) {
                    // Corrupted log record encountered; stop replay
                    break;
                }

                // Apply committed transactions to MVCC map
                if (hdr.type == static_cast<uint8_t>(LogRecordType::TX_UPDATE)) {
                    target_map.write(key, hdr.tx_id, 0, std::span<const uint8_t>(val_ptr, val_size), false);
                } else if (hdr.type == static_cast<uint8_t>(LogRecordType::TX_DELETE)) {
                    target_map.write(key, hdr.tx_id, 0, {}, true);
                }

                cursor += sizeof(LogHeader) + hdr.data_len;
            }
            offset += bytes_read;
        }
        close(fd);
    }
};

