### Part 3: Lock-Free MVCC Skip-List Engine

```cpp
namespace mvcc {

class LockFreeMVCCSkipList {
public:
    LockFreeMVCCSkipList() {
        // Sentinel Head and Tail
        VersionNode* head_v = new VersionNode(0, nullptr, 0);
        VersionNode* tail_v = new VersionNode(0, nullptr, 0);
        head_v->commit_ts.store(1, std::memory_order_relaxed);
        tail_v->commit_ts.store(1, std::memory_order_relaxed);

        head_ = new SkipListNode(0, MAX_SKIPLIST_LEVEL, head_v);
        tail_ = new SkipListNode(UINT64_MAX, MAX_SKIPLIST_LEVEL, tail_v);

        for (size_t i = 0; i < MAX_SKIPLIST_LEVEL; ++i) {
            head_->forward[i].store(tail_, std::memory_order_relaxed);
        }
    }

    ~LockFreeMVCCSkipList() {
        SkipListNode* curr = head_;
        while (curr) {
            SkipListNode* next = get_unmarked(curr->forward[0].load(std::memory_order_relaxed));
            VersionNode* v = curr->version_chain_head.load(std::memory_order_relaxed);
            while (v) {
                VersionNode* vn = v->next_version.load(std::memory_order_relaxed);
                delete v;
                v = vn;
            }
            delete curr;
            curr = next;
        }
    }

    // ------------------------------------------------------------------------
    // Search (Snapshot Isolation Visibility): Strictly Wait-Free O(log N)
    // ------------------------------------------------------------------------
    std::optional<std::string> search(uint64_t key, uint64_t read_ts, size_t tid) {
        auto& epoch_mgr = AdaptiveEpochManager::instance();
        epoch_mgr.enter_read(tid);

        SkipListNode* pred = head_;
        SkipListNode* curr = nullptr;

        for (int i = static_cast<int>(MAX_SKIPLIST_LEVEL) - 1; i >= 0; --i) {
            curr = pred->forward[i].load(std::memory_order_acquire);
            while (true) {
                SkipListNode* unmarked_curr = get_unmarked(curr);
                if (!unmarked_curr || unmarked_curr->key >= key) {
                    break;
                }
                pred = unmarked_curr;
                curr = pred->forward[i].load(std::memory_order_acquire);
            }
        }

        SkipListNode* target = get_unmarked(curr);
        if (!target || target->key != key) {
            epoch_mgr.exit_read(tid);
            return std::nullopt;
        }

        // Traverse MVCC version chain wait-free under SI visibility rules
        VersionNode* v = target->version_chain_head.load(std::memory_order_acquire);
        while (v != nullptr) {
            epoch_mgr.set_hazard(tid, v);

            // Re-verify after hazard protection to guard against immediate prune
            if (target->version_chain_head.load(std::memory_order_acquire) != v &&
                v->next_version.load(std::memory_order_acquire) == nullptr) {
                // Pointer was pruned and unlinked
                v = target->version_chain_head.load(std::memory_order_acquire);
                continue;
            }

            uint64_t raw_ts = v->commit_ts.load(std::memory_order_acquire);
            uint64_t cts = raw_ts & TS_MASK;

            if (cts != TX_UNCOMMITTED && cts != TX_ABORTED && cts <= read_ts) {
                if ((raw_ts & TOMBSTONE_FLAG) != 0) {
                    epoch_mgr.exit_read(tid);
                    return std::nullopt; // Logical deletion
                }
                std::string result(v->value_data, v->value_len);
                epoch_mgr.exit_read(tid);
                return result;
            }
            v = v->next_version.load(std::memory_order_acquire);
        }

        epoch_mgr.exit_read(tid);
        return std::nullopt;
    }

    // ------------------------------------------------------------------------
    // Upsert (Insert / Update): Lock-Free version chain prepending & CAS
    // ------------------------------------------------------------------------
    bool upsert(uint64_t key, const char* val, uint32_t len, uint64_t tx_id, size_t tid, bool is_delete = false) {
        auto& epoch_mgr = AdaptiveEpochManager::instance();
        epoch_mgr.enter_read(tid);

        SkipListNode* preds[MAX_SKIPLIST_LEVEL];
        SkipListNode* succs[MAX_SKIPLIST_LEVEL];

        while (true) {
            if (find_position(key, preds, succs)) {
                // Key exists: atomically prepend new version to version chain
                SkipListNode* node = succs[0];
                VersionNode* old_head = node->version_chain_head.load(std::memory_order_acquire);

                // Multi-writer conflict detection: abort if uncommitted version present
                if (old_head != nullptr) {
                    uint64_t old_ts = old_head->commit_ts.load(std::memory_order_acquire) & TS_MASK;
                    if (old_ts == TX_UNCOMMITTED && old_head->tx_id != tx_id) {
                        epoch_mgr.exit_read(tid);
                        return false; // Write-Write conflict: first committer wins
                    }
                }

                auto* new_version = new VersionNode(tx_id, val, len, old_head, is_delete);
                if (node->version_chain_head.compare_exchange_strong(
                        old_head, new_version, std::memory_order_acq_rel, std::memory_order_acquire)) {
                    epoch_mgr.exit_read(tid);
                    return true;
                }
                // CAS failed: retry loop
                delete new_version;
                continue;
            }

            // Key does not exist: create new SkipList node
            size_t height = random_height();
            auto* new_version = new VersionNode(tx_id, val, len, nullptr, is_delete);
            auto* new_node = new SkipListNode(key, height, new_version);

            for (size_t i = 0; i < height; ++i) {
                new_node->forward[i].store(succs[i], std::memory_order_relaxed);
            }

            // Link bottom level first via CAS
            SkipListNode* pred = preds[0];
            SkipListNode* succ = succs[0];
            if (!pred->forward[0].compare_exchange_strong(
                    succ, new_node, std::memory_order_release, std::memory_order_acquire)) {
                delete new_version;
                delete new_node;
                continue; // Retry insertion
            }

            // Link higher levels
            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    pred = preds[i];
                    succ = succs[i];
                    new_node->forward[i].store(succ, std::memory_order_relaxed);
                    if (pred->forward[i].compare_exchange_strong(
                            succ, new_node, std::memory_order_release, std::memory_order_acquire)) {
                        break;
                    }
                    find_position(key, preds, succs);
                }
            }
            epoch_mgr.exit_read(tid);
            return true;
        }
    }

    // ------------------------------------------------------------------------
    // Commit & Abort Protocol
    // ------------------------------------------------------------------------
    bool commit_version(uint64_t key, uint64_t tx_id, uint64_t commit_ts, size_t tid) {
        return finalize_version(key, tx_id, commit_ts, tid);
    }

    bool abort_version(uint64_t key, uint64_t tx_id, size_t tid) {
        return finalize_version(key, tx_id, TX_ABORTED, tid);
    }

    // Prune obsolete historical versions below the active minimum epoch threshold
    void prune_versions(uint64_t key, uint64_t watermark_ts, size_t tid) {
        SkipListNode* preds[MAX_SKIPLIST_LEVEL];
        SkipListNode* succs[MAX_SKIPLIST_LEVEL];
        if (!find_position(key, preds, succs)) return;

        SkipListNode* node = succs[0];
        VersionNode* curr = node->version_chain_head.load(std::memory_order_acquire);
        VersionNode* prev = nullptr;
        bool visible_version_seen = false;

        while (curr) {
            uint64_t cts = curr->commit_ts.load(std::memory_order_acquire);
            uint64_t ts = cts & TS_MASK;

            if (ts != TX_UNCOMMITTED && ts != TX_ABORTED && ts <= watermark_ts) {
                if (!visible_version_seen) {
                    visible_version_seen = true;
                    prev = curr;
                    curr = curr->next_version.load(std::memory_order_acquire);
                    continue;
                }
                // Unlink all subsequent versions older than current snapshot visibility
                if (prev) {
                    VersionNode* next = curr->next_version.load(std::memory_order_acquire);
                    if (prev->next_version.compare_exchange_strong(curr, next, std::memory_order_acq_rel)) {
                        AdaptiveEpochManager::instance().retire_node(curr, tid);
                        curr = next;
                        continue;
                    }
                }
            }
            prev = curr;
            curr = curr->next_version.load(std::memory_order_acquire);
        }
    }

private:
    SkipListNode* head_;
    SkipListNode* tail_;

    bool finalize_version(uint64_t key, uint64_t tx_id, uint64_t target_state, size_t tid) {
        auto& epoch_mgr = AdaptiveEpochManager::instance();
        epoch_mgr.enter_read(tid);

        SkipListNode* preds[MAX_SKIPLIST_LEVEL];
        SkipListNode* succs[MAX_SKIPLIST_LEVEL];

        if (!find_position(key, preds, succs)) {
            epoch_mgr.exit_read(tid);
            return false;
        }

        SkipListNode* node = succs[0];
        VersionNode* v = node->version_chain_head.load(std::memory_order_acquire);

        while (v) {
            if (v->tx_id == tx_id) {
                uint64_t cur_val = v->commit_ts.load(std::memory_order_acquire);
                if ((cur_val & TS_MASK) != TX_UNCOMMITTED) {
                    epoch_mgr.exit_read(tid);
                    return false;
                }
                uint64_t new_val = (target_state == TX_ABORTED) ? TX_ABORTED : ((cur_val & TOMBSTONE_FLAG) | target_state);
                bool ok = v->commit_ts.compare_exchange_strong(cur_val, new_val, std::memory_order_release);
                epoch_mgr.exit_read(tid);
                return ok;
            }
            v = v->next_version.load(std::memory_order_acquire);
        }

        epoch_mgr.exit_read(tid);
        return false;
    }

    bool find_position(uint64_t key, SkipListNode** preds, SkipListNode** succs) {
        SkipListNode* pred = head_;
        for (int i = static_cast<int>(MAX_SKIPLIST_LEVEL) - 1; i >= 0; --i) {
            SkipListNode* curr = pred->forward[i].load(std::memory_order_acquire);
            while (true) {
                SkipListNode* unmarked_curr = get_unmarked(curr);
                if (!unmarked_curr) break;
                if (unmarked_curr->key >= key) {
                    break;
                }
                pred = unmarked_curr;
                curr = pred->forward[i].load(std::memory_order_acquire);
            }
            preds[i] = pred;
            succs[i] = get_unmarked(curr);
        }
        return (succs[0] != nullptr && succs[0]->key == key && !is_marked(succs[0]->forward[0].load(std::memory_order_acquire)));
    }

    size_t random_height() noexcept {
        static thread_local uint32_t seed = 0x12345678 ^ static_cast<uint32_t>(__rdtsc());
        size_t level = 1;
        while (level < MAX_SKIPLIST_LEVEL) {
            seed ^= seed << 13;
            seed ^= seed >> 17;
            seed ^= seed << 5;
            if ((seed & 0x3) != 0) break; // p = 0.25
            level++;
        }
        return level;
    }
};

} // namespace mvcc
