### Part 4: Lock-Free MPSC Ring Buffer & io_uring WAL Subsystem

```cpp
#pragma once

#include <liburing.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <vector>
#include <thread>
#include <chrono>
#include <stdexcept>
#include <condition_variable>

namespace wal {

static constexpr size_t PAGE_SIZE = 4096;
static constexpr size_t RING_BUFFER_CAPACITY = 1024 * 1024; // 1M slots
static constexpr size_t DIRECT_IO_BUFFER_SIZE = 4 * 1024 * 1024; // 4MB DMA buffer
static constexpr unsigned IOURING_ENTRIES = 256;

#pragma pack(push, 1)
struct LogRecordHeader {
    uint64_t lsn;
    uint64_t tx_id;
    uint32_t key_len;
    uint32_t val_len;
    uint32_t crc32c;
};
#pragma pack(pop)

struct alignas(64) MPSCQueueSlot {
    std::atomic<uint64_t> sequence{0};
    LogRecordHeader header;
    char payload[512]; // Zero-allocation small payload buffer
};

// Monotonically tracked completion promise table
class alignas(64) LsnCompletionTable {
public:
    void notify_flushed(uint64_t flushed_lsn) noexcept {
        flushed_lsn_.store(flushed_lsn, std::memory_order_release);
        // Direct event notification without thundering herd:
        // Worker threads spin briefly with exponential backoff or futex wait
    }

    void wait_lsn(uint64_t lsn) const noexcept {
        uint32_t spins = 0;
        while (flushed_lsn_.load(std::memory_order_acquire) < lsn) {
            if (++spins < 64) {
                _mm_pause();
            } else {
                std::this_thread::yield();
            }
        }
    }

    [[nodiscard]] uint64_t get_flushed_lsn() const noexcept {
        return flushed_lsn_.load(std::memory_order_acquire);
    }

private:
    std::atomic<uint64_t> flushed_lsn_{0};
};

class MPSCLogRing {
public:
    MPSCLogRing() {
        buffer_ = new MPSCQueueSlot[RING_BUFFER_CAPACITY];
        for (size_t i = 0; i < RING_BUFFER_CAPACITY; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    ~MPSCLogRing() {
        delete[] buffer_;
    }

    // Producer enqueue: Lock-free multi-producer
    bool enqueue(uint64_t lsn, uint64_t tx_id, const char* data, uint32_t len) {
        if (len > sizeof(MPSCQueueSlot::payload)) return false;

        uint64_t pos = head_.load(std::memory_order_relaxed);
        while (true) {
            MPSCQueueSlot* slot = &buffer_[pos & (RING_BUFFER_CAPACITY - 1)];
            uint64_t seq = slot->sequence.load(std::memory_order_acquire);
            intptr_t diff = static_cast<intptr_t>(seq) - static_cast<intptr_t>(pos);

            if (diff == 0) {
                if (head_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                    // Populate record
                    slot->header.lsn = lsn;
                    slot->header.tx_id = tx_id;
                    slot->header.key_len = 0;
                    slot->header.val_len = len;
                    slot->header.crc32c = compute_crc32c(data, len);
                    if (data && len > 0) {
                        std::memcpy(slot->payload, data, len);
                    }
                    slot->sequence.store(pos + 1, std::memory_order_release);
                    return true;
                }
            } else if (diff < 0) {
                return false; // Full ring buffer
            } else {
                pos = head_.load(std::memory_order_relaxed);
            }
        }
    }

    // Consumer dequeue batch: Single-consumer draining
    size_t dequeue_batch(std::vector<MPSCQueueSlot*>& batch_out, size_t max_items) {
        size_t count = 0;
        uint64_t pos = tail_.load(std::memory_order_relaxed);

        while (count < max_items) {
            MPSCQueueSlot* slot = &buffer_[pos & (RING_BUFFER_CAPACITY - 1)];
            uint64_t seq = slot->sequence.load(std::memory_order_acquire);
            intptr_t diff = static_cast<intptr_t>(seq) - static_cast<intptr_t>(pos + 1);

            if (diff == 0) {
                batch_out.push_back(slot);
                pos++;
                count++;
            } else {
                break; // No more committed items
            }
        }

        if (count > 0) {
            tail_.store(pos, std::memory_order_release);
        }
        return count;
    }

    void release_slots(size_t count, uint64_t start_tail) {
        for (size_t i = 0; i < count; ++i) {
            uint64_t pos = start_tail + i;
            MPSCQueueSlot* slot = &buffer_[pos & (RING_BUFFER_CAPACITY - 1)];
            slot->sequence.store(pos + RING_BUFFER_CAPACITY, std::memory_order_release);
        }
    }

    [[nodiscard]] uint64_t get_tail() const noexcept {
        return tail_.load(std::memory_order_relaxed);
    }

private:
    static uint32_t compute_crc32c(const char* data, size_t len) noexcept {
        uint32_t crc = ~0u;
        for (size_t i = 0; i < len; ++i) {
            crc = _mm_crc32_u8(crc, static_cast<uint8_t>(data[i]));
        }
        return ~crc;
    }

    alignas(64) std::atomic<uint64_t> head_{0};
    alignas(64) std::atomic<uint64_t> tail_{0};
    MPSCQueueSlot* buffer_;
};

// ----------------------------------------------------------------------------
// io_uring Direct I/O Persistence Engine
// ----------------------------------------------------------------------------
class PipelinedIoUringWalEngine {
public:
    PipelinedIoUringWalEngine(const char* wal_path, LsnCompletionTable& completion_table)
        : completion_table_(completion_table), running_(false) {

        // Open with O_DIRECT and O_DSYNC (kernel-bypass, aligned requirements)
        fd_ = open(wal_path, O_CREAT | O_RDWR | O_DIRECT | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT");
        }

        // Allocate 4096-byte aligned Direct I/O memory
        if (posix_memalign(&dma_buffer_, PAGE_SIZE, DIRECT_IO_BUFFER_SIZE) != 0) {
            throw std::runtime_error("posix_memalign failed for direct I/O buffer");
        }

        // Setup io_uring instance
        struct io_uring_params params;
        std::memset(&params, 0, sizeof(params));
        // Use kernel submission polling thread (IORING_SETUP_SQPOLL) to bypass syscalls
        params.flags = IORING_SETUP_SQPOLL | IORING_SETUP_CQSIZE;
        params.sq_thread_idle = 2000; // 2ms kernel poll idle window
        params.cq_entries = IOURING_ENTRIES * 2;

        if (io_uring_queue_init_params(IOURING_ENTRIES, &ring_, &params) < 0) {
            // Fallback without SQPOLL if lacking CAP_SYS_NICE or unprivileged
            if (io_uring_queue_init(IOURING_ENTRIES, &ring_, 0) < 0) {
                throw std::runtime_error("io_uring_queue_init failed");
            }
        }

        // Register fixed DMA buffers for zero-copy kernel transfers
        iovec iov[1];
        iov[0].iov_base = dma_buffer_;
        iov[0].iov_len = DIRECT_IO_BUFFER_SIZE;
        if (io_uring_register_buffers(&ring_, iov, 1) < 0) {
            throw std::runtime_error("io_uring_register_buffers failed");
        }
    }

    ~PipelinedIoUringWalEngine() {
        stop();
        io_uring_unregister_buffers(&ring_);
        io_uring_queue_exit(&ring_);
        free(dma_buffer_);
        if (fd_ >= 0) close(fd_);
    }

    void start(MPSCLogRing& ring_buffer) {
        running_.store(true, std::memory_order_release);
        daemon_thread_ = std::thread(&PipelinedIoUringWalEngine::persistence_loop, this, std::ref(ring_buffer));
    }

    void stop() {
        if (running_.exchange(false, std::memory_order_acq_rel)) {
            if (daemon_thread_.joinable()) {
                daemon_thread_.join();
            }
        }
    }

private:
    struct FlushContext {
        uint64_t max_lsn;
        size_t slots_count;
        uint64_t start_tail;
        size_t bytes_written;
    };

    void persistence_loop(MPSCLogRing& ring_buffer) {
        std::vector<MPSCQueueSlot*> batch;
        batch.reserve(2048);
        off_t file_offset = 0;

        while (running_.load(std::memory_order_relaxed)) {
            batch.clear();
            uint64_t start_tail = ring_buffer.get_tail();
            size_t count = ring_buffer.dequeue_batch(batch, 1024);

            if (count == 0) {
                harvest_completions(ring_buffer, false);
                _mm_pause();
                continue;
            }

            // Serialize batch into 4096B aligned DMA direct buffer
            char* dma_ptr = static_cast<char*>(dma_buffer_);
            size_t bytes_buffered = 0;
            uint64_t max_batch_lsn = 0;

            for (size_t i = 0; i < count; ++i) {
                MPSCQueueSlot* slot = batch[i];
                size_t record_len = sizeof(LogRecordHeader) + slot->header.val_len;

                if (bytes_buffered + record_len > DIRECT_IO_BUFFER_SIZE) {
                    break;
                }

                std::memcpy(dma_ptr + bytes_buffered, &slot->header, sizeof(LogRecordHeader));
                bytes_buffered += sizeof(LogRecordHeader);

                if (slot->header.val_len > 0) {
                    std::memcpy(dma_ptr + bytes_buffered, slot->payload, slot->header.val_len);
                    bytes_buffered += slot->header.val_len;
                }

                if (slot->header.lsn > max_batch_lsn) {
                    max_batch_lsn = slot->header.lsn;
                }
            }

            // Direct I/O requires 4096-byte alignment: pad remainder with zeroed bytes
            size_t aligned_bytes = (bytes_buffered + PAGE_SIZE - 1) & ~(PAGE_SIZE - 1);
            if (aligned_bytes > bytes_buffered) {
                std::memset(dma_ptr + bytes_buffered, 0, aligned_bytes - bytes_buffered);
            }

            // Submit IORING_OP_WRITE_FIXED
            struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
            while (!sqe) {
                // SQ is full: flush pipeline & harvest
                io_uring_submit(&ring_);
                harvest_completions(ring_buffer, true);
                sqe = io_uring_get_sqe(&ring_);
            }

            auto* ctx = new FlushContext{max_batch_lsn, count, start_tail, aligned_bytes};

            io_uring_prep_write_fixed(sqe, fd_, dma_buffer_, aligned_bytes, file_offset, 0 /* buf_index */);
            io_uring_sqe_set_data(sqe, ctx);

            file_offset += aligned_bytes;
            io_uring_submit(&ring_);

            // Harvest completions non-blocking
            harvest_completions(ring_buffer, false);
        }

        // Drain in-flight I/O requests during shutdown
        while (in_flight_ios_ > 0) {
            harvest_completions(ring_buffer, true);
        }
    }

    void harvest_completions(MPSCLogRing& ring_buffer, bool wait) {
        struct io_uring_cqe* cqe = nullptr;
        int ret = 0;

        if (wait) {
            ret = io_uring_wait_cqe(&ring_, &cqe);
        } else {
            ret = io_uring_peek_cqe(&ring_, &cqe);
        }

        while (ret == 0 && cqe != nullptr) {
            auto* ctx = static_cast<FlushContext*>(io_uring_cqe_get_data(cqe));

            if (cqe->res < 0) {
                // Short write or error handling under disk backpressure
                handle_io_error(cqe->res);
            } else {
                // Notify waiting transactions lock-free up to this durably flushed LSN
                completion_table_.notify_flushed(ctx->max_lsn);
                // Return slots to ring buffer
                ring_buffer.release_slots(ctx->slots_count, ctx->start_tail);
            }

            delete ctx;
            in_flight_ios_--;
            io_uring_cqe_seen(&ring_, cqe);

            cqe = nullptr;
            ret = io_uring_peek_cqe(&ring_, &cqe);
        }
    }

    void handle_io_error(int err_code) {
        // Under heavy disk backpressure / ENOSPC, log and retry or panic transactional kernel
        (void)err_code;
    }

    int fd_{-1};
    struct io_uring ring_{};
    void* dma_buffer_{nullptr};
    LsnCompletionTable& completion_table_;
    std::atomic<bool> running_{false};
    std::thread daemon_thread_;
    size_t in_flight_ios_{0};
};

} // namespace wal
