### 2. Stall-Resilient Epoch-Based Reclamation (Hybrid EBR + Hazard Pointer)

```cpp
#include <thread>
#include <vector>

inline constexpr size_t MAX_THREADS = 128;
inline constexpr size_t RETIRE_THRESHOLD = 256;
inline constexpr uint64_t EPOCH_STALL_BOUND_US = 5000; // 5ms maximum pinning allowance

struct alignas(CACHE_LINE_SIZE) ThreadEpochState {
    std::atomic<uint64_t> active_epoch{INF_TS}; // INF_TS indicates inactive/quiescent
    std::atomic<uint64_t> enter_time_us{0};     // For stall detection
    std::atomic<void*> hazard_ptr{nullptr};      // Emergency hazard slot for pinned nodes

    char pad[CACHE_LINE_SIZE - (sizeof(std::atomic<uint64_t>) * 2 + sizeof(std::atomic<void*>))];
};

class HybridEBR {
public:
    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
        uint64_t epoch_retired;
    };

    struct alignas(CACHE_LINE_SIZE) ThreadLocalQueue {
        std::vector<RetiredNode> retired_list;
        uint64_t ops_since_reclaim{0};
    };

private:
    std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHE_LINE_SIZE) std::array<ThreadEpochState, MAX_THREADS> thread_states_{};
    static thread_local size_t tl_thread_id;
    static thread_local ThreadLocalQueue tl_queue;

public:
    static HybridEBR& instance() {
        static HybridEBR ebr;
        return ebr;
    }

    static void register_thread(size_t id) {
        tl_thread_id = id % MAX_THREADS;
    }

    // Enter critical read region
    void enter() noexcept {
        const uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        auto& state = thread_states_[tl_thread_id];

        state.enter_time_us.store(get_now_us(), std::memory_order_relaxed);
        // Acquire barrier prevents speculative reads from escaping above the epoch entry
        state.active_epoch.store(g_epoch, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    // Exit critical read region
    void leave() noexcept {
        auto& state = thread_states_[tl_thread_id];
        state.hazard_ptr.store(nullptr, std::memory_order_relaxed);
        // Release barrier guarantees reads complete before thread becomes inactive
        state.active_epoch.store(INF_TS, std::memory_order_release);
    }

    // Set emergency hazard pointer protection if a thread is reading a specific old version
    void set_hazard(void* ptr) noexcept {
        thread_states_[tl_thread_id].hazard_ptr.store(ptr, std::memory_order_seq_cst);
    }

    void clear_hazard() noexcept {
        thread_states_[tl_thread_id].hazard_ptr.store(nullptr, std::memory_order_release);
    }

    template <typename T>
    void retire(T* ptr) {
        if (!ptr) return;
        auto& q = tl_queue;
        q.retired_list.push_back({
            ptr,
            [](void* obj) { T::destroy(static_cast<T*>(obj)); },
            global_epoch_.load(std::memory_order_relaxed)
        });

        if (++q.ops_since_reclaim >= RETIRE_THRESHOLD) {
            try_advance_and_reclaim();
            q.ops_since_reclaim = 0;
        }
    }

    void try_advance_and_reclaim() {
        uint64_t current_g = global_epoch_.load(std::memory_order_relaxed);
        uint64_t now = get_now_us();
        bool can_advance = true;

        for (size_t i = 0; i < MAX_THREADS; ++i) {
            uint64_t e = thread_states_[i].active_epoch.load(std::memory_order_acquire);
            if (e != INF_TS && e < current_g) {
                uint64_t entered = thread_states_[i].enter_time_us.load(std::memory_order_relaxed);
                if (now - entered > EPOCH_STALL_BOUND_US) {
                    // Straggler detected: Epoch progression is unblocked via fallback.
                    // Straggler is safe because its accesses rely on Hazard Pointers.
                } else {
                    can_advance = false;
                    break;
                }
            }
        }

        if (can_advance) {
            global_epoch_.compare_exchange_strong(current_g, current_g + 1, 
                                                 std::memory_order_acq_rel, 
                                                 std::memory_order_relaxed);
        }

        reclaim_local();
    }

    void reclaim_local() {
        auto& q = tl_queue;
        if (q.retired_list.empty()) return;

        // Determine the safe minimum active epoch across non-straggling readers
        uint64_t min_active = global_epoch_.load(std::memory_order_relaxed);
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            uint64_t e = thread_states_[i].active_epoch.load(std::memory_order_acquire);
            if (e < min_active) {
                min_active = e;
            }
        }

        // Collect all active hazard pointers
        std::array<void*, MAX_THREADS> active_hazards{};
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            active_hazards[i] = thread_states_[i].hazard_ptr.load(std::memory_order_acquire);
        }

        auto it = q.retired_list.begin();
        while (it != q.retired_list.end()) {
            // An object is safe to reclaim if it was retired strictly before the oldest active epoch
            // AND no thread is protecting it via emergency Hazard Pointer.
            if (it->epoch_retired < min_active) {
                bool protected_by_hazard = false;
                for (void* hz : active_hazards) {
                    if (hz == it->ptr) {
                        protected_by_hazard = true;
                        break;
                    }
                }

                if (!protected_by_hazard) {
                    it->deleter(it->ptr);
                    *it = q.retired_list.back();
                    q.retired_list.pop_back();
                    continue;
                }
            }
            ++it;
        }
    }

private:
    static uint64_t get_now_us() {
        auto now = std::chrono::steady_clock::now().time_since_epoch();
        return std::chrono::duration_cast<std::chrono::microseconds>(now).count();
    }
};

thread_local size_t HybridEBR::tl_thread_id = 0;
thread_local HybridEBR::ThreadLocalQueue HybridEBR::tl_queue{};
