### 3. Lock-Free MVCC Skip-List Implementation

```cpp
#include <random>

template <typename Key>
class LockFreeMVCCSkipList {
private:
    SkipNode<Key>* head_;
    std::atomic<uint32_t> max_level_{1};

    uint32_t generate_random_level() {
        static thread_local std::mt19937_64 rng(std::random_device{}());
        uint64_t r = rng();
        // Count trailing zeros: geometric distribution with p = 0.5
        uint32_t lvl = __builtin_ctzll(r | (1ULL << (MAX_SKIPLIST_LEVELS - 1))) + 1;
        return std::min(lvl, static_cast<uint32_t>(MAX_SKIPLIST_LEVELS));
    }

    bool find_position(const Key& key, 
                       SkipNode<Key>** preds, 
                       SkipNode<Key>** succs) {
    retry:
        SkipNode<Key>* pred = head_;
        for (int l = static_cast<int>(MAX_SKIPLIST_LEVELS) - 1; l >= 0; --l) {
            // Acquire order on traversing forward link ensures we observe consistent nodes
            SkipNode<Key>* curr = pred->forward[l].next.load(std::memory_order_acquire);
            while (true) {
                if (curr == nullptr) break;

                SkipNode<Key>* succ = curr->forward[l].next.load(std::memory_order_acquire);

                // Harris logical deletion check
                while (MarkedPtr<SkipNode<Key>>::is_marked(succ)) {
                    // Physical deletion: Unlink marked node using CAS on pred
                    SkipNode<Key>* clean_curr = MarkedPtr<SkipNode<Key>>::clean_mark(curr);
                    SkipNode<Key>* clean_succ = MarkedPtr<SkipNode<Key>>::clean_mark(succ);

                    if (!pred->forward[l].next.compare_exchange_strong(
                            clean_curr, clean_succ, 
                            std::memory_order_acq_rel, 
                            std::memory_order_acquire)) {
                        goto retry; // CAS failed; restart traversal
                    }

                    // Level-0 unlinking triggers EBR memory reclamation
                    if (l == 0) {
                        HybridEBR::instance().retire(clean_curr);
                    }

                    curr = clean_succ;
                    if (curr == nullptr) break;
                    succ = curr->forward[l].next.load(std::memory_order_acquire);
                }

                if (curr == nullptr || curr->key >= key) {
                    break;
                }
                pred = curr;
                curr = succ;
            }
            preds[l] = pred;
            succs[l] = curr;
        }
        return (succs[0] != nullptr && succs[0]->key == key);
    }

public:
    LockFreeMVCCSkipList() {
        head_ = SkipNode<Key>::create(Key{}, MAX_SKIPLIST_LEVELS);
    }

    ~LockFreeMVCCSkipList() {
        SkipNode<Key>* curr = head_->forward[0].next.load(std::memory_order_relaxed);
        while (curr) {
            SkipNode<Key>* next = MarkedPtr<SkipNode<Key>>::clean_mark(
                curr->forward[0].next.load(std::memory_order_relaxed));

            // Clean version chain
            VersionNode* v = curr->version_head.load(std::memory_order_relaxed);
            while (v) {
                VersionNode* vn = v->next_version.load(std::memory_order_relaxed);
                VersionNode::destroy(v);
                v = vn;
            }
            SkipNode<Key>::destroy(curr);
            curr = next;
        }
        SkipNode<Key>::destroy(head_);
    }

    // -----------------------------------------------------------------------------
    // Snapshot Isolation (SI) Read Traversal - Strictly Wait-Free O(1) per step
    // -----------------------------------------------------------------------------
    std::optional<std::string> search(const Key& key, uint64_t read_ts) {
        HybridEBR::instance().enter();

        SkipNode<Key>* pred = head_;
        SkipNode<Key>* curr = nullptr;

        for (int l = static_cast<int>(MAX_SKIPLIST_LEVELS) - 1; l >= 0; --l) {
            curr = pred->forward[l].next.load(std::memory_order_acquire);
            while (curr != nullptr) {
                curr = MarkedPtr<SkipNode<Key>>::clean_mark(curr);
                if (curr->key >= key) break;
                pred = curr;
                curr = curr->forward[l].next.load(std::memory_order_acquire);
            }
        }

        if (curr != nullptr && curr->key == key) {
            // Traverse descending version chain
            VersionNode* v = curr->version_head.load(std::memory_order_acquire);
            while (v != nullptr) {
                uint64_t c_ts = v->commit_ts.load(std::memory_order_acquire);

                // Visibility check: Version is committed AND visible at read_ts
                if (c_ts <= read_ts && c_ts != TX_ABORTED && c_ts != TX_ACTIVE) {
                    if (v->deleted_flag) {
                        HybridEBR::instance().leave();
                        return std::nullopt; // Tombstone visible
                    }
                    std::string result(v->value_payload, v->val_len);
                    HybridEBR::instance().leave();
                    return result;
                }
                v = v->next_version.load(std::memory_order_acquire);
            }
        }

        HybridEBR::instance().leave();
        return std::nullopt;
    }

    // -----------------------------------------------------------------------------
    // Upsert (Install Active MVCC Version)
    // -----------------------------------------------------------------------------
    bool upsert(const Key& key, const void* val_data, uint32_t val_len, uint64_t tx_id) {
        HybridEBR::instance().enter();
        SkipNode<Key>* preds[MAX_SKIPLIST_LEVELS];
        SkipNode<Key>* succs[MAX_SKIPLIST_LEVELS];

        SkipNode<Key>* target_node = nullptr;

        while (true) {
            if (find_position(key, preds, succs)) {
                target_node = succs[0];
                break;
            } else {
                // Key does not exist; instantiate new SkipNode with geometric height
                uint32_t node_height = generate_random_level();
                SkipNode<Key>* new_node = SkipNode<Key>::create(key, node_height);

                for (uint32_t i = 0; i < node_height; ++i) {
                    new_node->forward[i].next.store(succs[i], std::memory_order_relaxed);
                }

                // Link at Level 0
                if (!preds[0]->forward[0].next.compare_exchange_strong(
                        succs[0], new_node, 
                        std::memory_order_release, 
                        std::memory_order_acquire)) {
                    SkipNode<Key>::destroy(new_node);
                    continue; // Retry entire position search
                }

                // Link higher levels
                for (uint32_t i = 1; i < node_height; ++i) {
                    while (true) {
                        SkipNode<Key>* pred = preds[i];
                        SkipNode<Key>* succ = succs[i];
                        new_node->forward[i].next.store(succ, std::memory_order_relaxed);
                        if (pred->forward[i].next.compare_exchange_strong(
                                succ, new_node, 
                                std::memory_order_release, 
                                std::memory_order_acquire)) {
                            break;
                        }
                        find_position(key, preds, succs);
                    }
                }
                target_node = new_node;
                break;
            }
        }

        // Install newly created uncommitted version at head of version chain
        VersionNode* new_ver = VersionNode::create(tx_id, TX_ACTIVE, false, val_data, val_len);

        while (true) {
            VersionNode* current_head = target_node->version_head.load(std::memory_order_acquire);

            // Write-Write Conflict Detection:
            // If the latest version is still TX_ACTIVE, another active tx holds the write lock
            if (current_head != nullptr) {
                uint64_t head_ts = current_head->commit_ts.load(std::memory_order_acquire);
                if (head_ts == TX_ACTIVE) {
                    VersionNode::destroy(new_ver);
                    HybridEBR::instance().leave();
                    return false; // WW conflict -> First-Committer-Wins abort
                }
            }

            new_ver->next_version.store(current_head, std::memory_order_relaxed);

            // CAS to install new version at the head of the chain
            if (target_node->version_head.compare_exchange_strong(
                    current_head, new_ver, 
                    std::memory_order_release, 
                    std::memory_order_acquire)) {
                HybridEBR::instance().leave();
                return true;
            }
        }
    }

    // -----------------------------------------------------------------------------
    // Commit Version
    // -----------------------------------------------------------------------------
    bool commit_version(const Key& key, uint64_t tx_id, uint64_t commit_ts) {
        HybridEBR::instance().enter();
        SkipNode<Key>* preds[MAX_SKIPLIST_LEVELS];
        SkipNode<Key>* succs[MAX_SKIPLIST_LEVELS];

        if (!find_position(key, preds, succs)) {
            HybridEBR::instance().leave();
            return false;
        }

        SkipNode<Key>* node = succs[0];
        VersionNode* v = node->version_head.load(std::memory_order_acquire);

        while (v != nullptr) {
            if (v->tx_id == tx_id) {
                uint64_t expected = TX_ACTIVE;
                // Atomic transition from ACTIVE to committed timestamp
                bool success = v->commit_ts.compare_exchange_strong(
                    expected, commit_ts, 
                    std::memory_order_release, 
                    std::memory_order_relaxed);
                HybridEBR::instance().leave();
                return success;
            }
            v = v->next_version.load(std::memory_order_acquire);
        }

        HybridEBR::instance().leave();
        return false;
    }

    // -----------------------------------------------------------------------------
    // Logical Version Pruning: Unlink versions older than global minimum SI read timestamp
    // -----------------------------------------------------------------------------
    void prune_versions(const Key& key, uint64_t global_watermark_ts) {
        HybridEBR::instance().enter();
        SkipNode<Key>* preds[MAX_SKIPLIST_LEVELS];
        SkipNode<Key>* succs[MAX_SKIPLIST_LEVELS];

        if (!find_position(key, preds, succs)) {
            HybridEBR::instance().leave();
            return;
        }

        SkipNode<Key>* node = succs[0];
        VersionNode* curr = node->version_head.load(std::memory_order_acquire);

        VersionNode* first_visible_old = nullptr;

        while (curr != nullptr) {
            uint64_t ts = curr->commit_ts.load(std::memory_order_acquire);
            if (ts <= global_watermark_ts && ts != TX_ACTIVE && ts != TX_ABORTED) {
                if (first_visible_old == nullptr) {
                    first_visible_old = curr;
                } else {
                    // Everything behind first_visible_old is obsolete and can be pruned
                    VersionNode* stale_chain = first_visible_old->next_version.exchange(
                        nullptr, std::memory_order_acq_rel);

                    while (stale_chain != nullptr) {
                        VersionNode* next = stale_chain->next_version.load(std::memory_order_relaxed);
                        HybridEBR::instance().retire(stale_chain);
                        stale_chain = next;
                    }
                    break;
                }
            }
            curr = curr->next_version.load(std::memory_order_acquire);
        }

        HybridEBR::instance().leave();
    }
};
