## Part 2: Kernel-Bypass Async WAL Subsystem via `io_uring`

### 1. Lock-Free MPSC Ring Buffer Layout

```cpp
#include <fcntl.h>
#include <unistd.h>
#include <sys/uio.h>
#include <liburing.h>
#include <immintrin.h>

inline constexpr size_t RING_BUFFER_CAPACITY = 65536; // 64K log slots
inline constexpr size_t BLOCK_SIZE = 4096;
inline constexpr size_t MAX_IO_BATCH_PAGES = 32;      // 128KB batch

#pragma pack(push, 1)
struct LogHeader {
    uint64_t lsn;
    uint64_t tx_id;
    uint32_t key_len;
    uint32_t val_len;
    uint32_t crc32c;
    char payload[0];
};
#pragma pack(pop)

struct alignas(CACHE_LINE_SIZE) MPSCLogSlot {
    std::atomic<uint32_t> ready_flag{0}; // 0 = empty, 1 = writing, 2 = commit ready
    uint32_t total_size{0};
    alignas(16) char buffer[512 - sizeof(std::atomic<uint32_t>) - sizeof(uint32_t)];
};

class LockFreeMPSCWALRing {
private:
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> write_index_{0};
    char pad0[CACHE_LINE_SIZE - sizeof(std::atomic<uint64_t>)];

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> read_index_{0};
    char pad1[CACHE_LINE_SIZE - sizeof(std::atomic<uint64_t>)];

    std::array<MPSCLogSlot, RING_BUFFER_CAPACITY> slots_{};

public:
    LockFreeMPSCWALRing() = default;

    // Zero-Copy Enqueue by Multi-Producers
    bool enqueue(uint64_t lsn, uint64_t tx_id, const void* key, uint32_t klen, 
                 const void* val, uint32_t vlen, uint64_t& allocated_idx) {
        uint32_t payload_len = sizeof(LogHeader) + klen + vlen;
        if (payload_len > sizeof(MPSCLogSlot::buffer)) {
            return false; // Record exceeds inline slot buffer
        }

        uint64_t slot_idx = write_index_.fetch_add(1, std::memory_order_acq_rel);
        uint64_t current_read = read_index_.load(std::memory_order_relaxed);

        if (slot_idx >= current_read + RING_BUFFER_CAPACITY) {
            // Buffer full condition
            return false;
        }

        allocated_idx = slot_idx;
        MPSCLogSlot& slot = slots_[slot_idx % RING_BUFFER_CAPACITY];

        // Indicate producer is actively serializing into the slot
        slot.ready_flag.store(1, std::memory_order_relaxed);

        auto* hdr = reinterpret_cast<LogHeader*>(slot.buffer);
        hdr->lsn = lsn;
        hdr->tx_id = tx_id;
        hdr->key_len = klen;
        hdr->val_len = vlen;

        std::memcpy(hdr->payload, key, klen);
        std::memcpy(hdr->payload + klen, val, vlen);

        // Hardware accelerated CRC32C computation
        uint32_t crc = 0;
        const auto* ptr = reinterpret_cast<const uint8_t*>(hdr->payload);
        for (size_t i = 0; i < (klen + vlen); ++i) {
            crc = _mm_crc32_u8(crc, ptr[i]);
        }
        hdr->crc32c = crc;

        slot.total_size = payload_len;
        // Release barrier guarantees payload write completes before ready_flag is marked done
        slot.ready_flag.store(2, std::memory_order_release);
        return true;
    }

    // Single Consumer Draining
    bool dequeue_slot(uint64_t idx, void* dest, uint32_t& out_size) {
        MPSCLogSlot& slot = slots_[idx % RING_BUFFER_CAPACITY];

        // Wait until producer completes writing
        if (slot.ready_flag.load(std::memory_order_acquire) != 2) {
            return false;
        }

        out_size = slot.total_size;
        std::memcpy(dest, slot.buffer, out_size);

        slot.ready_flag.store(0, std::memory_order_release);
        read_index_.store(idx + 1, std::memory_order_release);
        return true;
    }

    uint64_t get_tail() const noexcept {
        return write_index_.load(std::memory_order_acquire);
    }

    uint64_t get_head() const noexcept {
        return read_index_.load(std::memory_order_acquire);
    }
};
