### 2. Pipelined `io_uring` Direct-I/O WAL Subsystem

```cpp
#include <sys/mman.h>

class AsyncIOUringWALEngine {
private:
    struct io_uring ring_{};
    int wal_fd_{-1};
    uint64_t file_offset_{0};

    // Aligned Direct I/O buffers registered with io_uring
    void* direct_io_buffer_{nullptr};
    size_t buffer_size_{BLOCK_SIZE * MAX_IO_BATCH_PAGES};
    struct iovec iov_registered_{};

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> flushed_lsn_{0};
    std::atomic<bool> running_{false};
    std::thread daemon_thread_;

    LockFreeMPSCWALRing& ring_buffer_;

public:
    AsyncIOUringWALEngine(const char* wal_path, LockFreeMPSCWALRing& ring_buf)
        : ring_buffer_(ring_buf) {
        // Open file with O_DIRECT | O_SYNC | O_RDWR
        wal_fd_ = ::open(wal_path, O_DIRECT | O_SYNC | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (wal_fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT");
        }

        // Initialize io_uring with SQPOLL to bypass kernel context switches
        struct io_uring_params params{};
        params.flags = IORING_SETUP_SQPOLL | IORING_SETUP_CQSIZE;
        params.sq_thread_idle = 2000; // 2ms idle before sleeping
        params.cq_entries = 1024;

        if (io_uring_queue_init_params(512, &ring_, &params) < 0) {
            // Fallback to standard io_uring if SQPOLL privileges (CAP_SYS_NICE) are restricted
            io_uring_queue_init(512, &ring_, 0);
        }

        // Allocate page-aligned memory for O_DIRECT zero-copy writes
        if (::posix_memalign(&direct_io_buffer_, BLOCK_SIZE, buffer_size_) != 0) {
            throw std::bad_alloc();
        }

        iov_registered_.iov_base = direct_io_buffer_;
        iov_registered_.iov_len = buffer_size_;

        // Register buffers to lock physical pages into kernel map
        if (io_uring_register_buffers(&ring_, &iov_registered_, 1) < 0) {
            throw std::runtime_error("Failed to register fixed buffers with io_uring");
        }
    }

    ~AsyncIOUringWALEngine() {
        stop();
        io_uring_unregister_buffers(&ring_);
        io_uring_queue_exit(&ring_);
        if (wal_fd_ >= 0) ::close(wal_fd_);
        if (direct_io_buffer_) ::free(direct_io_buffer_);
    }

    void start() {
        running_.store(true, std::memory_order_relaxed);
        daemon_thread_ = std::thread(&AsyncIOUringWALEngine::daemon_loop, this);
    }

    void stop() {
        if (running_.exchange(false, std::memory_order_relaxed)) {
            if (daemon_thread_.joinable()) {
                daemon_thread_.join();
            }
        }
    }

    // Wait-free check or lightweight backoff wait for transaction commit durability
    void await_lsn_durable(uint64_t target_lsn) const noexcept {
        while (flushed_lsn_.load(std::memory_order_acquire) < target_lsn) {
            _mm_pause(); // Low-latency SMT pause instruction
        }
    }

private:
    void daemon_loop() {
        char temp_slot_buf[512];
        uint32_t bytes_drained = 0;
        uint64_t max_batch_lsn = 0;
        uint64_t current_read_idx = ring_buffer_.get_head();

        while (running_.load(std::memory_order_relaxed)) {
            bytes_drained = 0;
            max_batch_lsn = 0;
            auto* target_ptr = static_cast<char*>(direct_io_buffer_);

            // Batch up to buffer_size_ or until ring buffer is empty
            while (bytes_drained + sizeof(temp_slot_buf) <= buffer_size_) {
                uint32_t record_len = 0;
                if (!ring_buffer_.dequeue_slot(current_read_idx, temp_slot_buf, record_len)) {
                    break;
                }

                auto* hdr = reinterpret_cast<LogHeader*>(temp_slot_buf);
                if (hdr->lsn > max_batch_lsn) {
                    max_batch_lsn = hdr->lsn;
                }

                std::memcpy(target_ptr + bytes_drained, temp_slot_buf, record_len);
                bytes_drained += record_len;
                current_read_idx++;
            }

            if (bytes_drained == 0) {
                // Adaptive spinning backoff
                _mm_pause();
                continue;
            }

            // O_DIRECT requires write size to be an exact multiple of 4096 (BLOCK_SIZE)
            size_t aligned_flush_size = (bytes_drained + BLOCK_SIZE - 1) & ~(BLOCK_SIZE - 1);
            // Zero-pad remainder of the last 4KB sector
            std::memset(target_ptr + bytes_drained, 0, aligned_flush_size - bytes_drained);

            submit_direct_write(aligned_flush_size, max_batch_lsn);
            harvest_completions();
        }
    }

    void submit_direct_write(size_t write_bytes, uint64_t batch_max_lsn) {
        struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
        while (!sqe) {
            // SQ ring full: submit in-flight requests and retry
            io_uring_submit(&ring_);
            sqe = io_uring_get_sqe(&ring_);
        }

        // Zero-copy registered fixed-buffer write
        io_uring_prep_write_fixed(sqe, wal_fd_, direct_io_buffer_, write_bytes, file_offset_, 0);
        sqe->user_data = batch_max_lsn;

        file_offset_ += write_bytes;
        io_uring_submit(&ring_);
    }

    void harvest_completions() {
        struct io_uring_cqe* cqe = nullptr;
        // Non-blocking drain of CQ ring
        while (io_uring_peek_cqe(&ring_, &cqe) == 0) {
            if (cqe->res < 0) {
                // I/O write error handling
                handle_io_error(cqe->res);
            } else {
                uint64_t completed_lsn = cqe->user_data;
                // Atomic notification for transactions waiting on commit promises
                uint64_t current = flushed_lsn_.load(std::memory_order_relaxed);
                while (completed_lsn > current && 
                       !flushed_lsn_.compare_exchange_weak(current, completed_lsn, 
                                                           std::memory_order_release, 
                                                           std::memory_order_relaxed)) {
                    // Retry updating highest durable LSN
                }
            }
            io_uring_cqe_seen(&ring_, cqe);
        }
    }

    void handle_io_error(int err_code) {
        // Production error recovery: fsync fallbacks, write stall alerting, or panic recovery
        (void)err_code;
    }
};
```

