### Complete C++20 Implementation

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <string_view>
#include <memory>
#include <atomic>
#include <thread>
#include <future>
#include <chrono>
#include <cstring>
#include <cstdint>
#include <cassert>
#include <optional>
#include <random>
#include <array>
#include <functional>
#include <span>
#include <mutex>
#include <condition_variable>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/uio.h>
#include <sys/syscall.h>
#include <linux/fs.h>
#include <x86intrin.h>

#if __has_include(<liburing.h>)
#include <liburing.h>
#define HAS_LIBURING 1
#else
#define HAS_LIBURING 0
#endif

// ============================================================================
// 0. HARDWARE CONSTANTS & CACHE ALIGNMENT
// ============================================================================

#ifndef __cpp_lib_hardware_interference_size
namespace std {
    constexpr size_t hardware_destructive_interference_size = 64;
    constexpr size_t hardware_constructive_interference_size = 64;
}
#endif

constexpr size_t CACHE_LINE_SIZE = std::hardware_destructive_interference_size;
constexpr size_t WAL_SECTOR_SIZE = 4096; // Standard O_DIRECT sector alignment
constexpr uint32_t WAL_MAGIC = 0x57414C30; // 'WAL0'
constexpr size_t MAX_SKIPLIST_LEVELS = 16;
constexpr double SKIPLIST_P = 0.5;

// ============================================================================
// 1. FAST HARDWARE CRC32C CHECKSUM
// ============================================================================

inline uint32_t CalculateCRC32C(const uint8_t* data, size_t length, uint32_t prev_crc = 0xFFFFFFFF) {
    uint32_t crc = ~prev_crc;
    size_t i = 0;
    while (i + 8 <= length) {
        uint64_t val;
        std::memcpy(&val, data + i, 8);
        crc = static_cast<uint32_t>(_mm_crc32_u64(crc, val));
        i += 8;
    }
    while (i < length) {
        crc = _mm_crc32_u8(crc, data[i]);
        i++;
    }
    return ~crc;
}

// ============================================================================
// 2. EPOCH-BASED MEMORY RECLAMATION (EBR)
// ============================================================================

struct alignas(CACHE_LINE_SIZE) ThreadEpochState {
    std::atomic<uint64_t> active_epoch{0};
    std::atomic<bool> is_active{false};
    ThreadEpochState* next{nullptr};
};

class EpochManager {
public:
    static constexpr uint64_t INACTIVE = 0;
    static constexpr size_t RETIREMENT_THRESHOLD = 256;

    struct RetiredObject {
        void* ptr;
        void (*deleter)(void*);
        RetiredObject* next;
    };

    struct ThreadRetireQueue {
        std::array<RetiredObject*, 3> epoch_buckets{nullptr, nullptr, nullptr};
        size_t count{0};
    };

    static EpochManager& Instance() {
        static EpochManager manager;
        return manager;
    }

    void RegisterThread() {
        if (local_state_) return;
        local_state_ = new ThreadEpochState();
        ThreadEpochState* head = global_threads_.load(std::memory_order_relaxed);
        do {
            local_state_->next = head;
        } while (!global_threads_.compare_exchange_weak(
            head, local_state_, std::memory_order_release, std::memory_order_relaxed));
    }

    void Enter() {
        assert(local_state_ && "Thread not registered in EpochManager");
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);
        local_state_->active_epoch.store(current, std::memory_order_release);
        local_state_->is_active.store(true, std::memory_order_release);
    }

    void Exit() {
        assert(local_state_ && "Thread not registered in EpochManager");
        local_state_->is_active.store(false, std::memory_order_release);
        local_state_->active_epoch.store(INACTIVE, std::memory_order_relaxed);

        if (local_retire_queue_.count >= RETIREMENT_THRESHOLD) {
            TryAdvanceAndReclaim();
        }
    }

    template <typename T>
    void Retire(T* ptr) {
        if (!ptr) return;
        auto* obj = new RetiredObject{
            ptr,
            [](void* p) { delete static_cast<T*>(p); },
            nullptr
        };
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t bucket_idx = cur_epoch % 3;

        obj->next = local_retire_queue_.epoch_buckets[bucket_idx];
        local_retire_queue_.epoch_buckets[bucket_idx] = obj;
        local_retire_queue_.count++;
    }

    void TryAdvanceAndReclaim() {
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);

        // Scan all threads to verify if everyone has reached 'current'
        ThreadEpochState* curr = global_threads_.load(std::memory_order_acquire);
        bool can_advance = true;
        while (curr) {
            if (curr->is_active.load(std::memory_order_acquire)) {
                uint64_t thread_epoch = curr->active_epoch.load(std::memory_order_acquire);
                if (thread_epoch < current) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next;
        }

        if (can_advance) {
            if (global_epoch_.compare_exchange_strong(current, current + 1,
                                                      std::memory_order_acq_rel,
                                                      std::memory_order_relaxed)) {
                // Reclaim the bucket from 2 epochs ago: (current + 1) % 3
                size_t reclaim_idx = (current + 1) % 3;
                FreeBucket(local_retire_queue_.epoch_buckets[reclaim_idx]);
                local_retire_queue_.epoch_buckets[reclaim_idx] = nullptr;
            }
        }
    }

    uint64_t GetMinActiveEpoch() const {
        uint64_t min_epoch = global_epoch_.load(std::memory_order_acquire);
        ThreadEpochState* curr = global_threads_.load(std::memory_order_acquire);
        while (curr) {
            if (curr->is_active.load(std::memory_order_acquire)) {
                uint64_t thread_epoch = curr->active_epoch.load(std::memory_order_acquire);
                if (thread_epoch != INACTIVE && thread_epoch < min_epoch) {
                    min_epoch = thread_epoch;
                }
            }
            curr = curr->next;
        }
        return min_epoch;
    }

private:
    EpochManager() : global_epoch_(1), global_threads_(nullptr) {}

    void FreeBucket(RetiredObject* head) {
        while (head) {
            RetiredObject* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
            local_retire_queue_.count--;
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_;
    alignas(CACHE_LINE_SIZE) std::atomic<ThreadEpochState*> global_threads_;
    static thread_local ThreadEpochState* local_state_;
    static thread_local ThreadRetireQueue local_retire_queue_;
};

thread_local ThreadEpochState* EpochManager::local_state_ = nullptr;
thread_local EpochManager::ThreadRetireQueue EpochManager::local_retire_queue_;

struct EpochGuard {
    EpochGuard() {
        EpochManager::Instance().RegisterThread();
        EpochManager::Instance().Enter();
    }
    ~EpochGuard() {
        EpochManager::Instance().Exit();
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// 3. LOCK-FREE MVCC SKIPLIST WITH MARKED POINTERS
// ============================================================================

template <typename T>
class MarkedPtr {
    uintptr_t ptr_{0};
    static constexpr uintptr_t MARK_MASK = 1ULL;
    static constexpr uintptr_t PTR_MASK = ~MARK_MASK;

public:
    constexpr MarkedPtr() noexcept : ptr_(0) {}
    constexpr MarkedPtr(T* p, bool mark = false) noexcept
        : ptr_(reinterpret_cast<uintptr_t>(p) | (mark ? MARK_MASK : 0)) {}

    T* Get() const noexcept { return reinterpret_cast<T*>(ptr_ & PTR_MASK); }
    bool IsMarked() const noexcept { return (ptr_ & MARK_MASK) != 0; }
    uintptr_t Raw() const noexcept { return ptr_; }
};

struct VersionNode {
    uint64_t commit_ts;
    bool is_tombstone;
    std::string value;
    std::atomic<VersionNode*> next{nullptr};

    VersionNode(uint64_t ts, bool tombstone, std::string val)
        : commit_ts(ts), is_tombstone(tombstone), value(std::move(val)) {}
};

struct SkipListNode {
    std::string key;
    std::atomic<VersionNode*> version_head{nullptr};
    size_t height;
    std::atomic<MarkedPtr<SkipListNode>> forward[1]; // Flexible array member

    static SkipListNode* Create(std::string_view key, size_t height) {
        size_t size = sizeof(SkipListNode) + (height - 1) * sizeof(std::atomic<MarkedPtr<SkipListNode>>);
        void* mem = ::operator new(size);
        return new (mem) SkipListNode(key, height);
    }

    static void Destroy(SkipListNode* node) {
        if (!node) return;
        // Clean up version nodes
        VersionNode* v = node->version_head.load(std::memory_order_relaxed);
        while (v) {
            VersionNode* next = v->next.load(std::memory_order_relaxed);
            delete v;
            v = next;
        }
        node->~SkipListNode();
        ::operator delete(node);
    }

private:
    SkipListNode(std::string_view k, size_t h) : key(k), height(h) {
        for (size_t i = 0; i < height; ++i) {
            forward[i].store(MarkedPtr<SkipListNode>(nullptr, false), std::memory_order_relaxed);
        }
    }
    ~SkipListNode() = default;
};

class MVCCSkipList {
public:
    MVCCSkipList() : head_(SkipListNode::Create("", MAX_SKIPLIST_LEVELS)) {}

    ~MVCCSkipList() {
        SkipListNode* curr = head_->forward[0].load(std::memory_order_relaxed).Get();
        while (curr) {
            SkipListNode* next = curr->forward[0].load(std::memory_order_relaxed).Get();
            SkipListNode::Destroy(curr);
            curr = next;
        }
        SkipListNode::Destroy(head_);
    }

    std::optional<std::string> Get(std::string_view key, uint64_t read_ts) {
        EpochGuard guard;
        SkipListNode* node = FindNode(key);
        if (!node) return std::nullopt;

        // Traverse version chain (descending by commit_ts)
        VersionNode* v = node->version_head.load(std::memory_order_acquire);
        while (v) {
            if (v->commit_ts <= read_ts) {
                if (v->is_tombstone) return std::nullopt;
                return v->value;
            }
            v = v->next.load(std::memory_order_acquire);
        }
        return std::nullopt;
    }

    bool Put(std::string_view key, std::string_view value, uint64_t commit_ts, bool is_tombstone = false) {
        EpochGuard guard;
        SkipListNode* node = GetOrInsertNode(key);
        assert(node != nullptr);

        auto* new_version = new VersionNode(commit_ts, is_tombstone, std::string(value));
        VersionNode* current_head = node->version_head.load(std::memory_order_acquire);

        while (true) {
            // First-Committer-Wins validation
            if (current_head != nullptr && current_head->commit_ts >= commit_ts) {
                delete new_version;
                return false; // Write-Write conflict
            }
            new_version->next.store(current_head, std::memory_order_relaxed);
            if (node->version_head.compare_exchange_weak(
                    current_head, new_version,
                    std::memory_order_release,
                    std::memory_order_acquire)) {
                return true;
            }
        }
    }

    std::vector<std::pair<std::string, std::string>> Scan(std::string_view start_key,
                                                         std::string_view end_key,
                                                         uint64_t read_ts) {
        EpochGuard guard;
        std::vector<std::pair<std::string, std::string>> results;
        SkipListNode* preds[MAX_SKIPLIST_LEVELS];
        SkipListNode* succs[MAX_SKIPLIST_LEVELS];

        FindWindow(start_key, preds, succs);
        SkipListNode* curr = succs[0];

        while (curr) {
            if (!end_key.empty() && curr->key >= end_key) break;

            VersionNode* v = curr->version_head.load(std::memory_order_acquire);
            while (v) {
                if (v->commit_ts <= read_ts) {
                    if (!v->is_tombstone) {
                        results.emplace_back(curr->key, v->value);
                    }
                    break;
                }
                v = v->next.load(std::memory_order_acquire);
            }

            MarkedPtr<SkipListNode> succ = curr->forward[0].load(std::memory_order_acquire);
            while (succ.IsMarked()) {
                // Node logically deleted, help advance
                FindWindow(curr->key, preds, succs);
                curr = succs[0];
                if (!curr) break;
                succ = curr->forward[0].load(std::memory_order_acquire);
            }
            curr = succ.Get();
        }
        return results;
    }

    void PruneOldVersions(uint64_t min_active_ts) {
        EpochGuard guard;
        SkipListNode* curr = head_->forward[0].load(std::memory_order_acquire).Get();
        while (curr) {
            VersionNode* v = curr->version_head.load(std::memory_order_acquire);
            VersionNode* prev = nullptr;
            bool found_baseline = false;

            while (v) {
                VersionNode* next = v->next.load(std::memory_order_acquire);
                if (v->commit_ts < min_active_ts) {
                    if (!found_baseline) {
                        // Keep the single most recent version strictly below min_active_ts
                        found_baseline = true;
                        prev = v;
                    } else {
                        // Unlink all subsequent versions older than min_active_ts
                        if (prev) {
                            prev->next.store(nullptr, std::memory_order_release);
                        }
                        // Retire obsolete versions through EBR
                        VersionNode* to_retire = v;
                        while (to_retire) {
                            VersionNode* n = to_retire->next.load(std::memory_order_relaxed);
                            EpochManager::Instance().Retire(to_retire);
                            to_retire = n;
                        }
                        break;
                    }
                } else {
                    prev = v;
                }
                v = next;
            }
            curr = curr->forward[0].load(std::memory_order_acquire).Get();
        }
    }

private:
    size_t RandomHeight() {
        thread_local std::mt19937_64 rng(std::random_device{}());
        thread_local std::uniform_real_distribution<double> dist(0.0, 1.0);
        size_t h = 1;
        while (h < MAX_SKIPLIST_LEVELS && dist(rng) < SKIPLIST_P) {
            h++;
        }
        return h;
    }

    bool FindWindow(std::string_view key, SkipListNode* preds[], SkipListNode* succs[]) {
    retry:
        SkipListNode* pred = head_;
        for (int level = static_cast<int>(MAX_SKIPLIST_LEVELS) - 1; level >= 0; --level) {
            MarkedPtr<SkipListNode> curr = pred->forward[level].load(std::memory_order_acquire);
            while (true) {
                if (!curr.Get()) break;
                MarkedPtr<SkipListNode> succ = curr.Get()->forward[level].load(std::memory_order_acquire);

                // Physical deletion assistance for marked nodes
                while (succ.IsMarked()) {
                    MarkedPtr<SkipListNode> expected = MarkedPtr<SkipListNode>(curr.Get(), false);
                    if (!pred->forward[level].compare_exchange_weak(
                            expected, MarkedPtr<SkipListNode>(succ.Get(), false),
                            std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }
                    curr = succ;
                    if (!curr.Get()) break;
                    succ = curr.Get()->forward[level].load(std::memory_order_acquire);
                }

                if (!curr.Get() || curr.Get()->key >= key) {
                    break;
                }
                pred = curr.Get();
                curr = succ;
            }
            preds[level] = pred;
            succs[level] = curr.Get();
        }
        return (succs[0] != nullptr && succs[0]->key == key);
    }

    SkipListNode* FindNode(std::string_view key) {
        SkipListNode* preds[MAX_SKIPLIST_LEVELS];
        SkipListNode* succs[MAX_SKIPLIST_LEVELS];
        if (FindWindow(key, preds, succs)) {
            return succs[0];
        }
        return nullptr;
    }

    SkipListNode* GetOrInsertNode(std::string_view key) {
        SkipListNode* preds[MAX_SKIPLIST_LEVELS];
        SkipListNode* succs[MAX_SKIPLIST_LEVELS];
        size_t new_height = RandomHeight();
        SkipListNode* new_node = nullptr;

        while (true) {
            if (FindWindow(key, preds, succs)) {
                if (new_node) SkipListNode::Destroy(new_node);
                return succs[0]; // Node exists
            }

            if (!new_node) {
                new_node = SkipListNode::Create(key, new_height);
            }

            for (size_t i = 0; i < new_height; ++i) {
                new_node->forward[i].store(MarkedPtr<SkipListNode>(succs[i], false), std::memory_order_relaxed);
            }

            MarkedPtr<SkipListNode> expected = MarkedPtr<SkipListNode>(succs[0], false);
            MarkedPtr<SkipListNode> desired = MarkedPtr<SkipListNode>(new_node, false);

            if (!preds[0]->forward[0].compare_exchange_strong(
                    expected, desired, std::memory_order_release, std::memory_order_acquire)) {
                continue; // Retry search window
            }

            // Splice remaining levels
            for (size_t i = 1; i < new_height; ++i) {
                while (true) {
                    SkipListNode* pred = preds[i];
                    SkipListNode* succ = succs[i];
                    new_node->forward[i].store(MarkedPtr<SkipListNode>(succ, false), std::memory_order_relaxed);
                    expected = MarkedPtr<SkipListNode>(succ, false);
                    desired = MarkedPtr<SkipListNode>(new_node, false);
                    if (pred->forward[i].compare_exchange_weak(
                            expected, desired, std::memory_order_release, std::memory_order_acquire)) {
                        break;
                    }
                    FindWindow(key, preds, succs);
                }
            }
            return new_node;
        }
    }

    SkipListNode* head_;
};

// ============================================================================
// 4. ZERO-COPY `io_uring` WRITE-AHEAD LOG (WAL) ENGINE
// ============================================================================

enum class WALRecordType : uint8_t {
    PUT = 1,
    DELETE = 2,
    TXN_COMMIT = 3
};

#pragma pack(push, 1)
struct WALRecordHeader {
    uint32_t magic;
    uint32_t payload_len;
    uint64_t lsn;
    uint64_t commit_ts;
    uint8_t  record_type;
    uint32_t key_len;
    uint32_t value_len;
    uint32_t crc32c;
};
#pragma pack(pop)

struct WALRecord {
    uint64_t lsn;
    uint64_t commit_ts;
    WALRecordType type;
    std::string key;
    std::string value;
    std::promise<void>* sync_promise{nullptr};
};

class AsyncWALEngine {
public:
    static constexpr size_t RING_ENTRIES = 1024;
    static constexpr size_t NUM_BUFFERS = 32;
    static constexpr size_t BUFFER_SIZE = 64 * 1024; // 64KB per buffer

    AsyncWALEngine(const std::string& log_path) : log_path_(log_path), running_(true) {
        // Open file with O_DIRECT | O_RDWR | O_CREAT
        fd_ = open(log_path.c_str(), O_DIRECT | O_RDWR | O_CREAT, 0644);
        if (fd_ < 0) {
            // Fallback for filesystems not supporting O_DIRECT in tests (e.g. tmpfs)
            fd_ = open(log_path.c_str(), O_RDWR | O_CREAT, 0644);
            direct_io_supported_ = false;
        } else {
            direct_io_supported_ = true;
        }
        assert(fd_ >= 0 && "Failed to open WAL file");

        InitBuffers();
        InitIOUring();

        flusher_thread_ = std::thread(&AsyncWALEngine::FlusherLoop, this);
    }

    ~AsyncWALEngine() {
        running_.store(false, std::memory_order_release);
        cv_.notify_all();
        if (flusher_thread_.joinable()) {
            flusher_thread_.join();
        }

        CleanupIOUring();
        FreeBuffers();

        if (fd_ >= 0) {
            ::close(fd_);
        }
    }

    std::future<void> AppendRecord(uint64_t commit_ts, WALRecordType type,
                                  std::string_view key, std::string_view value) {
        auto* promise = new std::promise<void>();
        std::future<void> fut = promise->get_future();

        uint64_t lsn = next_lsn_.fetch_add(1, std::memory_order_relaxed);

        WALRecord rec{
            lsn,
            commit_ts,
            type,
            std::string(key),
            std::string(value),
            promise
        };

        {
            std::lock_guard<std::mutex> lock(queue_mutex_);
            mpsc_queue_.push_back(std::move(rec));
        }
        cv_.notify_one();
        return fut;
    }

    std::vector<WALRecord> Recover() {
        std::vector<WALRecord> recovered;
        int read_fd = open(log_path_.c_str(), O_RDONLY);
        if (read_fd < 0) return recovered;

        std::vector<uint8_t> buffer(BUFFER_SIZE);
        uint64_t expected_lsn = 1;
        off_t file_offset = 0;

        while (true) {
            ssize_t bytes_read = pread(read_fd, buffer.data(), BUFFER_SIZE, file_offset);
            if (bytes_read <= 0) break;

            size_t offset = 0;
            while (offset + sizeof(WALRecordHeader) <= static_cast<size_t>(bytes_read)) {
                const auto* hdr = reinterpret_cast<const WALRecordHeader*>(buffer.data() + offset);

                if (hdr->magic != WAL_MAGIC) {
                    // Reached unwritten / zeroed sector
                    goto recovery_done;
                }

                size_t total_rec_size = sizeof(WALRecordHeader) + hdr->key_len + hdr->value_len;
                if (offset + total_rec_size > static_cast<size_t>(bytes_read)) {
                    // Incomplete block write at EOF
                    goto recovery_done;
                }

                // Verify CRC32C checksum
                const uint8_t* payload_ptr = buffer.data() + offset + sizeof(WALRecordHeader);
                uint32_t computed_crc = CalculateCRC32C(payload_ptr, hdr->key_len + hdr->value_len);
                if (computed_crc != hdr->crc32c) {
                    // Corrupted or torn write detected, truncate log here
                    goto recovery_done;
                }

                if (hdr->lsn != expected_lsn) {
                    goto recovery_done;
                }

                WALRecord record;
                record.lsn = hdr->lsn;
                record.commit_ts = hdr->commit_ts;
                record.type = static_cast<WALRecordType>(hdr->record_type);
                record.key = std::string(reinterpret_cast<const char*>(payload_ptr), hdr->key_len);
                record.value = std::string(reinterpret_cast<const char*>(payload_ptr + hdr->key_len), hdr->value_len);

                recovered.push_back(std::move(record));
                expected_lsn++;
                offset += total_rec_size;
            }
            file_offset += bytes_read;
        }

    recovery_done:
        ::close(read_fd);
        next_lsn_.store(expected_lsn, std::memory_order_relaxed);
        file_offset_.store(file_offset, std::memory_order_relaxed);
        return recovered;
    }

private:
    void InitBuffers() {
        for (size_t i = 0; i < NUM_BUFFERS; ++i) {
            void* buf = nullptr;
            int ret = posix_memalign(&buf, WAL_SECTOR_SIZE, BUFFER_SIZE);
            assert(ret == 0 && "posix_memalign failed");
            buffers_.push_back(static_cast<uint8_t*>(buf));
            iovecs_.push_back({buf, BUFFER_SIZE});
        }
    }

    void FreeBuffers() {
        for (void* buf : buffers_) {
            free(buf);
        }
        buffers_.clear();
        iovecs_.clear();
    }

    void InitIOUring() {
#if HAS_LIBURING
        struct io_uring_params params;
        std::memset(&params, 0, sizeof(params));
        // Use kernel submission polling (SQPOLL) if permitted
        params.flags = IORING_SETUP_SQPOLL;
        params.sq_thread_idle = 2000;

        int ret = io_uring_queue_init_params(RING_ENTRIES, &ring_, &params);
        if (ret < 0) {
            // Fallback without SQPOLL (e.g. non-root unprivileged environment)
            ret = io_uring_queue_init(RING_ENTRIES, &ring_, 0);
            assert(ret == 0 && "io_uring_queue_init failed");
        }
        io_uring_registered_ = true;

        // Register pre-allocated fixed buffers for zero-copy direct I/O
        ret = io_uring_register_buffers(&ring_, iovecs_.data(), iovecs_.size());
        assert(ret == 0 && "io_uring_register_buffers failed");
#endif
    }

    void CleanupIOUring() {
#if HAS_LIBURING
        if (io_uring_registered_) {
            io_uring_unregister_buffers(&ring_);
            io_uring_queue_exit(&ring_);
        }
#endif
    }

    void FlusherLoop() {
        size_t current_buffer_idx = 0;
        std::vector<WALRecord> batch;
        batch.reserve(256);

        while (running_.load(std::memory_order_acquire) || !mpsc_queue_.empty()) {
            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                cv_.wait_for(lock, std::chrono::microseconds(500), [&]() {
                    return !mpsc_queue_.empty() || !running_.load(std::memory_order_relaxed);
                });
                batch.swap(mpsc_queue_);
            }

            if (batch.empty()) continue;

            uint8_t* buf = buffers_[current_buffer_idx];
            std::memset(buf, 0, BUFFER_SIZE);
            size_t buf_offset = 0;
            std::vector<std::promise<void>*> pending_promises;

            for (const auto& rec : batch) {
                size_t rec_len = sizeof(WALRecordHeader) + rec.key.size() + rec.value.size();
                if (buf_offset + rec_len > BUFFER_SIZE) {
                    // Flush full buffer before continuing
                    FlushBufferDirect(current_buffer_idx, buf_offset);
                    FulfillPromises(pending_promises);
                    current_buffer_idx = (current_buffer_idx + 1) % NUM_BUFFERS;
                    buf = buffers_[current_buffer_idx];
                    std::memset(buf, 0, BUFFER_SIZE);
                    buf_offset = 0;
                }

                auto* hdr = reinterpret_cast<WALRecordHeader*>(buf + buf_offset);
                hdr->magic = WAL_MAGIC;
                hdr->payload_len = rec.key.size() + rec.value.size();
                hdr->lsn = rec.lsn;
                hdr->commit_ts = rec.commit_ts;
                hdr->record_type = static_cast<uint8_t>(rec.type);
                hdr->key_len = rec.key.size();
                hdr->value_len = rec.value.size();

                uint8_t* payload = buf + buf_offset + sizeof(WALRecordHeader);
                std::memcpy(payload, rec.key.data(), rec.key.size());
                std::memcpy(payload + rec.key.size(), rec.value.data(), rec.value.size());
                hdr->crc32c = CalculateCRC32C(payload, hdr->payload_len);

                buf_offset += rec_len;
                if (rec.sync_promise) {
                    pending_promises.push_back(rec.sync_promise);
                }
            }

            if (buf_offset > 0) {
                // Align write size up to 4KB sector boundary for O_DIRECT
                size_t aligned_bytes = (buf_offset + WAL_SECTOR_SIZE - 1) & ~(WAL_SECTOR_SIZE - 1);
                FlushBufferDirect(current_buffer_idx, aligned_bytes);
                FulfillPromises(pending_promises);
                current_buffer_idx = (current_buffer_idx + 1) % NUM_BUFFERS;
            }

            batch.clear();
        }
    }

    void FlushBufferDirect(size_t buffer_idx, size_t aligned_size) {
        off_t write_offset = file_offset_.fetch_add(aligned_size, std::memory_order_relaxed);

#if HAS_LIBURING
        struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
        while (!sqe) {
            io_uring_submit(&ring_);
            sqe = io_uring_get_sqe(&ring_);
        }

        io_uring_prep_write_fixed(sqe, fd_, buffers_[buffer_idx], aligned_size, write_offset, buffer_idx);
        io_uring_submit(&ring_);

        struct io_uring_cqe* cqe = nullptr;
        int ret = io_uring_wait_cqe(&ring_, &cqe);
        assert(ret == 0 && cqe->res >= 0 && "io_uring write failed");
        io_uring_cqe_seen(&ring_, cqe);
#else
        ssize_t written = pwrite(fd_, buffers_[buffer_idx], aligned_size, write_offset);
        assert(written == static_cast<ssize_t>(aligned_size) && "pwrite failed");
        fdatasync(fd_);
#endif
    }

    void FulfillPromises(std::vector<std::promise<void>*>& promises) {
        for (auto* p : promises) {
            p->set_value();
            delete p;
        }
        promises.clear();
    }

    std::string log_path_;
    int fd_{-1};
    bool direct_io_supported_{true};
    std::atomic<bool> running_{false};
    std::atomic<uint64_t> next_lsn_{1};
    std::atomic<off_t> file_offset_{0};

    std::vector<uint8_t*> buffers_;
    std::vector<struct iovec> iovecs_;
    std::mutex queue_mutex_;
    std::condition_variable cv_;
    std::vector<WALRecord> mpsc_queue_;
    std::thread flusher_thread_;

#if HAS_LIBURING
    struct io_uring ring_;
    bool io_uring_registered_{false};
#endif
};

// ============================================================================
// 5. STORAGE ENGINE WITH SNAPSHOT ISOLATION & CONCURRENCY CONTROL
// ============================================================================

class StorageEngine {
public:
    class Transaction {
    public:
        Transaction(StorageEngine& engine, uint64_t read_ts)
            : engine_(engine), read_ts_(read_ts), committed_(false) {}

        ~Transaction() {
            if (!committed_) {
                Rollback();
            }
        }

        std::optional<std::string> Read(std::string_view key) {
            // Check uncommitted write-set first
            auto it = write_set_.find(std::string(key));
            if (it != write_set_.end()) {
                if (it->second.has_value()) return it->second;
                return std::nullopt; // Local tombstone
            }
            return engine_.index_.Get(key, read_ts_);
        }

        void Write(std::string_view key, std::string_view value) {
            write_set_[std::string(key)] = std::string(value);
        }

        void Delete(std::string_view key) {
            write_set_[std::string(key)] = std::nullopt;
        }

        bool Commit() {
            if (committed_) return false;
            if (write_set_.empty()) {
                committed_ = true;
                return true;
            }

            // Allocate monotonic commit timestamp
            uint64_t commit_ts = engine_.global_ts_.fetch_add(1, std::memory_order_acq_rel) + 1;
            std::vector<std::future<void>> wal_futures;

            // Phase 1: Write to WAL
            for (const auto& [k, v] : write_set_) {
                WALRecordType type = v.has_value() ? WALRecordType::PUT : WALRecordType::DELETE;
                std::string_view val_view = v.has_value() ? *v : "";
                wal_futures.push_back(engine_.wal_.AppendRecord(commit_ts, type, k, val_view));
            }

            // Await hardware durability
            for (auto& fut : wal_futures) {
                fut.get();
            }

            // Phase 2: Lock-Free Version Installation with Conflict Detection
            for (const auto& [k, v] : write_set_) {
                bool is_tombstone = !v.has_value();
                std::string_view val_view = v.has_value() ? *v : "";
                bool success = engine_.index_.Put(k, val_view, commit_ts, is_tombstone);
                if (!success) {
                    // Write-Write conflict occurred
                    Rollback();
                    return false;
                }
            }

            committed_ = true;
            return true;
        }

        void Rollback() {
            write_set_.clear();
            committed_ = true;
        }

    private:
        StorageEngine& engine_;
        uint64_t read_ts_;
        bool committed_;
        std::unordered_map<std::string, std::optional<std::string>> write_set_;
    };

    StorageEngine(const std::string& wal_path)
        : wal_(wal_path), global_ts_(1), gc_running_(true) {
        RecoverFromWAL();
        gc_thread_ = std::thread(&StorageEngine::VacuumLoop, this);
    }

    ~StorageEngine() {
        gc_running_.store(false, std::memory_order_release);
        if (gc_thread_.joinable()) {
            gc_thread_.join();
        }
    }

    Transaction BeginTransaction() {
        EpochManager::Instance().RegisterThread();
        uint64_t read_ts = global_ts_.load(std::memory_order_acquire);
        return Transaction(*this, read_ts);
    }

    std::vector<std::pair<std::string, std::string>> Scan(std::string_view start_key,
                                                         std::string_view end_key,
                                                         uint64_t read_ts) {
        return index_.Scan(start_key, end_key, read_ts);
    }

private:
