// ============================================================================
// 1. DECENTRALIZED 3-PHASE EPOCH-BASED RECLAMATION (EBR)
// ============================================================================

struct alignas(CACHE_LINE) EpochReclamationEntry {
    void* ptr;
    void (*deleter)(void*);
};

class GlobalEpochManager;

struct alignas(CACHE_LINE) ThreadEpochDescriptor {
    // 0 = inactive/quiescent; odd epoch numbers = active reading epoch
    std::atomic<uint64_t> local_epoch{0};
    std::atomic<ThreadEpochDescriptor*> next{nullptr};

    // 3 epoch limbo lists for retired objects
    std::vector<EpochReclamationEntry> limbo[3];
    uint64_t registered_epoch{0};

    ~ThreadEpochDescriptor() {
        // Drain any remaining limbo items upon thread termination
        for (int i = 0; i < 3; ++i) {
            for (auto& item : limbo[i]) {
                item.deleter(item.ptr);
            }
            limbo[i].clear();
        }
    }
};

class GlobalEpochManager {
public:
    static GlobalEpochManager& Instance() {
        static GlobalEpochManager instance;
        return instance;
    }

    GlobalEpochManager() : global_epoch_(1), head_thread_(nullptr) {}

    ~GlobalEpochManager() {
        // Reclaim all remaining objects across all registered threads
        ThreadEpochDescriptor* curr = head_thread_.load(std::memory_order_relaxed);
        while (curr) {
            for (int i = 0; i < 3; ++i) {
                for (auto& item : curr->limbo[i]) {
                    item.deleter(item.ptr);
                }
                curr->limbo[i].clear();
            }
            curr = curr->next.load(std::memory_order_relaxed);
        }
    }

    void RegisterThread(ThreadEpochDescriptor* desc) {
        ThreadEpochDescriptor* old_head = head_thread_.load(std::memory_order_relaxed);
        do {
            desc->next.store(old_head, std::memory_order_relaxed);
        } while (!head_thread_.compare_exchange_weak(
            old_head, desc, std::memory_order_release, std::memory_order_relaxed));
    }

    void EnterEpoch(ThreadEpochDescriptor* desc) {
        // memory_order_seq_cst ensures that entering the epoch descriptor is globally visible
        // prior to any subsequent speculative or active memory loads in the transaction.
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);
        desc->local_epoch.store(current, std::memory_order_seq_cst);
    }

    void LeaveEpoch(ThreadEpochDescriptor* desc) {
        // memory_order_release ensures all memory reads in the guarded region complete 
        // before the thread publishes that it has exited the epoch.
        desc->local_epoch.store(0, std::memory_order_release);
    }

    template <typename T>
    void Retire(ThreadEpochDescriptor* desc, T* ptr) {
        if (!ptr) return;
        uint64_t epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = epoch % 3;
        desc->limbo[idx].push_back({
            static_cast<void*>(ptr),
            [](void* p) { delete static_cast<T*>(p); }
        });
    }

    void TryAdvanceAndReclaim(ThreadEpochDescriptor* desc) {
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);

        // Scan all registered threads to check if all active threads have reached 'current'
        ThreadEpochDescriptor* curr = head_thread_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            uint64_t active_epoch = curr->local_epoch.load(std::memory_order_acquire);
            if (active_epoch != 0 && active_epoch < current) {
                // Thread is still observing a prior epoch; cannot safely advance.
                return;
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(current, current + 1,
                                                 std::memory_order_acq_rel,
                                                 std::memory_order_relaxed)) {
            // Epoch successfully advanced. Items retired 2 epochs ago are now safe to delete.
            size_t reclaim_idx = (current + 2) % 3; // Equivalent to (current - 1) % 3
            for (auto& item : desc->limbo[reclaim_idx]) {
                item.deleter(item.ptr);
            }
            desc->limbo[reclaim_idx].clear();
        }
    }

private:
    alignas(CACHE_LINE) std::atomic<uint64_t> global_epoch_;
    alignas(CACHE_LINE) std::atomic<ThreadEpochDescriptor*> head_thread_;
};

