struct VersionRecord {
    std::atomic<uint64_t> begin_ts;
    std::atomic<uint64_t> end_ts;
    std::atomic<VersionRecord*> prev;
    uint32_t payload_size;
    uint8_t payload[1]; // Flexible array allocation

    static VersionRecord* Create(uint64_t begin, uint64_t end, VersionRecord* prev_rec, std::span<const uint8_t> data) {
        size_t total_size = sizeof(VersionRecord) + data.size() - 1;
        void* mem = ::operator new(total_size);
        return new (mem) VersionRecord(begin, end, prev_rec, data);
    }

    static void Destroy(VersionRecord* rec) {
        if (!rec) return;
        rec->~VersionRecord();
        ::operator delete(static_cast<void*>(rec));
    }

private:
    VersionRecord(uint64_t begin, uint64_t end, VersionRecord* prev_rec, std::span<const uint8_t> data)
        : begin_ts(begin), end_ts(end), prev(prev_rec), payload_size(static_cast<uint32_t>(data.size())) {
        if (!data.empty()) {
            std::memcpy(payload, data.data(), data.size());
        }
    }
    ~VersionRecord() = default;
};

