enum class NodeType : uint8_t {
    Node4   = 0,
    Node16  = 1,
    Node48  = 2,
    Node256 = 3,
    Leaf    = 4
};

// Optimistic Version Lock:
// Bit 0 (0x1): Write lock bit
// Bit 1 (0x2): Obsolete bit (set when node is removed/replaced during growth)
// Bits 2..63: Monotonic modification generation counter
struct alignas(CACHE_LINE) OptimisticVersionLock {
    std::atomic<uint64_t> version{0};

    uint64_t ReadLockOrRestart(bool& restart) const {
        uint64_t v = version.load(std::memory_order_acquire);
        if ((v & 0b11) != 0) { // Locked or Obsolete
            restart = true;
            return 0;
        }
        restart = false;
        return v;
    }

    bool CheckVersion(uint64_t old_version) const {
        std::atomic_thread_fence(std::memory_order_acquire);
        return version.load(std::memory_order_relaxed) == old_version;
    }

    bool AcquireWriteLock() {
        uint64_t v = version.load(std::memory_order_relaxed);
        while (true) {
            if ((v & 0b11) != 0) return false; // Already locked or obsolete
            if (version.compare_exchange_weak(v, v | 0b01,
                                              std::memory_order_acquire,
                                              std::memory_order_relaxed)) {
                return true;
            }
        }
    }

    void ReleaseWriteLock() {
        // Increment version generation, clear lock bit (v + 4 - 1 = v + 3)
        uint64_t v = version.load(std::memory_order_relaxed);
        version.store((v + 4) & ~0b01ULL, std::memory_order_release);
    }

    void MarkObsoleteAndRelease() {
        uint64_t v = version.load(std::memory_order_relaxed);
        version.store((v + 4) | 0b10ULL, std::memory_order_release);
    }
};

struct NodeHeader {
    NodeType type;
    uint8_t prefix_len{0};
    uint8_t prefix[MAX_PREFIX]{};
    OptimisticVersionLock lock;

    explicit NodeHeader(NodeType t) : type(t) {}

    bool MatchPrefix(uint64_t key, uint32_t depth, uint32_t& matched_len) const {
        matched_len = 0;
        uint32_t limit = std::min(static_cast<uint32_t>(prefix_len), static_cast<uint32_t>(MAX_PREFIX));
        for (uint32_t i = 0; i < limit && (depth + i) < 8; ++i) {
            uint8_t key_byte = static_cast<uint8_t>((key >> (56 - 8 * (depth + i))) & 0xFF);
            if (prefix[i] != key_byte) return false;
            matched_len++;
        }
        return matched_len == prefix_len;
    }
};

struct LeafNode : public NodeHeader {
    uint64_t key;
    std::atomic<VersionRecord*> chain_head{nullptr};

    explicit LeafNode(uint64_t k, VersionRecord* initial_version)
        : NodeHeader(NodeType::Leaf), key(k), chain_head(initial_version) {}
};

struct Node4 : public NodeHeader {
    uint8_t count{0};
    uint8_t keys[4]{};
    std::atomic<NodeHeader*> children[4]{};

    Node4() : NodeHeader(NodeType::Node4) {
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }

    NodeHeader* FindChild(uint8_t key_byte) const {
        for (uint8_t i = 0; i < count; ++i) {
            if (keys[i] == key_byte) {
                return children[i].load(std::memory_order_consume);
            }
        }
        return nullptr;
    }
};

struct Node16 : public NodeHeader {
    uint8_t count{0};
    uint8_t keys[16]{};
    std::atomic<NodeHeader*> children[16]{};

    Node16() : NodeHeader(NodeType::Node16) {
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }

    NodeHeader* FindChild(uint8_t key_byte) const {
#if defined(ART_X86_SIMD)
        __m128i cmp_key = _mm_set1_epi8(static_cast<char>(key_byte));
        __m128i node_keys = _mm_loadu_si128(reinterpret_cast<const __m128i*>(keys));
        __m128i res = _mm_cmpeq_epi8(cmp_key, node_keys);
        int mask = _mm_movemask_epi8(res) & ((1 << count) - 1);
        if (mask != 0) {
            int idx = __builtin_ctz(mask);
            return children[idx].load(std::memory_order_consume);
        }
#else
        for (uint8_t i = 0; i < count; ++i) {
            if (keys[i] == key_byte) {
                return children[i].load(std::memory_order_consume);
            }
        }
#endif
        return nullptr;
    }
};

struct Node48 : public NodeHeader {
    static constexpr uint8_t EMPTY_MARKER = 48;
    uint8_t count{0};
    uint8_t child_indices[256];
    std::atomic<NodeHeader*> children[48]{};

    Node48() : NodeHeader(NodeType::Node48) {
        std::memset(child_indices, EMPTY_MARKER, sizeof(child_indices));
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }

    NodeHeader* FindChild(uint8_t key_byte) const {
        uint8_t idx = child_indices[key_byte];
        if (idx < 48) {
            return children[idx].load(std::memory_order_consume);
        }
        return nullptr;
    }
};

struct Node256 : public NodeHeader {
    uint16_t count{0};
    std::atomic<NodeHeader*> children[256]{};

    Node256() : NodeHeader(NodeType::Node256) {
        for (auto& c : children) c.store(nullptr, std::memory_order_relaxed);
    }

    NodeHeader* FindChild(uint8_t key_byte) const {
        return children[key_byte].load(std::memory_order_consume);
    }
};

// ART Tree implementation supporting optimistic read traversal and lock-free node adaptation
class ConcurrentART {
public:
    ConcurrentART() : root_(nullptr) {}

    ~ConcurrentART() {
        DestroyRecursive(root_.load(std::memory_order_relaxed));
    }

    LeafNode* Lookup(uint64_t key) const {
        while (true) {
            bool restart = false;
            NodeHeader* curr = root_.load(std::memory_order_acquire);
            if (!curr) return nullptr;

            uint32_t depth = 0;
            while (curr) {
                if (curr->type == NodeType::Leaf) {
                    auto* leaf = static_cast<LeafNode*>(curr);
                    if (leaf->key == key) return leaf;
                    return nullptr;
                }

                uint64_t v = curr->lock.ReadLockOrRestart(restart);
                if (restart) break;

                // Validate Prefix
                if (curr->prefix_len > 0) {
                    uint32_t matched = 0;
                    if (!curr->MatchPrefix(key, depth, matched)) {
                        if (!curr->lock.CheckVersion(v)) { restart = true; break; }
                        return nullptr;
                    }
                    depth += curr->prefix_len;
                }

                if (depth >= 8) {
                    if (!curr->lock.CheckVersion(v)) { restart = true; break; }
                    return nullptr;
                }

                uint8_t key_byte = static_cast<uint8_t>((key >> (56 - 8 * depth)) & 0xFF);
                NodeHeader* next = nullptr;

                switch (curr->type) {
                    case NodeType::Node4:   next = static_cast<Node4*>(curr)->FindChild(key_byte); break;
                    case NodeType::Node16:  next = static_cast<Node16*>(curr)->FindChild(key_byte); break;
                    case NodeType::Node48:  next = static_cast<Node48*>(curr)->FindChild(key_byte); break;
                    case NodeType::Node256: next = static_cast<Node256*>(curr)->FindChild(key_byte); break;
                    default: break;
                }

                if (!curr->lock.CheckVersion(v)) {
                    restart = true;
                    break;
                }

                curr = next;
                depth++;
            }

            if (!restart) return nullptr;
        }
    }

    LeafNode* GetOrCreateLeaf(uint64_t key, VersionRecord* initial_version) {
        while (true) {
            NodeHeader* current_root = root_.load(std::memory_order_acquire);
            if (!current_root) {
                auto* new_leaf = new LeafNode(key, initial_version);
                if (root_.compare_exchange_strong(current_root, new_leaf,
                                                  std::memory_order_release,
                                                  std::memory_order_relaxed)) {
                    return new_leaf;
                }
                delete new_leaf;
                continue;
            }

            LeafNode* result = InsertInternal(nullptr, &root_, current_root, key, 0, initial_version);
            if (result != nullptr) {
                return result;
            }
        }
    }

private:
    std::atomic<NodeHeader*> root_;

    void DestroyRecursive(NodeHeader* node) {
        if (!node) return;
        if (node->type == NodeType::Leaf) {
            auto* leaf = static_cast<LeafNode*>(node);
            VersionRecord* cur = leaf->chain_head.load(std::memory_order_relaxed);
            while (cur) {
                VersionRecord* next = cur->prev.load(std::memory_order_relaxed);
                VersionRecord::Destroy(cur);
                cur = next;
            }
            delete leaf;
            return;
        }

        switch (node->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(node);
                for (uint8_t i = 0; i < n->count; ++i) DestroyRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(node);
                for (uint8_t i = 0; i < n->count; ++i) DestroyRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(node);
                for (uint8_t i = 0; i < 256; ++i) {
                    uint8_t idx = n->child_indices[i];
                    if (idx < 48) DestroyRecursive(n->children[idx].load(std::memory_order_relaxed));
                }
                delete n;
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(node);
                for (int i = 0; i < 256; ++i) DestroyRecursive(n->children[i].load(std::memory_order_relaxed));
                delete n;
                break;
            }
            default: break;
        }
    }

    LeafNode* InsertInternal(NodeHeader* parent, std::atomic<NodeHeader*>* parent_slot,
                            NodeHeader* node, uint64_t key, uint32_t depth, VersionRecord* rec) {
        if (node->type == NodeType::Leaf) {
            auto* leaf = static_cast<LeafNode*>(node);
            if (leaf->key == key) return leaf;

            // Key collision at leaf level: create a parent node and split
            if (!parent && !root_.load(std::memory_order_relaxed)) return nullptr;

            auto* n4 = new Node4();
            uint64_t k1 = leaf->key;
            uint64_t k2 = key;
            uint32_t common_prefix_len = 0;

            while (depth + common_prefix_len < 8) {
                uint8_t b1 = static_cast<uint8_t>((k1 >> (56 - 8 * (depth + common_prefix_len))) & 0xFF);
                uint8_t b2 = static_cast<uint8_t>((k2 >> (56 - 8 * (depth + common_prefix_len))) & 0xFF);
                if (b1 != b2) break;
                if (common_prefix_len < MAX_PREFIX) {
                    n4->prefix[common_prefix_len] = b1;
                }
                common_prefix_len++;
            }
            n4->prefix_len = static_cast<uint8_t>(std::min(common_prefix_len, static_cast<uint32_t>(MAX_PREFIX)));

            uint32_t new_depth = depth + common_prefix_len;
            uint8_t byte1 = static_cast<uint8_t>((k1 >> (56 - 8 * new_depth)) & 0xFF);
            uint8_t byte2 = static_cast<uint8_t>((k2 >> (56 - 8 * new_depth)) & 0xFF);

            auto* new_leaf = new LeafNode(key, rec);

            n4->keys[0] = byte1;
            n4->children[0].store(leaf, std::memory_order_relaxed);
            n4->keys[1] = byte2;
            n4->children[1].store(new_leaf, std::memory_order_relaxed);
            n4->count = 2;

            if (parent_slot->compare_exchange_strong(node, n4, std::memory_order_release, std::memory_order_relaxed)) {
                return new_leaf;
            } else {
                delete new_leaf;
                delete n4;
                return nullptr;
            }
        }

        // Inner node traversal and lock coupling
        if (!node->lock.AcquireWriteLock()) return nullptr;

        // Verify prefix matching
        uint32_t matched = 0;
        if (node->prefix_len > 0) {
            if (!node->MatchPrefix(key, depth, matched)) {
                // Split prefix node
                auto* split_node = new Node4();
                split_node->prefix_len = static_cast<uint8_t>(matched);
                for (uint32_t i = 0; i < matched; ++i) {
                    split_node->prefix[i] = node->prefix[i];
                }

                uint8_t old_prefix_byte = node->prefix[matched];
                node->prefix_len -= static_cast<uint8_t>(matched + 1);
                std::memmove(node->prefix, node->prefix + matched + 1, node->prefix_len);

                auto* new_leaf = new LeafNode(key, rec);
                uint8_t new_byte = static_cast<uint8_t>((key >> (56 - 8 * (depth + matched))) & 0xFF);

                split_node->keys[0] = old_prefix_byte;
                split_node->children[0].store(node, std::memory_order_relaxed);
                split_node->keys[1] = new_byte;
                split_node->children[1].store(new_leaf, std::memory_order_relaxed);
                split_node->count = 2;

                parent_slot->store(split_node, std::memory_order_release);
                node->lock.ReleaseWriteLock();
                return new_leaf;
            }
            depth += node->prefix_len;
        }

        uint8_t key_byte = static_cast<uint8_t>((key >> (56 - 8 * depth)) & 0xFF);
        std::atomic<NodeHeader*>* child_slot = nullptr;

        switch (node->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(node);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == key_byte) {
                        child_slot = &n->children[i];
                        break;
                    }
                }
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(node);
                for (uint8_t i = 0; i < n->count; ++i) {
                    if (n->keys[i] == key_byte) {
                        child_slot = &n->children[i];
                        break;
                    }
                }
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(node);
                uint8_t idx = n->child_indices[key_byte];
                if (idx < 48) child_slot = &n->children[idx];
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(node);
                child_slot = &n->children[key_byte];
                break;
            }
            default: break;
        }

        if (child_slot && child_slot->load(std::memory_order_relaxed) != nullptr) {
            NodeHeader* child = child_slot->load(std::memory_order_relaxed);
            node->lock.ReleaseWriteLock();
            return InsertInternal(node, child_slot, child, key, depth + 1, rec);
        }

        // Child not found: insert into current node, expanding if necessary
        LeafNode* new_leaf = new LeafNode(key, rec);
        InsertChildAndExpand(node, parent_slot, key_byte, new_leaf);
        node->lock.ReleaseWriteLock();
        return new_leaf;
    }

    void InsertChildAndExpand(NodeHeader* node, std::atomic<NodeHeader*>* parent_slot,
                              uint8_t key_byte, NodeHeader* child) {
        switch (node->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(node);
                if (n->count < 4) {
                    n->keys[n->count] = key_byte;
                    n->children[n->count].store(child, std::memory_order_release);
                    n->count++;
                } else {
                    auto* n16 = new Node16();
                    n16->count = n->count;
                    n16->prefix_len = n->prefix_len;
                    std::memcpy(n16->prefix, n->prefix, sizeof(n->prefix));
                    for (uint8_t i = 0; i < n->count; ++i) {
                        n16->keys[i] = n->keys[i];
                        n16->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                    n16->keys[n16->count] = key_byte;
                    n16->children[n16->count].store(child, std::memory_order_relaxed);
                    n16->count++;

                    parent_slot->store(n16, std::memory_order_release);
                    n->lock.MarkObsoleteAndRelease();
                    GlobalEpochManager::Instance().Retire(&t_epoch_desc, n);
                }
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(node);
                if (n->count < 16) {
                    n->keys[n->count] = key_byte;
                    n->children[n->count].store(child, std::memory_order_release);
                    n->count++;
                } else {
                    auto* n48 = new Node48();
                    n48->count = n->count;
                    n48->prefix_len = n->prefix_len;
                    std::memcpy(n48->prefix, n->prefix, sizeof(n->prefix));
                    for (uint8_t i = 0; i < n->count; ++i) {
                        n48->child_indices[n->keys[i]] = i;
                        n48->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                    n48->child_indices[key_byte] = n48->count;
                    n48->children[n48->count].store(child, std::memory_order_relaxed);
                    n48->count++;

                    parent_slot->store(n48, std::memory_order_release);
                    n->lock.MarkObsoleteAndRelease();
                    GlobalEpochManager::Instance().Retire(&t_epoch_desc, n);
                }
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(node);
                if (n->count < 48) {
                    uint8_t idx = n->count;
                    n->child_indices[key_byte] = idx;
                    n->children[idx].store(child, std::memory_order_release);
                    n->count++;
                } else {
                    auto* n256 = new Node256();
                    n256->count = n->count;
                    n256->prefix_len = n->prefix_len;
                    std::memcpy(n256->prefix, n->prefix, sizeof(n->prefix));
                    for (int i = 0; i < 256; ++i) {
                        uint8_t idx = n->child_indices[i];
                        if (idx < 48) {
                            n256->children[i].store(n->children[idx].load(std::memory_order_relaxed), std::memory_order_relaxed);
                        }
                    }
                    n256->children[key_byte].store(child, std::memory_order_relaxed);
                    n256->count++;

                    parent_slot->store(n256, std::memory_order_release);
                    n->lock.MarkObsoleteAndRelease();
                    GlobalEpochManager::Instance().Retire(&t_epoch_desc, n);
                }
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(node);
                n->children[key_byte].store(child, std::memory_order_release);
                n->count++;
                break;
            }
            default: break;
        }
    }
};

