class TransactionManager {
public:
    TransactionManager() : global_ts_(1) {}

    uint64_t GetSnapshotTimestamp() const {
        return global_ts_.load(std::memory_order_acquire);
    }

    uint64_t AllocateCommitTimestamp() {
        return global_ts_.fetch_add(1, std::memory_order_acq_rel) + 1;
    }

    ConcurrentART& GetIndex() { return index_; }

private:
    alignas(CACHE_LINE) std::atomic<uint64_t> global_ts_;
    ConcurrentART index_;
};

class Transaction {
public:
    struct WriteBufferEntry {
        uint64_t key;
        std::vector<uint8_t> val;
    };

    struct ReadSetEntry {
        uint64_t key;
        VersionRecord* record;
    };

    explicit Transaction(TransactionManager& tm)
        : tm_(tm),
          read_ts_(tm.GetSnapshotTimestamp()),
          is_active_(true) {}

    ~Transaction() {
        if (is_active_) {
            Abort();
        }
    }

    bool Read(uint64_t key, std::span<const uint8_t>& out_val) {
        if (!is_active_) return false;

        // Check local write-set first (Read-Your-Own-Writes)
        for (auto it = write_set_.rbegin(); it != write_set_.rend(); ++it) {
            if (it->key == key) {
                out_val = std::span<const uint8_t>(it->val.data(), it->val.size());
                return true;
            }
        }

        EpochGuard guard;
        LeafNode* leaf = tm_.GetIndex().Lookup(key);
        if (!leaf) return false;

        // Traverse version chain to find visible version: begin_ts <= read_ts < end_ts
        VersionRecord* curr = leaf->chain_head.load(std::memory_order_acquire);
        while (curr != nullptr) {
            uint64_t b = curr->begin_ts.load(std::memory_order_acquire);
            uint64_t e = curr->end_ts.load(std::memory_order_acquire);

            if (b <= read_ts_ && read_ts_ < e) {
                read_set_.push_back({key, curr});
                out_val = std::span<const uint8_t>(curr->payload, curr->payload_size);
                return true;
            }
            curr = curr->prev.load(std::memory_order_acquire);
        }

        return false;
    }

    bool Write(uint64_t key, std::span<const uint8_t> val) {
        if (!is_active_) return false;
        write_set_.push_back({key, std::vector<uint8_t>(val.begin(), val.end())});
        return true;
    }

    bool Commit() {
        if (!is_active_) return false;
        if (write_set_.empty()) {
            is_active_ = false;
            return true;
        }

        EpochGuard guard;

        // 1. Validation & Pre-installation (Write-Write Conflict Detection)
        struct InstalledWrite {
            LeafNode* leaf;
            VersionRecord* old_head;
            VersionRecord* new_record;
        };
        std::vector<InstalledWrite> installed;
        installed.reserve(write_set_.size());

        for (const auto& w : write_set_) {
            VersionRecord* new_rec = VersionRecord::Create(
                TENTATIVE_TS, INF_TS, nullptr, std::span<const uint8_t>(w.val.data(), w.val.size()));

            LeafNode* leaf = tm_.GetIndex().GetOrCreateLeaf(w.key, new_rec);

            // If the leaf was not freshly created with new_rec
            if (leaf->chain_head.load(std::memory_order_relaxed) != new_rec) {
                while (true) {
                    VersionRecord* cur_head = leaf->chain_head.load(std::memory_order_acquire);

                    // Write-Write Conflict: active uncommitted write or newer committed write
                    if (cur_head != nullptr) {
                        uint64_t cur_begin = cur_head->begin_ts.load(std::memory_order_acquire);
                        uint64_t cur_end = cur_head->end_ts.load(std::memory_order_acquire);
                        if (cur_begin == TENTATIVE_TS || cur_begin > read_ts_ || cur_end != INF_TS) {
                            VersionRecord::Destroy(new_rec);
                            RollbackInstalled(installed);
                            is_active_ = false;
                            return false;
                        }
                    }

                    new_rec->prev.store(cur_head, std::memory_order_relaxed);
                    if (leaf->chain_head.compare_exchange_weak(cur_head, new_rec,
                                                               std::memory_order_release,
                                                               std::memory_order_relaxed)) {
                        installed.push_back({leaf, cur_head, new_rec});
                        break;
                    }
                }
            } else {
                installed.push_back({leaf, nullptr, new_rec});
            }
        }

        // 2. Linearizability Point: Obtain final commit timestamp
        uint64_t commit_ts = tm_.AllocateCommitTimestamp();

        // 3. Finalize Versions: Atomically transition tentative markers
        for (auto& inst : installed) {
            if (inst.old_head != nullptr) {
                inst.old_head->end_ts.store(commit_ts, std::memory_order_release);
            }
            inst.new_record->begin_ts.store(commit_ts, std::memory_order_release);
        }

        is_active_ = false;
        return true;
    }

    void Abort() {
        if (!is_active_) return;
        write_set_.clear();
        read_set_.clear();
        is_active_ = false;
    }

private:
    void RollbackInstalled(const std::vector<struct InstalledWrite>& installed) {
        for (const auto& inst : installed) {
            // Restore previous head
            inst.leaf->chain_head.store(inst.old_head, std::memory_order_release);
            GlobalEpochManager::Instance().Retire(&t_epoch_desc, inst.new_record);
        }
    }

    TransactionManager& tm_;
    uint64_t read_ts_;
    bool is_active_;
    std::vector<ReadSetEntry> read_set_;
    std::vector<WriteBufferEntry> write_set_;
};

