+----------------------------------------------------------------------------------------------------+
```

#### 1. Memory Ordering & Synchronization Rationale
* **Optimistic Version Verification (`ArtNode::version_`):**
  * Node version counters pack an *expansion/lock bit* (LSB) and a *generation counter* (MSBs).
  * Readers load `version_` with `std::memory_order_acquire` before reading node payloads/children. If the LSB is set, the reader spins/yields.
  * After payload traversal, readers verify `version_` again via `std::memory_order_acquire`. If the version matches the pre-read value, the read slice is guaranteed to be non-torn without acquiring physical locks.
  * Writers use `fetch_add(2, std::memory_order_release)` or set the lock bit via `compare_exchange_weak(..., std::memory_order_acquire)` to ensure writes become visible prior to releasing optimistic locks.
* **Version Chain Pointer Swaps (`begin_ts`, `end_ts`, `prev_version`):**
  * When appending a new record version $V_{new}$ to a chain, its `prev_version` is initialized to the existing head. The head atomic pointer is swapped via `compare_exchange_strong(head, V_new, std::memory_order_acq_rel, std::memory_order_acquire)`.
  * The old version's `end_ts` is updated using `std::memory_order_release` to guarantee that the new payload is completely initialized and visible before any reader sees the transition $V_{old}.end\_ts = T_{commit}$.
* **Decentralized Epoch-Based Reclamation (EBR):**
  * Thread-local epoch markers are stored in cache-line isolated structures (`alignas(64)`).
  * Entry into an epoch critical section performs a `std::memory_order_seq_cst` or `std::memory_order_release` update to the thread's active epoch, publishing its active read status.
  * Memory retirement enqueues pointers into an epoch ring buffer `[3]`. Objects retired in epoch $e$ are safely reclaimed once all registered active threads report an epoch $e' \ge e + 2$.

---

### Complete Self-Contained Implementation

```cpp
#include <iostream>
#include <atomic>
#include <memory>
#include <vector>
#include <array>
#include <cstring>
#include <cstdint>
#include <span>
#include <optional>
#include <thread>
#include <mutex>
#include <shared_mutex>
#include <immintrin.h>
#include <cassert>
#include <functional>

namespace MVStore {

// ============================================================================
// CONSTANTS & FORWARD DECLARATIONS
// ============================================================================
static constexpr uint64_t INF_TS = std::numeric_limits<uint64_t>::max();
static constexpr size_t CACHE_LINE_SIZE = 64;
static constexpr uint32_t MAX_PREFIX_LEN = 8;
static constexpr size_t MAX_THREADS = 256;

class EpochManager;
class ThreadEpochContext;
struct RecordVersion;
struct ArtNode;

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) SUBSYSTEM
// ============================================================================

struct alignas(CACHE_LINE_SIZE) RetiredObject {
    void* ptr{nullptr};
    void (*deleter)(void*){nullptr};
    RetiredObject* next{nullptr};
};

struct alignas(CACHE_LINE_SIZE) ThreadEpochContext {
    std::atomic<uint64_t> local_epoch{0};
    std::atomic<bool> active{false};

    // Retirement queues for 3 epoch phases
    RetiredObject* limbo_lists[3]{nullptr, nullptr, nullptr};
    size_t limbo_counts[3]{0, 0, 0};

    ThreadEpochContext* next{nullptr};
};

class EpochManager {
public:
    static EpochManager& Instance() {
        static EpochManager instance;
        return instance;
    }

    EpochManager() : global_epoch_(1), thread_list_head_(nullptr) {}

    ~EpochManager() {
        // Drain all remaining memory on shutdown
        for (uint64_t i = 0; i < 3; ++i) {
            ReclaimLimboList(i);
        }
    }

    void RegisterThread(ThreadEpochContext* ctx) {
        ThreadEpochContext* old_head = thread_list_head_.load(std::memory_order_relaxed);
        do {
            ctx->next = old_head;
        } while (!thread_list_head_.compare_exchange_weak(
            old_head, ctx, std::memory_order_release, std::memory_order_relaxed));
    }

    void EnterCriticalSection(ThreadEpochContext& ctx) {
        // Announce active participation in current global epoch
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);
        ctx.local_epoch.store(current, std::memory_order_relaxed);
        ctx.active.store(true, std::memory_order_seq_cst);
    }

    void ExitCriticalSection(ThreadEpochContext& ctx) {
        ctx.active.store(false, std::memory_order_seq_cst);

        // Periodically attempt to advance epoch and reclaim memory
        TryAdvanceAndReclaim(ctx);
    }

    template <typename T>
    void Retire(ThreadEpochContext& ctx, T* ptr) {
        if (!ptr) return;
        auto* obj = new RetiredObject{
            .ptr = ptr,
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };

        uint64_t e = ctx.local_epoch.load(std::memory_order_relaxed) % 3;
        obj->next = ctx.limbo_lists[e];
        ctx.limbo_lists[e] = obj;
        ctx.limbo_counts[e]++;
    }

    void RetireArray(ThreadEpochContext& ctx, uint8_t* ptr) {
        if (!ptr) return;
        auto* obj = new RetiredObject{
            .ptr = ptr,
            .deleter = [](void* p) { delete[] static_cast<uint8_t*>(p); },
            .next = nullptr
        };

        uint64_t e = ctx.local_epoch.load(std::memory_order_relaxed) % 3;
        obj->next = ctx.limbo_lists[e];
        ctx.limbo_lists[e] = obj;
        ctx.limbo_counts[e]++;
    }

    void TryAdvanceAndReclaim(ThreadEpochContext& ctx) {
        uint64_t current_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Verify if all active threads have reached the current global epoch
        ThreadEpochContext* curr = thread_list_head_.load(std::memory_order_acquire);
        while (curr) {
            if (curr->active.load(std::memory_order_acquire)) {
                if (curr->local_epoch.load(std::memory_order_acquire) < current_epoch) {
                    return; // Stale thread active; cannot advance
                }
            }
            curr = curr->next;
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(current_epoch, current_epoch + 1, 
                                                 std::memory_order_acq_rel)) {
            // Memory retired 2 epochs ago is now strictly unreachable by any thread
            uint64_t reclaim_epoch_idx = (current_epoch + 1) % 3;
            ReclaimThreadLimbo(ctx, reclaim_epoch_idx);
        }
    }

private:
    void ReclaimThreadLimbo(ThreadEpochContext& ctx, size_t epoch_idx) {
        RetiredObject* head = ctx.limbo_lists[epoch_idx];
        ctx.limbo_lists[epoch_idx] = nullptr;
        ctx.limbo_counts[epoch_idx] = 0;

        while (head) {
            RetiredObject* next = head->next;
            head->deleter(head->ptr);
            delete head;
            head = next;
        }
    }

    void ReclaimLimboList(size_t idx) {
        ThreadEpochContext* curr = thread_list_head_.load(std::memory_order_relaxed);
        while (curr) {
            ReclaimThreadLimbo(*curr, idx);
            curr = curr->next;
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_epoch_;
    alignas(CACHE_LINE_SIZE) std::atomic<ThreadEpochContext*> thread_list_head_;
};

thread_local ThreadEpochContext t_epoch_ctx;

struct EpochGuard {
    EpochGuard() {
        static thread_local bool registered = false;
        if (!registered) {
            EpochManager::Instance().RegisterThread(&t_epoch_ctx);
            registered = true;
        }
        EpochManager::Instance().EnterCriticalSection(t_epoch_ctx);
    }
    ~EpochGuard() {
        EpochManager::Instance().ExitCriticalSection(t_epoch_ctx);
    }
};

// ============================================================================
// 2. MULTI-VERSION RECORD LAYER (MVCC)
// ============================================================================

struct RecordVersion {
    std::atomic<uint64_t> begin_ts{0};
    std::atomic<uint64_t> end_ts{INF_TS};
    std::atomic<RecordVersion*> prev_version{nullptr};

    size_t val_size{0};
    uint8_t* payload{nullptr};

    RecordVersion(uint64_t begin, size_t size, const uint8_t* data, RecordVersion* prev = nullptr)
        : begin_ts(begin), end_ts(INF_TS), prev_version(prev), val_size(size) {
        if (size > 0 && data != nullptr) {
            payload = new uint8_t[size];
            std::memcpy(payload, data, size);
        }
    }

    ~RecordVersion() {
        if (payload) {
            delete[] payload;
            payload = nullptr;
        }
    }
};

// ============================================================================
// 3. LOCK-FREE / OPTIMISTIC ADAPTIVE RADIX TREE (ART)
// ============================================================================

enum class NodeType : uint8_t {
    Node4 = 0,
    Node16 = 1,
    Node48 = 2,
    Node256 = 3,
    Leaf = 4
};

struct alignas(CACHE_LINE_SIZE) ArtNode {
    // Optimistic Version Lock: LSB 0 = Lock, bits [63:1] = Version Generation Counter
    std::atomic<uint64_t> version_{0};
    NodeType type;
    uint8_t prefix_len{0};
    uint8_t prefix[MAX_PREFIX_LEN]{0};

    explicit ArtNode(NodeType t) : type(t) {}

    bool IsLocked(uint64_t v) const { return (v & 1ULL) != 0; }

    uint64_t ReadLockOrRestart(bool& need_restart) const {
        uint64_t v = version_.load(std::memory_order_acquire);
        if (IsLocked(v)) {
            _mm_pause();
            need_restart = true;
            return 0;
        }
        need_restart = false;
        return v;
    }

    bool CheckVersion(uint64_t old_version) const {
        std::atomic_thread_fence(std::memory_order_acquire);
        return version_.load(std::memory_order_relaxed) == old_version;
    }

    bool UpgradeToWriteLock() {
        uint64_t v = version_.load(std::memory_order_relaxed);
        if (IsLocked(v)) return false;
        return version_.compare_exchange_strong(v, v + 1, std::memory_order_acquire, std::memory_order_relaxed);
    }

    void WriteUnlock() {
        // Increment version counter to advance generation and clear lock bit (bit 0)
        version_.fetch_add(1, std::memory_order_release);
    }

    void WriteUnlockObsolete() {
        // Obsolete state marks version with bit 0 set + bit 1 set to prevent further lock acquisitions
        version_.store(1ULL, std::memory_order_release);
    }
};

struct LeafNode : public ArtNode {
    uint64_t key;
    std::atomic<RecordVersion*> version_chain_head{nullptr};

    LeafNode(uint64_t k, RecordVersion* first_ver) : ArtNode(NodeType::Leaf), key(k) {
        version_chain_head.store(first_ver, std::memory_order_relaxed);
    }
};

struct Node4 : public ArtNode {
    std::atomic<uint8_t> count{0};
    uint8_t keys[4]{0};
    std::atomic<ArtNode*> children[4]{nullptr, nullptr, nullptr, nullptr};

    Node4() : ArtNode(NodeType::Node4) {}
};

struct Node16 : public ArtNode {
    std::atomic<uint8_t> count{0};
    uint8_t keys[16]{0};
    std::atomic<ArtNode*> children[16]{nullptr};

    Node16() : ArtNode(NodeType::Node16) {}
};

struct Node48 : public ArtNode {
    std::atomic<uint8_t> count{0};
    static constexpr uint8_t EMPTY_MARKER = 48;
    uint8_t child_indices[256];
    std::atomic<ArtNode*> children[48]{nullptr};

    Node48() : ArtNode(NodeType::Node48) {
        std::memset(child_indices, EMPTY_MARKER, sizeof(child_indices));
    }
};

struct Node256 : public ArtNode {
    std::atomic<uint16_t> count{0};
    std::atomic<ArtNode*> children[256]{nullptr};

    Node256() : ArtNode(NodeType::Node256) {}
};

// ============================================================================
// ART TREE MANIPULATION AND TRAVERSAL
// ============================================================================

class ConcurrentART {
public:
    ConcurrentART() {
        root_.store(nullptr, std::memory_order_relaxed);
    }

    ~ConcurrentART() {
        // Tree cleanup happens via epoch manager on shutdown
    }

    static inline uint8_t GetByte(uint64_t key, size_t depth) {
        // Big-endian extraction of byte slice (depth 0 = MSB, depth 7 = LSB)
        return static_cast<uint8_t>((key >> ((7 - depth) * 8)) & 0xFF);
    }

    LeafNode* Lookup(uint64_t key) const {
        while (true) {
            bool need_restart = false;
            ArtNode* current = root_.load(std::memory_order_acquire);
            if (!current) return nullptr;

            size_t depth = 0;

            while (current) {
                uint64_t v = current->ReadLockOrRestart(need_restart);
                if (need_restart) break;

                if (current->type == NodeType::Leaf) {
                    auto* leaf = static_cast<LeafNode*>(current);
                    if (!current->CheckVersion(v)) {
                        need_restart = true;
                        break;
                    }
                    return (leaf->key == key) ? leaf : nullptr;
                }

                // Check optimistic prefix compression
                if (current->prefix_len > 0) {
                    for (uint32_t i = 0; i < current->prefix_len; ++i) {
                        if (GetByte(key, depth + i) != current->prefix[i]) {
                            if (!current->CheckVersion(v)) {
                                need_restart = true;
                                break;
                            }
                            return nullptr;
                        }
                    }
                    if (need_restart) break;
                    depth += current->prefix_len;
                }

                uint8_t byte = GetByte(key, depth);
                ArtNode* next_child = FindChild(current, byte);

                if (!current->CheckVersion(v)) {
                    need_restart = true;
                    break;
                }

                if (!next_child) return nullptr;

                current = next_child;
                depth += 1;
            }

            if (!need_restart) return nullptr;
        }
    }

    bool InsertOrUpdateLeaf(uint64_t key, RecordVersion* initial_version, LeafNode*& out_leaf) {
        while (true) {
            ArtNode* root = root_.load(std::memory_order_acquire);
            if (!root) {
                auto* new_leaf = new LeafNode(key, initial_version);
                if (root_.compare_exchange_strong(root, new_leaf, std::memory_order_acq_rel, std::memory_order_acquire)) {
                    out_leaf = new_leaf;
                    return true;
                }
                delete new_leaf;
                continue;
            }

            ArtNode* parent = nullptr;
            ArtNode* current = root;
            size_t depth = 0;
            bool retry_traversal = false;

            while (current) {
                if (current->type == NodeType::Leaf) {
                    auto* leaf = static_cast<LeafNode*>(current);
                    if (leaf->key == key) {
                        out_leaf = leaf;
                        return false; // Found existing leaf
                    }

                    // Key split required: Create common parent and split
                    if (!parent) {
                        if (!root_.load(std::memory_order_relaxed)) {
                            retry_traversal = true;
                            break;
                        }
                    }

                    if (!SynchronizedLeafSplit(parent, leaf, key, initial_version, depth, out_leaf)) {
                        retry_traversal = true;
                    }
                    break;
                }

                // Check prefix match
                uint32_t match_len = 0;
                while (match_len < current->prefix_len && 
                       GetByte(key, depth + match_len) == current->prefix[match_len]) {
                    match_len++;
                }

                if (match_len < current->prefix_len) {
                    // Prefix divergence: Split inner node
                    if (!SynchronizedPrefixSplit(parent, current, key, initial_version, depth, match_len, out_leaf)) {
                        retry_traversal = true;
                    }
                    break;
                }

                depth += current->prefix_len;
                uint8_t byte = GetByte(key, depth);
                ArtNode* next_child = FindChild(current, byte);

                if (!next_child) {
                    // Direct insertion into current node
                    if (!SynchronizedInsertChild(current, byte, new LeafNode(key, initial_version), out_leaf)) {
                        retry_traversal = true;
                    }
                    break;
                }

                parent = current;
                current = next_child;
                depth += 1;
            }

            if (!retry_traversal) return true;
        }
    }

private:
    static ArtNode* FindChild(ArtNode* node, uint8_t byte) {
        switch (node->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(node);
                uint8_t cnt = n->count.load(std::memory_order_relaxed);
                for (uint8_t i = 0; i < cnt; ++i) {
                    if (n->keys[i] == byte) return n->children[i].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(node);
                uint8_t cnt = n->count.load(std::memory_order_relaxed);
                for (uint8_t i = 0; i < cnt; ++i) {
                    if (n->keys[i] == byte) return n->children[i].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(node);
                uint8_t idx = n->child_indices[byte];
                if (idx != Node48::EMPTY_MARKER) {
                    return n->children[idx].load(std::memory_order_acquire);
                }
                return nullptr;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(node);
                return n->children[byte].load(std::memory_order_acquire);
            }
            default:
                return nullptr;
        }
    }

    bool SynchronizedInsertChild(ArtNode* parent, uint8_t byte, LeafNode* leaf, LeafNode*& out_leaf) {
        if (!parent->UpgradeToWriteLock()) {
            delete leaf;
            return false;
        }

        bool ok = false;
        switch (parent->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(parent);
                uint8_t cnt = n->count.load(std::memory_order_relaxed);
                if (cnt < 4) {
                    n->keys[cnt] = byte;
                    n->children[cnt].store(leaf, std::memory_order_release);
                    n->count.store(cnt + 1, std::memory_order_release);
                    ok = true;
                } else {
                    // Grow Node4 -> Node16
                    auto* n16 = new Node16();
                    n16->prefix_len = n->prefix_len;
                    std::memcpy(n16->prefix, n->prefix, n->prefix_len);
                    for (size_t i = 0; i < 4; ++i) {
                        n16->keys[i] = n->keys[i];
                        n16->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                    n16->keys[4] = byte;
                    n16->children[4].store(leaf, std::memory_order_relaxed);
                    n16->count.store(5, std::memory_order_relaxed);

                    ReplaceNodeInParent(parent, n16);
                    EpochManager::Instance().Retire(t_epoch_ctx, n);
                    ok = true;
                }
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(parent);
                uint8_t cnt = n->count.load(std::memory_order_relaxed);
                if (cnt < 16) {
                    n->keys[cnt] = byte;
                    n->children[cnt].store(leaf, std::memory_order_release);
                    n->count.store(cnt + 1, std::memory_order_release);
                    ok = true;
                } else {
                    // Grow Node16 -> Node48
                    auto* n48 = new Node48();
                    n48->prefix_len = n->prefix_len;
                    std::memcpy(n48->prefix, n->prefix, n->prefix_len);
                    for (size_t i = 0; i < 16; ++i) {
                        n48->child_indices[n->keys[i]] = static_cast<uint8_t>(i);
                        n48->children[i].store(n->children[i].load(std::memory_order_relaxed), std::memory_order_relaxed);
                    }
                    n48->child_indices[byte] = 16;
                    n48->children[16].store(leaf, std::memory_order_relaxed);
                    n48->count.store(17, std::memory_order_relaxed);

                    ReplaceNodeInParent(parent, n48);
                    EpochManager::Instance().Retire(t_epoch_ctx, n);
                    ok = true;
                }
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(parent);
                uint8_t cnt = n->count.load(std::memory_order_relaxed);
                if (cnt < 48) {
                    n->child_indices[byte] = cnt;
                    n->children[cnt].store(leaf, std::memory_order_release);
                    n->count.store(cnt + 1, std::memory_order_release);
                    ok = true;
                } else {
                    // Grow Node48 -> Node256
                    auto* n256 = new Node256();
                    n256->prefix_len = n->prefix_len;
                    std::memcpy(n256->prefix, n->prefix, n->prefix_len);
                    for (size_t i = 0; i < 256; ++i) {
                        uint8_t idx = n->child_indices[i];
                        if (idx != Node48::EMPTY_MARKER) {
                            n256->children[i].store(n->children[idx].load(std::memory_order_relaxed), std::memory_order_relaxed);
                        }
                    }
                    n256->children[byte].store(leaf, std::memory_order_relaxed);
                    n256->count.store(49, std::memory_order_relaxed);

                    ReplaceNodeInParent(parent, n256);
                    EpochManager::Instance().Retire(t_epoch_ctx, n);
                    ok = true;
                }
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(parent);
                n->children[byte].store(leaf, std::memory_order_release);
                n->count.fetch_add(1, std::memory_order_relaxed);
                ok = true;
                break;
            }
            default:
                break;
        }

        out_leaf = leaf;
        parent->WriteUnlock();
        return ok;
    }

    bool SynchronizedLeafSplit(ArtNode* parent, LeafNode* existing_leaf, uint64_t key,
                               RecordVersion* initial_version, size_t depth, LeafNode*& out_leaf) {
        auto* new_leaf = new LeafNode(key, initial_version);
        auto* new_n4 = new Node4();

        // Calculate common prefix between keys
        uint32_t common_len = 0;
        while (depth + common_len < 8) {
            uint8_t b1 = GetByte(existing_leaf->key, depth + common_len);
            uint8_t b2 = GetByte(key, depth + common_len);
            if (b1 != b2) break;
            new_n4->prefix[common_len] = b1;
            common_len++;
        }
        new_n4->prefix_len = common_len;

        uint8_t b_existing = GetByte(existing_leaf->key, depth + common_len);
        uint8_t b_new = GetByte(key, depth + common_len);

        new_n4->keys[0] = b_existing;
        new_n4->children[0].store(existing_leaf, std::memory_order_relaxed);
        new_n4->keys[1] = b_new;
        new_n4->children[1].store(new_leaf, std::memory_order_relaxed);
        new_n4->count.store(2, std::memory_order_relaxed);

        if (!parent) {
            ArtNode* old_root = existing_leaf;
            if (root_.compare_exchange_strong(old_root, new_n4, std::memory_order_acq_rel)) {
                out_leaf = new_leaf;
                return true;
            }
        } else {
            if (parent->UpgradeToWriteLock()) {
                ReplaceChild(parent, GetByte(existing_leaf->key, depth - 1), new_n4);
                parent->WriteUnlock();
                out_leaf = new_leaf;
                return true;
            }
        }

        delete new_n4;
        delete new_leaf;
        return false;
    }

    bool SynchronizedPrefixSplit(ArtNode* parent, ArtNode* node, uint64_t key,
                                 RecordVersion* initial_version, size_t depth,
                                 uint32_t match_len, LeafNode*& out_leaf) {
        if (!node->UpgradeToWriteLock()) {
            return false;
        }

        auto* new_parent = new Node4();
        new_parent->prefix_len = match_len;
        std::memcpy(new_parent->prefix, node->prefix, match_len);

        uint8_t split_byte = node->prefix[match_len];
        node->prefix_len -= (match_len + 1);
        std::memmove(node->prefix, node->prefix + match_len + 1, node->prefix_len);

        auto* new_leaf = new LeafNode(key, initial_version);
        uint8_t leaf_byte = GetByte(key, depth + match_len);

        new_parent->keys[0] = split_byte;
        new_parent->children[0].store(node, std::memory_order_relaxed);
        new_parent->keys[1] = leaf_byte;
        new_parent->children[1].store(new_leaf, std::memory_order_relaxed);
        new_parent->count.store(2, std::memory_order_relaxed);

        if (!parent) {
            root_.store(new_parent, std::memory_order_release);
        } else {
            ReplaceChild(parent, GetByte(key, depth - 1), new_parent);
        }

        out_leaf = new_leaf;
        node->WriteUnlock();
        return true;
    }

    void ReplaceChild(ArtNode* parent, uint8_t byte, ArtNode* new_child) {
        switch (parent->type) {
            case NodeType::Node4: {
                auto* n = static_cast<Node4*>(parent);
                for (uint8_t i = 0; i < n->count.load(std::memory_order_relaxed); ++i) {
                    if (n->keys[i] == byte) {
                        n->children[i].store(new_child, std::memory_order_release);
                        return;
                    }
                }
                break;
            }
            case NodeType::Node16: {
                auto* n = static_cast<Node16*>(parent);
                for (uint8_t i = 0; i < n->count.load(std::memory_order_relaxed); ++i) {
                    if (n->keys[i] == byte) {
                        n->children[i].store(new_child, std::memory_order_release);
                        return;
                    }
                }
                break;
            }
            case NodeType::Node48: {
                auto* n = static_cast<Node48*>(parent);
                uint8_t idx = n->child_indices[byte];
                n->children[idx].store(new_child, std::memory_order_release);
                break;
            }
            case NodeType::Node256: {
                auto* n = static_cast<Node256*>(parent);
                n->children[byte].store(new_child, std::memory_order_release);
                break;
            }
            default:
                break;
        }
    }

    void ReplaceNodeInParent(ArtNode* old_node, ArtNode* new_node) {
        ArtNode* r = root_.load(std::memory_order_relaxed);
        if (r == old_node) {
            root_.store(new_node, std::memory_order_release);
        }
    }

    alignas(CACHE_LINE_SIZE) std::atomic<ArtNode*> root_;
};

// ============================================================================
// 4. TRANSACTION ENGINE & OCC PROTOCOL
// ============================================================================

class TransactionManager {
public:
    TransactionManager() : global_ts_(1) {}

    uint64_t GetNextTimestamp() {
        return global_ts_.fetch_add(1, std::memory_order_acq_rel);
    }

    ConcurrentART& GetIndex() { return index_; }

private:
    alignas(CACHE_LINE_SIZE) std::atomic<uint64_t> global_ts_;
    ConcurrentART index_;
};

struct WriteBufferEntry {
    uint64_t key;
    std::vector<uint8_t> data;
    LeafNode* leaf{nullptr};
    RecordVersion* prev_version{nullptr};
};

class Transaction {
public:
    explicit Transaction(TransactionManager& tm) 
        : tm_(tm), read_ts_(tm.GetNextTimestamp()), committed_(false), aborted_(false) {
        epoch_guard_ = std::make_unique<EpochGuard>();
    }

    ~Transaction() {
        if (!committed_ && !aborted_) {
            Abort();
        }
    }

    bool Read(uint64_t key, std::vector<uint8_t>& out_val) {
        if (aborted_) return false;

        // Check local write set first (Read-Your-Own-Writes)
        for (auto it = write_set_.rbegin(); it != write_set_.rend(); ++it) {
            if (it->key == key) {
                out_val = it->data;
                return true;
            }
        }

        // Lock-free traversal to find the leaf node
        LeafNode* leaf = tm_.GetIndex().Lookup(key);
        if (!leaf) {
            return false; // Key does not exist
        }

        // Traverse MVCC version chain for snapshot visibility
        RecordVersion* current = leaf->version_chain_head.load(std::memory_order_acquire);
        while (current) {
            uint64_t b_ts = current->begin_ts.load(std::memory_order_acquire);
            uint64_t e_ts = current->end_ts.load(std::memory_order_acquire);

            if (b_ts <= read_ts_ && read_ts_ < e_ts) {
                out_val.resize(current->val_size);
                if (current->val_size > 0) {
                    std::memcpy(out_val.data(), current->payload, current->val_size);
                }
                // Record read set for serialization validation
                read_set_.push_back({leaf, current});
                return true;
            }
            current = current->prev_version.load(std::memory_order_acquire);
        }

        return false; // No visible version in snapshot
    }

    bool Write(uint64_t key, std::span<const uint8_t> val) {
        if (aborted_) return false;

        std::vector<uint8_t> buffer(val.begin(), val.end());
        for (auto& entry : write_set_) {
            if (entry.key == key) {
                entry.data = std::move(buffer);
                return true;
            }
        }

        write_set_.push_back(WriteBufferEntry{
            .key = key,
            .data = std::move(buffer),
            .leaf = nullptr,
            .prev_version = nullptr
        });
        return true;
    }

    bool Commit() {
        if (aborted_ || committed_) return false;
        if (write_set_.empty()) {
            committed_ = true;
            return true; // Read-only transactions commit immediately
        }

        // 1. Resolve index leaves for write set
        for (auto& entry : write_set_) {
            LeafNode* leaf = nullptr;
            auto* dummy_ver = new RecordVersion(0, entry.data.size(), entry.data.data());
            if (!tm_.GetIndex().InsertOrUpdateLeaf(entry.key, dummy_ver, leaf)) {
                // Leaf already existed; free dummy node
                delete dummy_ver;
            }
            entry.leaf = leaf;
        }

        // 2. Validate Read Set (Anti-Dependency Cycle check for SSI / Repeatable Read)
        for (const auto& read_entry : read_set_) {
            RecordVersion* head = read_entry.leaf->version_chain_head.load(std::memory_order_acquire);
            uint64_t cur_end = read_entry.observed_version->end_ts.load(std::memory_order_acquire);
            // If the version observed in snapshot was overwritten prior to commit, abort
            if (cur_end <= read_ts_) {
                Abort();
                return false;
            }
        }

        // 3. Obtain Commit Timestamp
        uint64_t commit_ts = tm_.GetNextTimestamp();

        // 4. Atomic Multi-Version Installation via CAS
        std::vector<RecordVersion*> allocated_versions;
        for (auto& entry : write_set_) {
            RecordVersion* old_head = entry.leaf->version_chain_head.load(std::memory_order_acquire);

            // Check write-write conflict: if active version modified after read_ts
            if (old_head && old_head->begin_ts.load(std::memory_order_acquire) > read_ts_) {
                // Write-write conflict detected; cleanup uncommitted versions and abort
                for (auto* v : allocated_versions) delete v;
                Abort();
                return false;
            }

            auto* new_ver = new RecordVersion(commit_ts, entry.data.size(), entry.data.data(), old_head);
            allocated_versions.push_back(new_ver);

            // Install new head into leaf
            while (!entry.leaf->version_chain_head.compare_exchange_weak(
                old_head, new_ver, std::memory_order_acq_rel, std::memory_order_acquire)) {

                if (old_head && old_head->begin_ts.load(std::memory_order_acquire) > read_ts_) {
                    for (auto* v : allocated_versions) delete v;
                    Abort();
                    return false;
                }
                new_ver->prev_version.store(old_head, std::memory_order_relaxed);
            }

            // Close validity window of previous version
            if (old_head) {
                old_head->end_ts.store(commit_ts, std::memory_order_release);
            }
        }

        committed_ = true;
        return true;
    }

    void Abort() {
        aborted_ = true;
        write_set_.clear();
        read_set_.clear();
    }

private:
    struct ReadSetEntry {
        LeafNode* leaf;
        RecordVersion* observed_version;
    };

    TransactionManager& tm_;
    uint64_t read_ts_;
    bool committed_;
    bool aborted_;
    std::unique_ptr<EpochGuard> epoch_guard_;

    std::vector<ReadSetEntry> read_set_;
    std::vector<WriteBufferEntry> write_set_;
};

} // namespace MVStore

// ============================================================================
// 5. VERIFICATION & STRESS HARNESS
// ============================================================================

int main() {
    using namespace MVStore;

    std::cout << "========================================================\n";
    std::cout << "Starting High-Throughput MVCC ART Concurrency Engine...\n";
    std::cout << "========================================================\n";

    TransactionManager tm;
    constexpr uint64_t NUM_ACCOUNTS = 100;
    constexpr uint64_t INITIAL_BALANCE = 1000;

    // 1. Initialize Accounts
    std::cout << "[Init] Populating " << NUM_ACCOUNTS << " bank accounts with " << INITIAL_BALANCE << "$...\n";
    {
