        for (uint64_t i = 0; i < NUM_ACCOUNTS; ++i) {
            uint64_t balance = INITIAL_BALANCE;
            init_tx.Write(i, std::span<const uint8_t>(reinterpret_cast<const uint8_t*>(&balance), sizeof(balance)));
        }
        bool ok = init_tx.Commit();
        assert(ok);
    }

    // 2. Launch Concurrent Worker Threads
    constexpr int NUM_WORKERS = 8;
    constexpr int TX_PER_WORKER = 5000;
    std::vector<std::thread> workers;
    std::atomic<uint64_t> total_aborts{0};
    std::atomic<uint64_t> total_commits{0};

    auto worker_fn = [&](int worker_id) {
        for (int i = 0; i < TX_PER_WORKER; ++i) {
            uint64_t src = (worker_id * 13 + i) % NUM_ACCOUNTS;
            uint64_t dst = (worker_id * 17 + i + 1) % NUM_ACCOUNTS;
            if (src == dst) dst = (dst + 1) % NUM_ACCOUNTS;

            Transaction tx(tm);
            std::vector<uint8_t> src_bytes, dst_bytes;

            if (!tx.Read(src, src_bytes) || !tx.Read(dst, dst_bytes)) {
                tx.Abort();
                total_aborts.fetch_add(1, std::memory_order_relaxed);
                continue;
            }

            uint64_t src_bal = *reinterpret_cast<uint64_t*>(src_bytes.data());
            uint64_t dst_bal = *reinterpret_cast<uint64_t*>(dst_bytes.data());

            if (src_bal >= 10) {
                src_bal -= 10;
                dst_bal += 10;

                tx.Write(src, std::span<const uint8_t>(reinterpret_cast<const uint8_t*>(&src_bal), sizeof(src_bal)));
                tx.Write(dst, std::span<const uint8_t>(reinterpret_cast<const uint8_t*>(&dst_bal), sizeof(dst_bal)));

                if (tx.Commit()) {
                    total_commits.fetch_add(1, std::memory_order_relaxed);
                } else {
                    total_aborts.fetch_add(1, std::memory_order_relaxed);
                }
            } else {
                tx.Abort();
                total_aborts.fetch_add(1, std::memory_order_relaxed);
            }
        }
    };

    for (int i = 0; i < NUM_WORKERS; ++i) {
        workers.emplace_back(worker_fn, i);
    }

    for (auto& w : workers) {
        w.join();
    }

    std::cout << "[Workload Complete] Commits: " << total_commits.load() 
              << ", Aborts: " << total_aborts.load() << "\n";

    // 3. Invariant Verification: Total Ledger Balance
    std::cout << "[Verification] Auditing global invariant (conservation of funds)...\n";
    {
        Transaction audit_tx(tm);
        uint64_t total_system_balance = 0;

        for (uint64_t i = 0; i < NUM_ACCOUNTS; ++i) {
            std::vector<uint8_t> val;
            bool ok = audit_tx.Read(i, val);
            assert(ok);
