            total_system_balance += bal;
        }

        bool ok = audit_tx.Commit();
        assert(ok);

        std::cout << "Audit Result: Total Balance = " << total_system_balance 
                  << " (Expected: " << (NUM_ACCOUNTS * INITIAL_BALANCE) << ")\n";
        assert(total_system_balance == (NUM_ACCOUNTS * INITIAL_BALANCE));
    }

    std::cout << "Engine successfully validated under strict Snapshot Isolation.\n";
    return 0;
}
