struct EBR {
    std::atomic<size_t> global_epoch{0}; // 3-epoch model

    struct ThreadLocalState {
        size_t thread_epoch{0};
        bool is_active{false};
        std::vector<void*> retired_objects; // Deferred memory deallocation
    };

    std::array<ThreadLocalState, MaxThreads> thread_states;

    void enter_epoch(size_t thread_id) {
        thread_states[thread_id].is_active = true;
        thread_states[thread_id].thread_epoch = global_epoch.load(std::memory_order_relaxed);
    }

    void exit_epoch(size_t thread_id) {
        thread_states[thread_id].is_active = false;
    }

    void retire_object(void* obj, size_t thread_id) {
        thread_states[thread_id].retired_objects.push_back(obj);
    }

    void advance_global_epoch() {
        size_t new_epoch = global_epoch.load(std::memory_order_relaxed) + 1;
        global_epoch.store(new_epoch, std::memory_order_acq_rel);

        size_t safe_epoch = global_epoch.load(std::memory_order_acquire) - 2;

        // Reclaim memory from all retired buffers
        for (auto& thread_state : thread_states) {
            auto it = thread_state.retired_objects.begin();
            while (it != thread_state.retired_objects.end()) {
                // Safe to delete objects retired in older epochs
                void* obj = *it;
                ++it;
                delete obj;
            }
            thread_state.retired_objects.clear();
        }
    }
};
```

