namespace pointer_tagging {
    static constexpr uintptr_t MARK_MASK = 0x1ULL;

    template <typename T>
    inline bool is_marked(T* ptr) noexcept {
        return (reinterpret_cast<uintptr_t>(ptr) & MARK_MASK) != 0;
