// 3. Epoch-Based Memory Reclamation (3-Epoch Hazard-Free EBR)
// ============================================================================
class EpochReclaimer {
public:
    struct RetiredNode {
        void* ptr;
        void (*deleter)(void*);
    };

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<bool> is_registered{false};
        std::atomic<bool> is_active{false};
        std::atomic<uint64_t> local_epoch{0};

        // 3 Retirement buffers corresponding to (epoch % 3)
        std::vector<RetiredNode> retired_limbo[3];

        // Thread-local fast pseudo-RNG state (XorShift64)
        uint64_t rng_state{0x853c49e6748fea9bULL};

        uint64_t next_random() noexcept {
            uint64_t x = rng_state;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            return rng_state = x;
        }
    };

private:
    const size_t max_threads_;
    std::atomic<uint64_t> global_epoch_{0};
    std::unique_ptr<ThreadControlBlock[]> threads_;

public:
    explicit EpochReclaimer(size_t max_threads)
        : max_threads_(max_threads),
          threads_(std::make_unique<ThreadControlBlock[]>(max_threads)) {}

    ~EpochReclaimer() {
        // Drain and reclaim all memory remaining in limbo lists
        for (size_t i = 0; i < max_threads_; ++i) {
            for (int e = 0; e < 3; ++e) {
                for (auto& item : threads_[i].retired_limbo[e]) {
                    item.deleter(item.ptr);
                }
                threads_[i].retired_limbo[e].clear();
            }
        }
    }

    void register_thread(size_t tid) {
        assert(tid < max_threads_);
        threads_[tid].rng_state ^= (static_cast<uint64_t>(tid + 1) * 0x9e3779b97f4a7c15ULL);
        threads_[tid].is_registered.store(true, std::memory_order_release);
    }

    void unregister_thread(size_t tid) {
        assert(tid < max_threads_);
        exit_epoch(tid);
        try_reclaim_thread_limbo(tid, true);
        threads_[tid].is_registered.store(false, std::memory_order_release);
    }

    inline void enter_epoch(size_t tid) noexcept {
        assert(tid < max_threads_);
        // 1. Announce entry into current global epoch
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);
        threads_[tid].local_epoch.store(current, std::memory_order_relaxed);
        // 2. Publish active status with seq_cst / release to ensure subsequent reads stay inside critical section
        threads_[tid].is_active.store(true, std::memory_order_seq_cst);
    }

    inline void exit_epoch(size_t tid) noexcept {
        assert(tid < max_threads_);
        threads_[tid].is_active.store(false, std::memory_order_seq_cst);
    }

    template <typename T>
    void retire(size_t tid, T* ptr) {
        assert(tid < max_threads_);
        if (!ptr) return;
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t idx = cur_epoch % 3;

        threads_[tid].retired_limbo[idx].push_back({
            ptr,
            [](void* p) { delete static_cast<T*>(p); }
        });

        // Trigger garbage collection if local threshold exceeded
        if (threads_[tid].retired_limbo[idx].size() >= 64) {
            try_advance_and_reclaim(tid);
        }
    }

    void try_advance_and_reclaim(size_t tid) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Check if all active threads have witnessed the current epoch
        bool can_advance = true;
        for (size_t i = 0; i < max_threads_; ++i) {
            if (threads_[i].is_registered.load(std::memory_order_acquire) &&
                threads_[i].is_active.load(std::memory_order_seq_cst)) {
                if (threads_[i].local_epoch.load(std::memory_order_acquire) < cur_epoch) {
                    can_advance = false;
                    break;
                }
            }
        }

        if (can_advance) {
            global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, std::memory_order_acq_rel);
        }

        try_reclaim_thread_limbo(tid, false);
    }

    void try_reclaim_thread_limbo(size_t tid, bool force_all) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        for (int i = 0; i < 3; ++i) {
            // Buffer is safe to free if it was retired 2 epochs ago: (cur_epoch >= retire_epoch + 2)
            // In a 3-epoch scheme, bucket ((cur_epoch + 1) % 3) holds objects retired <= cur_epoch - 2.
            if (force_all || (i != (cur_epoch % 3) && i != ((cur_epoch + 2) % 3))) {
                auto& list = threads_[tid].retired_limbo[i];
                for (auto& item : list) {
                    item.deleter(item.ptr);
                }
                list.clear();
            }
        }
    }

    uint64_t get_random_level(size_t tid, size_t max_height) noexcept {
        uint64_t r = threads_[tid].next_random();
        // Count trailing zeros gives geometric distribution with p = 0.5
        uint64_t level = 1;
        if (r == 0) return max_height;
        level += static_cast<uint64_t>(__builtin_ctzll(r));
        return level > max_height ? max_height : level;
    }
};

