// 4. Lock-Free MVCC Skip List Implementation
// ============================================================================
template <typename Key, typename Value, typename KeyComparator = std::less<Key>>
class LockFreeMVCCIndex {
public:
    static constexpr size_t MAX_HEIGHT = 32;

    struct IndexNode {
        Key key;
        size_t height;
        std::atomic<VersionNode<Value>*> versions{nullptr};
        std::atomic<IndexNode*> next[MAX_HEIGHT];

        IndexNode(const Key& k, size_t h) : key(k), height(h) {
            for (size_t i = 0; i < MAX_HEIGHT; ++i) {
                next[i].store(nullptr, std::memory_order_relaxed);
            }
        }
    };

private:
    KeyComparator comp_;
    size_t max_threads_;
    EpochReclaimer ebr_;
    IndexNode* head_;
    IndexNode* tail_;

    bool key_less(const Key& a, const Key& b) const noexcept {
        return comp_(a, b);
    }

    bool key_equal(const Key& a, const Key& b) const noexcept {
        return !comp_(a, b) && !comp_(b, a);
    }

    /**
     * Lock-Free Skip List Core Traversal & Helper:
     * Searches for key and cooperatively helps unlinking logically deleted (marked) nodes.
     */
    bool find_position(size_t tid, const Key& key, IndexNode* preds[], IndexNode* succs[]) {
        bool retry = false;
        do {
            retry = false;
            IndexNode* pred = head_;
            for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
                IndexNode* curr = pred->next[level].load(std::memory_order_acquire);

                while (true) {
                    if (curr == nullptr) {
                        // End of list at this level
                        succs[level] = nullptr;
                        preds[level] = pred;
                        break;
                    }

                    IndexNode* succ = curr->next[level].load(std::memory_order_acquire);

                    // Check if curr is logically marked for physical deletion at this level
                    while (pointer_tagging::is_marked(succ)) {
                        IndexNode* unmarked_succ = pointer_tagging::get_unmarked(succ);
                        // Cooperative physical unlinking via CAS
                        if (!pred->next[level].compare_exchange_strong(
                                curr, unmarked_succ, std::memory_order_acq_rel, std::memory_order_acquire)) {
                            retry = true;
                            break; // CAS failed: another thread modified pred->next[level]
                        }

                        // If unlinked at bottom level (level 0), retire to EBR
                        if (level == 0) {
                            ebr_.retire(tid, curr);
                        }

                        curr = unmarked_succ;
                        if (curr == nullptr) break;
                        succ = curr->next[level].load(std::memory_order_acquire);
                    }

                    if (retry) break;

                    if (curr == tail_ || curr == nullptr) {
                        preds[level] = pred;
                        succs[level] = curr;
                        break;
                    }

                    if (!key_less(curr->key, key)) {
                        // curr->key >= key
                        preds[level] = pred;
                        succs[level] = curr;
                        break;
                    }

                    pred = curr;
                    curr = pointer_tagging::get_unmarked(succ);
                }

                if (retry) break;
            }
        } while (retry);

        return (succs[0] != tail_ && succs[0] != nullptr && key_equal(succs[0]->key, key));
    }

    /**
     * Mark an index node for logical deletion across all levels (top-down to bottom).
     */
    void mark_index_node_deleted(IndexNode* node) {
        for (int l = static_cast<int>(node->height) - 1; l >= 0; --l) {
            IndexNode* succ = node->next[l].load(std::memory_order_acquire);
            while (!pointer_tagging::is_marked(succ)) {
                IndexNode* marked = pointer_tagging::get_marked(succ);
                if (node->next[l].compare_exchange_weak(
                        succ, marked, std::memory_order_acq_rel, std::memory_order_acquire)) {
                    break;
                }
                // succ reloaded by compare_exchange_weak
            }
        }
    }

public:
    explicit LockFreeMVCCIndex(size_t max_threads = 256)
        : max_threads_(max_threads),
          ebr_(max_threads) {
        // Allocate boundary sentinel nodes
        head_ = new IndexNode(Key(), MAX_HEIGHT);
        tail_ = new IndexNode(Key(), MAX_HEIGHT);

        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            head_->next[i].store(tail_, std::memory_order_relaxed);
            tail_->next[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    ~LockFreeMVCCIndex() {
        IndexNode* curr = head_;
        while (curr != nullptr) {
            IndexNode* next = pointer_tagging::get_unmarked(curr->next[0].load(std::memory_order_relaxed));
            // Free MVCC chain
            VersionNode<Value>* v_curr = curr->versions.load(std::memory_order_relaxed);
            while (v_curr != nullptr) {
                VersionNode<Value>* v_next = v_curr->next_version.load(std::memory_order_relaxed);
                delete v_curr;
                v_curr = v_next;
            }
            delete curr;
            curr = next;
        }
    }

    // Thread Registration Hooks
    void register_thread(size_t thread_id) { ebr_.register_thread(thread_id); }
    void unregister_thread(size_t thread_id) { ebr_.unregister_thread(thread_id); }
    void enter_epoch(size_t thread_id) { ebr_.enter_epoch(thread_id); }
    void exit_epoch(size_t thread_id) { ebr_.exit_epoch(thread_id); }

    // ========================================================================
    // Snapshot Read: Lock-Free & Zero-Allocation
    // ========================================================================
    bool get(size_t thread_id, const Key& key, uint64_t tx_snapshot_id, Value& out_value) {
        enter_epoch(thread_id);

        IndexNode* pred = head_;
        IndexNode* target = nullptr;

        // Traverse skip list without physical unlinking to ensure bounded read latency
        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            IndexNode* curr = pointer_tagging::get_unmarked(pred->next[level].load(std::memory_order_acquire));
            while (curr != nullptr && curr != tail_) {
                if (!key_less(curr->key, key)) {
                    if (key_equal(curr->key, key)) {
                        target = curr;
                    }
                    break;
                }
                pred = curr;
                curr = pointer_tagging::get_unmarked(curr->next[level].load(std::memory_order_acquire));
            }
            if (target != nullptr) break;
        }

        if (target == nullptr) {
            exit_epoch(thread_id);
            return false;
        }

        // Traverse MVCC version chain (ordered newest -> oldest)
        VersionNode<Value>* v = target->versions.load(std::memory_order_acquire);
        while (v != nullptr) {
            uint64_t created = v->created_tx_id;
            uint64_t expired = v->expired_tx_id.load(std::memory_order_acquire);

            // Visibility Predicate: created <= T_read < expired
            if (created <= tx_snapshot_id && tx_snapshot_id < expired) {
                if (v->is_tombstone) {
                    exit_epoch(thread_id);
                    return false; // Record is logically deleted at snapshot
                }
                out_value = v->payload;
                exit_epoch(thread_id);
                return true;
            }
            v = v->next_version.load(std::memory_order_acquire);
        }

        exit_epoch(thread_id);
        return false;
    }

    // ========================================================================
    // Insert: Creates new key or prepends new version if inactive
    // ========================================================================
    bool insert(size_t thread_id, const Key& key, const Value& value, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];

        while (true) {
            bool found = find_position(thread_id, key, preds, succs);
            if (found) {
                IndexNode* node = succs[0];
                VersionNode<Value>* head_ver = node->versions.load(std::memory_order_acquire);

                // If top version is alive and not a tombstone, insert fails (key collision)
                if (head_ver != nullptr && !head_ver->is_tombstone && 
                    head_ver->expired_tx_id.load(std::memory_order_acquire) == std::numeric_limits<uint64_t>::max()) {
                    exit_epoch(thread_id);
                    return false; // Active key already exists
                }

                // If prior version was deleted, prepend new active version
                auto* new_version = new VersionNode<Value>(tx_id, std::numeric_limits<uint64_t>::max(), head_ver, false, value);
                if (node->versions.compare_exchange_weak(head_ver, new_version, 
                        std::memory_order_release, std::memory_order_acquire)) {
                    if (head_ver != nullptr) {
                        head_ver->expired_tx_id.store(tx_id, std::memory_order_release);
                    }
                    exit_epoch(thread_id);
                    return true;
                } else {
                    delete new_version;
                    continue; // Version CAS contention retry
                }
            }

            // Key does not exist: create new IndexNode
            size_t new_height = ebr_.get_random_level(thread_id, MAX_HEIGHT);
            auto* new_node = new IndexNode(key, new_height);
            auto* initial_ver = new VersionNode<Value>(tx_id, std::numeric_limits<uint64_t>::max(), nullptr, false, value);
            new_node->versions.store(initial_ver, std::memory_order_relaxed);

            for (size_t i = 0; i < new_height; ++i) {
                new_node->next[i].store(succs[i], std::memory_order_relaxed);
            }

            // Splice bottom level first
            if (!preds[0]->next[0].compare_exchange_strong(
                    succs[0], new_node, std::memory_order_release, std::memory_order_acquire)) {
                // Splicing failed; clean up and retry
                delete initial_ver;
                delete new_node;
                continue;
            }

            // Splice remaining levels
            for (size_t i = 1; i < new_height; ++i) {
                while (true) {
                    IndexNode* pred = preds[i];
                    IndexNode* succ = succs[i];
                    new_node->next[i].store(succ, std::memory_order_relaxed);
                    if (pred->next[i].compare_exchange_strong(
                            succ, new_node, std::memory_order_release, std::memory_order_acquire)) {
                        break;
                    }
                    // Re-find position on splice failure
                    find_position(thread_id, key, preds, succs);
                }
            }

            exit_epoch(thread_id);
            return true;
        }
    }

    // ========================================================================
    // Update: Atomically prepends new version to existing active record
    // ========================================================================
    bool update(size_t thread_id, const Key& key, const Value& value, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];

        while (true) {
            bool found = find_position(thread_id, key, preds, succs);
            if (!found) {
                exit_epoch(thread_id);
                return false; // Key does not exist
            }

            IndexNode* node = succs[0];
            VersionNode<Value>* head_ver = node->versions.load(std::memory_order_acquire);

            if (head_ver == nullptr || head_ver->is_tombstone || 
                head_ver->expired_tx_id.load(std::memory_order_acquire) != std::numeric_limits<uint64_t>::max()) {
                exit_epoch(thread_id);
                return false; // Key is deleted
            }

            // Must preserve monotonic commit ordering
            if (head_ver->created_tx_id >= tx_id) {
                exit_epoch(thread_id);
                return false;
            }

            auto* new_version = new VersionNode<Value>(tx_id, std::numeric_limits<uint64_t>::max(), head_ver, false, value);
            if (node->versions.compare_exchange_weak(head_ver, new_version, 
                    std::memory_order_release, std::memory_order_acquire)) {
                // Seal previous version
                head_ver->expired_tx_id.store(tx_id, std::memory_order_release);
                exit_epoch(thread_id);
                return true;
            } else {
                delete new_version; // Contention retry
            }
        }
    }

    // ========================================================================
    // Remove: Prepends tombstone version
    // ========================================================================
    bool remove(size_t thread_id, const Key& key, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];

        while (true) {
            bool found = find_position(thread_id, key, preds, succs);
            if (!found) {
                exit_epoch(thread_id);
                return false;
            }

            IndexNode* node = succs[0];
            VersionNode<Value>* head_ver = node->versions.load(std::memory_order_acquire);

            if (head_ver == nullptr || head_ver->is_tombstone ||
                head_ver->expired_tx_id.load(std::memory_order_acquire) != std::numeric_limits<uint64_t>::max()) {
                exit_epoch(thread_id);
                return false; // Already deleted
            }

            auto* tombstone = new VersionNode<Value>(tx_id, std::numeric_limits<uint64_t>::max(), head_ver, true);
            if (node->versions.compare_exchange_weak(head_ver, tombstone, 
                    std::memory_order_release, std::memory_order_acquire)) {
                head_ver->expired_tx_id.store(tx_id, std::memory_order_release);
                exit_epoch(thread_id);
                return true;
            } else {
                delete tombstone;
            }
        }
    }

    // ========================================================================
    // Maintenance & Physical Garbage Collection
    // ========================================================================
    void advance_epoch_and_reclaim(uint64_t min_active_tx_id) {
        // Step 1: Scan bottom level to prune obsolete versions & mark dead index nodes
        IndexNode* curr = pointer_tagging::get_unmarked(head_->next[0].load(std::memory_order_acquire));
        while (curr != nullptr && curr != tail_) {
            if (!pointer_tagging::is_marked(curr->next[0].load(std::memory_order_relaxed))) {
                prune_version_chain(0, curr, min_active_tx_id);
            }
            curr = pointer_tagging::get_unmarked(curr->next[0].load(std::memory_order_acquire));
        }

        // Step 2: Advance EBR epoch and reclaim safe memory buffers
        ebr_.try_advance_and_reclaim(0);
    }

    void prune_version_chain(size_t tid, IndexNode* node, uint64_t min_active_tx_id) {
        VersionNode<Value>* v = node->versions.load(std::memory_order_acquire);
        if (!v) return;

        // If top version is a tombstone and expired <= min_active_tx_id, entire index node is dead
        if (v->is_tombstone && v->created_tx_id <= min_active_tx_id) {
            mark_index_node_deleted(node);
            return;
        }

        // Prune tail versions older than min_active_tx_id
        while (v != nullptr) {
            VersionNode<Value>* next_v = v->next_version.load(std::memory_order_acquire);
            if (next_v != nullptr) {
                uint64_t next_exp = next_v->expired_tx_id.load(std::memory_order_acquire);
                if (next_exp <= min_active_tx_id) {
                    // Atomically cut older versions
                    if (v->next_version.compare_exchange_strong(next_v, nullptr, std::memory_order_acq_rel)) {
                        // Retire unlinked suffix
                        while (next_v != nullptr) {
                            VersionNode<Value>* n = next_v->next_version.load(std::memory_order_relaxed);
                            ebr_.retire(tid, next_v);
                            next_v = n;
                        }
                        break;
                    }
                }
            }
            v = next_v;
        }
    }

    // ========================================================================
    // Observability & Verification
    // ========================================================================
    size_t approximate_size() const {
        size_t count = 0;
        IndexNode* curr = pointer_tagging::get_unmarked(head_->next[0].load(std::memory_order_acquire));
        while (curr != nullptr && curr != tail_) {
            if (!pointer_tagging::is_marked(curr->next[0].load(std::memory_order_relaxed))) {
                VersionNode<Value>* v = curr->versions.load(std::memory_order_acquire);
                if (v && !v->is_tombstone) {
                    ++count;
                }
            }
            curr = pointer_tagging::get_unmarked(curr->next[0].load(std::memory_order_acquire));
        }
        return count;
    }

    void validate_internal_invariants() const {
        for (size_t l = 0; l < MAX_HEIGHT; ++l) {
            IndexNode* curr = head_;
            IndexNode* next = pointer_tagging::get_unmarked(curr->next[l].load(std::memory_order_acquire));
            while (next != nullptr && next != tail_) {
                assert(!key_less(next->key, curr->key) || curr == head_);
                curr = next;
                next = pointer_tagging::get_unmarked(curr->next[l].load(std::memory_order_acquire));
            }
        }
    }
};
```

---

### Formal Concurrency & Linearizability Proof

#### 1. Snapshot Read Linearizability & Wait-Freedom
* **Linearization Point**: For an active read transaction at snapshot $T_{\text{read}}$, the linearization point is the exact atomic load of `node->versions.load(std::memory_order_acquire)`.
* **Visibility Invariant**: A version $V$ satisfies visibility if and only if:
  $$V.created\_tx\_id \le T_{\text{read}} < V.expired\_tx\_id$$
* **Proof of Wait-Freedom / Bounded Traversal**:
  1. Readers do not perform CAS, acquire locks, or assist in physical unlinking; they only follow unmarked pointers via `pointer_tagging::get_unmarked`.
  2. A concurrent insertion prepends to the version chain via `compare_exchange_weak`. Because versions are appended at strictly ascending commit timestamps ($T_{\text{commit}}$) and the chain is immutable once sealed ($expired\_tx\_id$ transitions once from $\infty \to T_{\text{commit}}$), no reader can observe a transient half-written state.
  3. Physical deletion of nodes or versions is deferred by EBR until all active reader epochs have completed ($E \ge E_{\text{retired}} + 2$). Thus, reading along any pointer chain is guaranteed to encounter valid, un-reclaimed memory addresses, ensuring reads are strictly wait-free $O(H + V_{\text{depth}})$.

#### 2. Non-blocking Insertion and Unlinking (No Lost Updates or ABA)
* **Tower Insertion**: 
  - An insertion executes CAS on `pred->next[0]`. If concurrent mutations occur, CAS fails, and the thread re-reads `pred` and `succ` from the current state.
  - Higher levels are spliced bottom-up. Even if higher level links are partially complete, lower levels guarantee key reachability.
* **Cooperative Physical Unlinking**:
  - Logical deletion tags bit `0x1` of `curr->next[level]`.
  - Once tagged, any inserting thread attempting to splice after `curr` will fail its CAS (since the expected unmarked pointer does not match the tagged pointer).
  - Traversing threads encountering marked pointers execute `pred->next[level].compare_exchange_strong(curr, succ_unmarked)`. This atomically bypasses `curr`.
* **ABA Prevention**: 
  - 64-bit heap allocations are aligned to 8-byte boundaries, guaranteeing the low bit is strictly 0.
  - Node addresses are not reused immediately; deallocation occurs strictly through 3-Epoch EBR, precluding the ABA hazard where an address is freed and re-allocated while another thread is executing a CAS.

---

### Hardware Memory Ordering Rationale

| Operation | Memory Order | Hardware Rationale (ARM64 / x86-64) |
| :--- | :--- | :--- |
| `versions.load()` | `memory_order_acquire` | Prevents speculative hoisting of payload/version reads before verifying version head pointer. On ARM64 emits `LDAR` (Load-Acquire); on x86 compiles to a standard `MOV` with compiler barrier. |
| `versions.compare_exchange()` | `memory_order_release` (succ) / `acquire` (fail) | Ensures the newly constructed `VersionNode` payload and fields are visible across all cores before the head pointer publishes the node address. |
| `expired_tx_id.store()` | `memory_order_release` | Enforces that all modifications to the newer version precede sealing the old version's lifetime boundary. |
| `next[l].load()` | `memory_order_acquire` | Synchronizes with `next[l].compare_exchange(release)` from concurrent inserters/unlinkers, establishing a happens-before relationship for node initialization. |
| `next[0].compare_exchange()` | `memory_order_acq_rel` | Must both acquire the previous link state and release the newly spliced node to subsequent traversers. Translates to `LOCK CMPXCHG` on x86 and `LDAXR`/`STLXR` loop on ARM64. |
| `threads_[tid].is_active.store()` | `memory_order_seq_cst` | Implements Dekker-style synchronization between thread epoch announcement and global epoch advancement. Prevents store-load reordering across CPU store buffers (`MFENCE` or `DMB ISH`). |
| `rng_state` operations | `memory_order_relaxed` | Independent per-thread RNG state; requires no inter-thread synchronization. |

