### Part 1: C++20 Source Implementation

```cpp
#pragma once

#include <atomic>
#include <cstdint>
#include <cstddef>
#include <concepts>
#include <functional>
#include <optional>
#include <vector>
#include <memory>
#include <new>
#include <iostream>
#include <cassert>

#ifdef __cpp_lib_hardware_interference_size
    using std::hardware_destructive_interference_size;
#else
    // Standard L1 cache line size fallback
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

template <typename Key, typename Value, typename KeyComparator = std::less<Key>>
class LockFreeMVCCIndex {
public:
    static constexpr size_t MAX_HEIGHT = 32;
    static constexpr double P_FACTOR = 0.5;

    // -------------------------------------------------------------------------
    // Node Structures
    // -------------------------------------------------------------------------

    struct VersionNode {
        uint64_t created_tx_id;                 // Tx ID that created this version
        std::atomic<uint64_t> expired_tx_id;    // Tx ID that invalidated this version (UINT64_MAX if active)
        std::atomic<VersionNode*> next_version; // Pointer to older version
        bool is_tombstone;                      // True if this record represents a deletion
        Value payload;                          // User value

        VersionNode(uint64_t created_tx, uint64_t expired_tx, bool tombstone, const Value& val)
            : created_tx_id(created_tx),
              expired_tx_id(expired_tx),
              next_version(nullptr),
              is_tombstone(tombstone),
              payload(val) {}

        VersionNode(uint64_t created_tx, uint64_t expired_tx, bool tombstone)
            : created_tx_id(created_tx),
              expired_tx_id(expired_tx),
              next_version(nullptr),
              is_tombstone(tombstone),
              payload() {}
    };

    struct IndexNode {
        Key key;
        size_t top_level;                       // Node height: [0, top_level]
        std::atomic<VersionNode*> version_head; // Head of version chain (newest first)
        std::atomic<uintptr_t> next[MAX_HEIGHT];// Marked pointers for lock-free skip list

        IndexNode(const Key& k, size_t height, VersionNode* initial_version)
            : key(k), top_level(height - 1), version_head(initial_version) {
            for (size_t i = 0; i < MAX_HEIGHT; ++i) {
                next[i].store(0, std::memory_order_relaxed);
            }
        }
    };

private:
    // -------------------------------------------------------------------------
    // Pointer Tagging Utilities (Lowest bit indicates logical deletion)
    // -------------------------------------------------------------------------
    static constexpr uintptr_t MARK_MASK = 0x1;

    static inline bool is_marked(uintptr_t ptr) noexcept {
        return (ptr & MARK_MASK) != 0;
    }

    static inline IndexNode* get_unmarked_ptr(uintptr_t ptr) noexcept {
        return reinterpret_cast<IndexNode*>(ptr & ~MARK_MASK);
    }

    static inline uintptr_t make_marked(uintptr_t ptr) noexcept {
        return ptr | MARK_MASK;
    }

    static inline uintptr_t make_unmarked(IndexNode* ptr) noexcept {
        return reinterpret_cast<uintptr_t>(ptr);
    }

    // -------------------------------------------------------------------------
    // Thread-Safe, Zero-Allocation Geometric RNG
    // -------------------------------------------------------------------------
    static inline uint64_t xorshift64star(uint64_t& state) noexcept {
        state ^= state >> 12;
        state ^= state << 25;
        state ^= state >> 27;
        return state * 0x2545F4914F6CDD1DULL;
    }

    size_t generate_random_height(size_t thread_id) noexcept {
        // Fast thread-local pseudo-random level generator
        static thread_local uint64_t tl_rng_state = 0x853c49e6748fea9bULL + (thread_id + 1) * 0x9e3779b97f4a7c15ULL;
        uint64_t rnd = xorshift64star(tl_rng_state);
        // Count trailing zeros gives a geometric distribution with p = 0.5
        size_t lvl = 1;
        if (rnd != 0) {
            lvl += static_cast<size_t>(__builtin_ctzll(rnd));
        }
        return (lvl > MAX_HEIGHT) ? MAX_HEIGHT : (lvl == 0 ? 1 : lvl);
    }

    // -------------------------------------------------------------------------
    // Epoch-Based Reclamation (EBR) Types & Layouts
    // -------------------------------------------------------------------------
    struct RetiredElement {
        void* ptr;
        void (*deleter)(void*);
    };

    struct alignas(hardware_destructive_interference_size) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{UINT64_MAX}; // UINT64_MAX = inactive
        std::atomic<bool> is_active{false};
        std::atomic<bool> registered{false};

        // 3 Epoch retirement buckets
        std::vector<RetiredElement> retired_limbo[3];
    };

    // Index & EBR state members
    KeyComparator comparator_;
    size_t max_threads_;
    IndexNode* head_;
    IndexNode* tail_;

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_{0};
    ThreadControlBlock* thread_registry_;

    // Deleter functions
    static void delete_index_node(void* ptr) {
        delete static_cast<IndexNode*>(ptr);
    }

    static void delete_version_node(void* ptr) {
        delete static_cast<VersionNode*>(ptr);
    }

    void retire_node(size_t thread_id, void* ptr, void (*deleter)(void*)) {
        uint64_t epoch = global_epoch_.load(std::memory_order_relaxed);
        thread_registry_[thread_id].retired_limbo[epoch % 3].push_back({ptr, deleter});
    }

public:
    // -------------------------------------------------------------------------
    // Lifecycle & Epoch API
    // -------------------------------------------------------------------------

    explicit LockFreeMVCCIndex(size_t max_threads = 256)
        : max_threads_(max_threads) {
        // Allocate cache-line aligned per-thread tracking structures
        thread_registry_ = new ThreadControlBlock[max_threads_];

        // Sentinel Head & Tail construction
        head_ = new IndexNode(Key(), MAX_HEIGHT, nullptr);
        tail_ = new IndexNode(Key(), MAX_HEIGHT, nullptr);

        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            head_->next[i].store(make_unmarked(tail_), std::memory_order_relaxed);
            tail_->next[i].store(0, std::memory_order_relaxed);
        }
    }

    ~LockFreeMVCCIndex() {
        // Clean up remaining elements across all retired buckets
        for (size_t t = 0; t < max_threads_; ++t) {
            for (size_t b = 0; b < 3; ++b) {
                for (auto& elem : thread_registry_[t].retired_limbo[b]) {
                    elem.deleter(elem.ptr);
                }
                thread_registry_[t].retired_limbo[b].clear();
            }
        }

        // Clean up Skip List towers and Version chains
        IndexNode* curr = get_unmarked_ptr(head_->next[0].load(std::memory_order_relaxed));
        while (curr && curr != tail_) {
            IndexNode* next_node = get_unmarked_ptr(curr->next[0].load(std::memory_order_relaxed));

            // Delete version chain
            VersionNode* v = curr->version_head.load(std::memory_order_relaxed);
            while (v) {
                VersionNode* v_next = v->next_version.load(std::memory_order_relaxed);
                delete v;
                v = v_next;
            }

            delete curr;
            curr = next_node;
        }

        delete head_;
        delete tail_;
        delete[] thread_registry_;
    }

    LockFreeMVCCIndex(const LockFreeMVCCIndex&) = delete;
    LockFreeMVCCIndex& operator=(const LockFreeMVCCIndex&) = delete;

    void register_thread(size_t thread_id) {
        assert(thread_id < max_threads_);
        thread_registry_[thread_id].registered.store(true, std::memory_order_release);
    }

    void unregister_thread(size_t thread_id) {
        assert(thread_id < max_threads_);
        exit_epoch(thread_id);
        thread_registry_[thread_id].registered.store(false, std::memory_order_release);
    }

    inline void enter_epoch(size_t thread_id) noexcept {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        thread_registry_[thread_id].local_epoch.store(g_epoch, std::memory_order_relaxed);
        thread_registry_[thread_id].is_active.store(true, std::memory_order_release);
    }

    inline void exit_epoch(size_t thread_id) noexcept {
        thread_registry_[thread_id].is_active.store(false, std::memory_order_release);
        thread_registry_[thread_id].local_epoch.store(UINT64_MAX, std::memory_order_relaxed);
    }

private:
    // -------------------------------------------------------------------------
    // Lock-Free Skip List Core Operations (Fraser/Herlihy Algorithm)
    // -------------------------------------------------------------------------

    bool search_position(const Key& key, IndexNode** preds, IndexNode** succs) noexcept {
    retry:
        IndexNode* pred = head_;
        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            uintptr_t curr_val = pred->next[level].load(std::memory_order_acquire);
            IndexNode* curr = get_unmarked_ptr(curr_val);

            while (true) {
                if (curr == nullptr || curr == tail_) {
                    break;
                }

                uintptr_t succ_val = curr->next[level].load(std::memory_order_acquire);

                // Cooperative physical unlinking of logically deleted nodes
                while (is_marked(succ_val)) {
                    uintptr_t expected = make_unmarked(curr);
                    if (!pred->next[level].compare_exchange_weak(
                            expected, make_unmarked(get_unmarked_ptr(succ_val)),
                            std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }
                    curr = get_unmarked_ptr(succ_val);
                    if (curr == nullptr || curr == tail_) break;
                    succ_val = curr->next[level].load(std::memory_order_acquire);
                }

                if (curr != nullptr && curr != tail_ && comparator_(curr->key, key)) {
                    pred = curr;
                    curr = get_unmarked_ptr(succ_val);
                } else {
                    break;
                }
            }
            preds[level] = pred;
            succs[level] = curr;
        }

        // Return true if an exact, unmarked key match exists at level 0
        if (succs[0] != nullptr && succs[0] != tail_ && !comparator_(key, succs[0]->key) && !comparator_(succs[0]->key, key)) {
            uintptr_t l0_link = succs[0]->next[0].load(std::memory_order_acquire);
            return !is_marked(l0_link);
        }
        return false;
    }

    bool logically_delete_node(IndexNode* node) noexcept {
        for (int level = static_cast<int>(node->top_level); level >= 0; --level) {
            uintptr_t succ = node->next[level].load(std::memory_order_acquire);
            while (!is_marked(succ)) {
                if (node->next[level].compare_exchange_weak(
                        succ, make_marked(succ),
                        std::memory_order_acq_rel, std::memory_order_acquire)) {
                    break;
                }
            }
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // Lock-Free MVCC Chain Operations
    // -------------------------------------------------------------------------

    bool try_prepend_version(IndexNode* node, VersionNode* new_version, uint64_t tx_id) noexcept {
        VersionNode* current_head = node->version_head.load(std::memory_order_acquire);
        while (true) {
            // Validate serializability invariant
            if (current_head != nullptr && current_head->created_tx_id >= tx_id) {
                // Write conflict: Newer or identical transaction version exists
                return false;
            }

            new_version->next_version.store(current_head, std::memory_order_relaxed);
            if (node->version_head.compare_exchange_weak(
                    current_head, new_version,
                    std::memory_order_acq_rel, std::memory_order_acquire)) {
                // Prepend succeeded: Invalidate previous active version atomically
                if (current_head != nullptr) {
                    current_head->expired_tx_id.store(tx_id, std::memory_order_release);
                }
                return true;
            }
        }
    }

public:
    // -------------------------------------------------------------------------
    // Public MVCC Transactional Operations
    // -------------------------------------------------------------------------

    bool insert(size_t thread_id, const Key& key, const Value& value, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];
        VersionNode* v_node = new VersionNode(tx_id, UINT64_MAX, false, value);

        while (true) {
            if (search_position(key, preds, succs)) {
                // Key already exists in index: try appending version
                IndexNode* existing = succs[0];
                if (try_prepend_version(existing, v_node, tx_id)) {
                    exit_epoch(thread_id);
                    return true;
                } else {
                    delete v_node;
                    exit_epoch(thread_id);
                    return false;
                }
            }

            // Key does not exist: create tower
            size_t height = generate_random_height(thread_id);
            IndexNode* new_node = new IndexNode(key, height, v_node);

            for (size_t i = 0; i < height; ++i) {
                new_node->next[i].store(make_unmarked(succs[i]), std::memory_order_relaxed);
            }

            // Link bottom level first (linearization point for Skip List insertion)
            uintptr_t expected = make_unmarked(succs[0]);
            if (!preds[0]->next[0].compare_exchange_strong(
                    expected, make_unmarked(new_node),
                    std::memory_order_release, std::memory_order_acquire)) {
                // CAS failed: retry search
                delete new_node;
                continue;
            }

            // Successfully inserted at level 0; link higher levels
            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    expected = make_unmarked(succs[i]);
                    if (preds[i]->next[i].compare_exchange_weak(
                            expected, make_unmarked(new_node),
                            std::memory_order_release, std::memory_order_acquire)) {
                        break;
                    }
                    // Re-synchronize preds and succs for higher level
                    search_position(key, preds, succs);
                }
            }

            exit_epoch(thread_id);
            return true;
        }
    }

    bool update(size_t thread_id, const Key& key, const Value& value, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];

        if (!search_position(key, preds, succs)) {
            exit_epoch(thread_id);
            return false;
        }

        IndexNode* node = succs[0];
        VersionNode* v_node = new VersionNode(tx_id, UINT64_MAX, false, value);

        if (!try_prepend_version(node, v_node, tx_id)) {
            delete v_node;
            exit_epoch(thread_id);
            return false;
        }

        exit_epoch(thread_id);
        return true;
    }

    bool remove(size_t thread_id, const Key& key, uint64_t tx_id) {
        enter_epoch(thread_id);

        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];

        if (!search_position(key, preds, succs)) {
            exit_epoch(thread_id);
            return false;
        }

        IndexNode* node = succs[0];
        VersionNode* tombstone = new VersionNode(tx_id, UINT64_MAX, true);

        if (!try_prepend_version(node, tombstone, tx_id)) {
            delete tombstone;
            exit_epoch(thread_id);
            return false;
        }

        exit_epoch(thread_id);
        return true;
    }

    // -------------------------------------------------------------------------
    // Lock-Free Snapshot Read
    // -------------------------------------------------------------------------
    bool get(size_t thread_id, const Key& key, uint64_t tx_snapshot_id, Value& out_value) {
        enter_epoch(thread_id);

        IndexNode* pred = head_;
        IndexNode* curr = nullptr;

        // Bounded lock-free point lookup down the levels
        for (int level = static_cast<int>(MAX_HEIGHT) - 1; level >= 0; --level) {
            uintptr_t curr_val = pred->next[level].load(std::memory_order_acquire);
            curr = get_unmarked_ptr(curr_val);

            while (curr != nullptr && curr != tail_) {
                if (!comparator_(curr->key, key)) {
                    break;
                }
                pred = curr;
                curr = get_unmarked_ptr(curr->next[level].load(std::memory_order_acquire));
            }
        }

        if (curr != nullptr && curr != tail_ && !comparator_(key, curr->key) && !comparator_(curr->key, key)) {
            // Key match: Traverse immutable version chain lock-free
            VersionNode* v = curr->version_head.load(std::memory_order_acquire);
            while (v != nullptr) {
                uint64_t c_tx = v->created_tx_id;
                uint64_t e_tx = v->expired_tx_id.load(std::memory_order_acquire);

                // Visibility condition: created_tx_id <= tx_snapshot_id < expired_tx_id
                if (c_tx <= tx_snapshot_id && tx_snapshot_id < e_tx) {
                    if (v->is_tombstone) {
                        exit_epoch(thread_id);
                        return false; // Record is deleted under snapshot
                    }
                    out_value = v->payload;
                    exit_epoch(thread_id);
                    return true;
                }

                v = v->next_version.load(std::memory_order_acquire);
            }
        }

        exit_epoch(thread_id);
        return false;
    }

    // -------------------------------------------------------------------------
    // Maintenance & Concurrent Garbage Collection
    // -------------------------------------------------------------------------

    void advance_epoch_and_reclaim(uint64_t min_active_tx_id) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);

        // Verify if all active threads have witnessed the current epoch
        for (size_t t = 0; t < max_threads_; ++t) {
            if (thread_registry_[t].registered.load(std::memory_order_acquire)) {
                if (thread_registry_[t].is_active.load(std::memory_order_acquire)) {
                    uint64_t th_epoch = thread_registry_[t].local_epoch.load(std::memory_order_acquire);
                    if (th_epoch != UINT64_MAX && th_epoch < cur_epoch) {
                        // At least one thread is still in an older epoch
                        return;
                    }
                }
            }
        }

        // Advance global epoch
        global_epoch_.fetch_add(1, std::memory_order_acq_rel);
        uint64_t new_epoch = cur_epoch + 1;

        // Bucket to reclaim is 2 epochs behind (safe to free)
        size_t reclaim_bucket = (new_epoch + 1) % 3;

        for (size_t t = 0; t < max_threads_; ++t) {
            auto& limbo = thread_registry_[t].retired_limbo[reclaim_bucket];
            for (auto& item : limbo) {
                item.deleter(item.ptr);
            }
            limbo.clear();
        }

        // Inline MVCC version chain pruning
        IndexNode* pred = head_;
        uintptr_t curr_val = pred->next[0].load(std::memory_order_acquire);
        IndexNode* curr = get_unmarked_ptr(curr_val);

        while (curr != nullptr && curr != tail_) {
            VersionNode* v = curr->version_head.load(std::memory_order_acquire);
            VersionNode* prev = nullptr;

            while (v != nullptr) {
                uint64_t e_tx = v->expired_tx_id.load(std::memory_order_acquire);

                // If expired before all active transactions, prune rest of chain
                if (e_tx <= min_active_tx_id) {
                    VersionNode* obsolete = v->next_version.exchange(nullptr, std::memory_order_acq_rel);
                    while (obsolete != nullptr) {
                        VersionNode* next = obsolete->next_version.load(std::memory_order_relaxed);
                        retire_node(0, obsolete, delete_version_node);
                        obsolete = next;
                    }

                    // If head itself is an obsolete tombstone, logically delete IndexNode
                    if (prev == nullptr && v->is_tombstone) {
                        logically_delete_node(curr);
                    }
                    break;
                }

                prev = v;
                v = v->next_version.load(std::memory_order_acquire);
            }

            curr = get_unmarked_ptr(curr->next[0].load(std::memory_order_acquire));
        }

        // Cooperative physical unlink sweep
        IndexNode* preds[MAX_HEIGHT];
        IndexNode* succs[MAX_HEIGHT];
        search_position(Key(), preds, succs);
    }

    // -------------------------------------------------------------------------
    // Observability & Validation
    // -------------------------------------------------------------------------

    size_t approximate_size() const {
        size_t count = 0;
        IndexNode* curr = get_unmarked_ptr(head_->next[0].load(std::memory_order_relaxed));
        while (curr && curr != tail_) {
            uintptr_t l0 = curr->next[0].load(std::memory_order_relaxed);
            if (!is_marked(l0)) {
                VersionNode* v = curr->version_head.load(std::memory_order_relaxed);
                if (v && !v->is_tombstone) {
                    ++count;
                }
            }
            curr = get_unmarked_ptr(l0);
        }
        return count;
    }

    void validate_internal_invariants() const {
        IndexNode* curr = head_;
        IndexNode* next_node = get_unmarked_ptr(curr->next[0].load(std::memory_order_acquire));

        while (next_node != nullptr && next_node != tail_) {
            // 1. Tower monotonicity: ensure strictly ascending keys
            if (curr != head_) {
                assert(comparator_(curr->key, next_node->key) && "Keys out of order in level 0 chain!");
            }

            // 2. Version chain monotonicity: created_tx_id strictly decreasing
            VersionNode* v = next_node->version_head.load(std::memory_order_acquire);
            uint64_t last_tx = UINT64_MAX;
            while (v != nullptr) {
                assert(v->created_tx_id < last_tx && "MVCC chain created_tx_id not strictly decreasing!");
                last_tx = v->created_tx_id;
                v = v->next_version.load(std::memory_order_acquire);
            }

            curr = next_node;
            next_node = get_unmarked_ptr(curr->next[0].load(std::memory_order_acquire));
        }
    }
};
```

---

### Part 2: Formal Concurrency & Linearizability Proof

#### 1. Snapshot Read Linearizability & Wait-Freedom
* **Linearization Point of Reads**:
  A snapshot read operation `get(key, tx_snapshot_id)` linearizes precisely at the atomic load of `IndexNode::version_head` via `std::memory_order_acquire`.
* **Proof of Bounded Traversal**:
  1. The skip list spine lookup traverses down $H \le 32$ levels. Every step across a level visits strictly ascending keys. Because nodes are never moved backward, forward pointer chasing is acyclic and strictly bounded by the number of elements.
  2. The version chain is strictly monotonic: each newly prepended `VersionNode` has $T_{\text{created\_new}} > T_{\text{created\_old}}$.
  3. Since readers do not modify any shared memory and only traverse forward down the immutable/monotonic pointer chains (`next_version`), the snapshot lookup executes in bounded lock-free / wait-free time without retrying or spinning.

#### 2. Insertions, Version Prepending, and Deletions
* **Linearization Point of Insertions**:
  * If the key is new: The successful `compare_exchange_strong` on `pred->next[0]` from unmarked `succ` to `make_unmarked(new_node)`.
  * If the key exists: The successful `compare_exchange_weak` on `existing_node->version_head` prepending the new `VersionNode`.
* **Prevention of Lost Updates**:
  * Concurrent updates to the same key race on the atomic CAS of `version_head`. Exactly one writer succeeds. The failing writer re-reads the new head, checks that `head->created_tx_id < tx_id`, updates its `next_version` pointer, and re-attempts the CAS.
* **Absence of Dangling Pointer Dereferences**:
  * Under Harris/Fraser pointer tagging, a node is logically marked before it is physically unlinked. Readers and traversers reading a tagged pointer treat it as marked and use cooperative CAS to complete physical detachment.
  * Physical memory deallocation of both `IndexNode` and `VersionNode` is deferred across 3 epochs in the EBR manager. A node retired at epoch $E$ is only reclaimed when all threads have advanced to $\ge E + 2$. Therefore, any reading thread that entered an epoch guard prior to unlinking retains safe reference validity throughout its operation.

---

### Part 3: Memory Ordering & Hardware Architecture Rationale

| Operation / Field | Memory Order | Rationale & Synchronization Invariant |
| :--- | :--- | :--- |
| `IndexNode::next[0].CAS` (Insert) | `std::memory_order_release` | Synchronizes with readers/traversers loading `next[0]` with `acquire`. Guarantees that the initialized fields (`key`, `top_level`, `version_head`) of the new node are fully visible before the pointer becomes reachable. |
| `IndexNode::next[level].load` | `std::memory_order_acquire` | Establishes an acquire-load dependency. Ensures that dereferencing the returned pointer observes all previous writes to the node made prior to its insertion. |
| `node->next[level].CAS` (Marking) | `std::memory_order_acq_rel` | `acquire` ensures the thread observes the latest child pointer; `release` ensures the marked bit is globally published to all subsequent cooperative unlinking operations. |
| `version_head.CAS` (Prepend) | `std::memory_order_acq_rel` | `release` publishes the contents of the new `VersionNode` to concurrent readers. `acquire` establishes synchronization with prior prependers on the same key. |
| `expired_tx_id.store` | `std::memory_order_release` | Invalidation of an older version is published with release ordering so snapshot readers traversing the chain observe consistent visibility intervals ($[created, expired)$). |
| `ThreadControlBlock::is_active` | `std::memory_order_release` | Guarantees that the write to `local_epoch` is committed to memory before the thread is published as active to concurrent `advance_epoch_and_reclaim` sweeps. |
| `global_epoch_.fetch_add` | `std::memory_order_acq_rel` | Guarantees total ordering on epoch transitions and forces visibility of all retired bucket elements across CPU store buffers on weak-memory architectures (e.g., ARM64 / POWER). |

