### 2. Complete, Production-Grade C++20 Implementation

```cpp
#ifndef NUMA_EBR_RING_BUFFER_HPP
#define NUMA_EBR_RING_BUFFER_HPP

#include <atomic>
#include <cassert>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <functional>
#include <iostream>
#include <memory>
#include <new>
#include <numeric>
#include <optional>
#include <span>
#include <thread>
#include <type_traits>
#include <utility>
#include <vector>

namespace numa_concurrent {

// Dual-cacheline alignment (128 bytes) eliminates false sharing across adjacent prefetcher streams
inline constexpr size_t CACHELINE_SIZE = 128;

// ============================================================================
// 1. EPOCH-BASED RECLAMATION (EBR) SUBSYSTEM
// ============================================================================

class EbrManager {
public:
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr size_t RETIRE_THRESHOLD = 64;

    struct alignas(CACHELINE_SIZE) ThreadRecord {
        std::atomic<bool> active{false};
        std::atomic<uint64_t> local_epoch{0};
        std::array<std::vector<std::function<void()>>, NUM_EPOCHS> retire_lists;
        size_t ops_since_gc{0};
        ThreadRecord* next{nullptr};
    };

private:
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(CACHELINE_SIZE) std::atomic<ThreadRecord*> registry_head_{nullptr};

    EbrManager() = default;

public:
    ~EbrManager() {
        // Drain all retired nodes on shutdown
        for (uint64_t ep = 0; ep < NUM_EPOCHS; ++ep) {
            drain_epoch(ep);
        }

        ThreadRecord* curr = registry_head_.load(std::memory_order_relaxed);
        while (curr) {
            ThreadRecord* next = curr->next;
            delete curr;
            curr = next;
        }
    }

    static EbrManager& instance() {
        static EbrManager mgr;
        return mgr;
    }

    ThreadRecord& register_thread() {
        static thread_local ThreadRecord* local_rec = nullptr;
        if (local_rec != nullptr) {
            return *local_rec;
        }

        auto* new_rec = new ThreadRecord();
        ThreadRecord* old_head = registry_head_.load(std::memory_order_relaxed);
        do {
            new_rec->next = old_head;
        } while (!registry_head_.compare_exchange_weak(
            old_head, new_rec, std::memory_order_release, std::memory_order_relaxed));

        local_rec = new_rec;
        return *local_rec;
    }

    void enter(ThreadRecord& rec) noexcept {
        const uint64_t ge = global_epoch_.load(std::memory_order_relaxed);
        rec.local_epoch.store(ge, std::memory_order_relaxed);
        // acquire-release barrier ensures epoch visibility before reader payload access
        rec.active.store(true, std::memory_order_seq_cst);
    }

    void leave(ThreadRecord& rec) noexcept {
        rec.active.store(false, std::memory_order_release);
        if (++rec.ops_since_gc >= RETIRE_THRESHOLD) {
            rec.ops_since_gc = 0;
            try_advance_and_reclaim(rec);
        }
    }

    template <typename F>
    void defer_destruction(ThreadRecord& rec, F&& reclaim_fn) {
        const uint64_t ge = global_epoch_.load(std::memory_order_relaxed);
        rec.retire_lists[ge % NUM_EPOCHS].emplace_back(std::forward<F>(reclaim_fn));
    }

    void try_advance_and_reclaim(ThreadRecord& rec) {
        const uint64_t current_ge = global_epoch_.load(std::memory_order_relaxed);
        ThreadRecord* curr = registry_head_.load(std::memory_order_acquire);

        while (curr != nullptr) {
            if (curr->active.load(std::memory_order_acquire)) {
                if (curr->local_epoch.load(std::memory_order_relaxed) != current_ge) {
                    // Active thread operating in older epoch -> cannot advance global epoch
                    return;
                }
            }
            curr = curr->next;
        }

        // All active threads are at current_ge: safe to advance epoch
        if (global_epoch_.compare_exchange_strong(
                const_cast<uint64_t&>(current_ge), current_ge + 1,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            // Epoch E advanced to E+1; safe to reclaim epoch (E+1 - 2) mod 3 = (E-1) mod 3
            const size_t reclaim_epoch = (current_ge + NUM_EPOCHS - 1) % NUM_EPOCHS;
            drain_epoch(reclaim_epoch);
        }
    }

private:
    void drain_epoch(size_t epoch_idx) {
        ThreadRecord* curr = registry_head_.load(std::memory_order_acquire);
        while (curr != nullptr) {
            auto& list = curr->retire_lists[epoch_idx];
            for (auto& fn : list) {
                if (fn) fn();
            }
            list.clear();
            curr = curr->next;
        }
    }
};

class EpochGuard {
    EbrManager::ThreadRecord& rec_;

public:
    explicit EpochGuard(EbrManager::ThreadRecord& rec) noexcept : rec_(rec) {
        EbrManager::instance().enter(rec_);
    }

    ~EpochGuard() {
        EbrManager::instance().leave(rec_);
    }

    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
    EpochGuard(EpochGuard&&) = delete;
    EpochGuard& operator=(EpochGuard&&) = delete;
};

// ============================================================================
// 2. LOCK-FREE BOUNDED MPMC SUB-RING WITH ZERO-COPY BATCH LEASES
// ============================================================================

template <typename T>
class LockFreeRingBufferCore {
public:
    struct alignas(CACHELINE_SIZE) Slot {
        std::atomic<uint64_t> sequence{0};
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        T* ptr() noexcept {
            return reinterpret_cast<T*>(storage);
        }

        const T* ptr() const noexcept {
            return reinterpret_cast<const T*>(storage);
        }
    };

private:
    const size_t capacity_;
    const size_t mask_;
    Slot* const buffer_;

    alignas(CACHELINE_SIZE) std::atomic<uint64_t> head_{0};
    alignas(CACHELINE_SIZE) std::atomic<uint64_t> tail_{0};

public:
    explicit LockFreeRingBufferCore(size_t min_capacity)
        : capacity_(next_power_of_two(min_capacity)),
          mask_(capacity_ - 1),
          buffer_(static_cast<Slot*>(::operator new[](sizeof(Slot) * capacity_, std::align_val_t{alignof(Slot)}))) {
        for (size_t i = 0; i < capacity_; ++i) {
            new (&buffer_[i]) Slot();
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    ~LockFreeRingBufferCore() {
        // Clean up remaining unconsumed elements
        uint64_t t = tail_.load(std::memory_order_relaxed);
        uint64_t h = head_.load(std::memory_order_relaxed);
        while (t < h) {
            Slot& slot = buffer_[t & mask_];
            if (slot.sequence.load(std::memory_order_relaxed) == t + 1) {
                std::destroy_at(slot.ptr());
            }
            ++t;
        }

        for (size_t i = 0; i < capacity_; ++i) {
            buffer_[i].~Slot();
        }
        ::operator delete[](buffer_, std::align_val_t{alignof(Slot)});
    }

    LockFreeRingBufferCore(const LockFreeRingBufferCore&) = delete;
    LockFreeRingBufferCore& operator=(const LockFreeRingBufferCore&) = delete;

    size_t capacity() const noexcept { return capacity_; }

    // Producer Lease representing contiguous ownership of reserved slots
    class ProducerLease {
        LockFreeRingBufferCore* ring_{nullptr};
        uint64_t start_ticket_{0};
        size_t count_{0};
        bool committed_{false};

    public:
        ProducerLease() noexcept = default;

        ProducerLease(LockFreeRingBufferCore* ring, uint64_t start_ticket, size_t count) noexcept
            : ring_(ring), start_ticket_(start_ticket), count_(count), committed_(false) {}

        ~ProducerLease() {
            if (!committed_ && ring_ != nullptr && count_ > 0) {
                commit();
            }
        }

        ProducerLease(ProducerLease&& other) noexcept
            : ring_(other.ring_), start_ticket_(other.start_ticket_),
              count_(other.count_), committed_(other.committed_) {
            other.ring_ = nullptr;
            other.count_ = 0;
            other.committed_ = true;
        }

        ProducerLease& operator=(ProducerLease&& other) noexcept {
            if (this != &other) {
                if (!committed_ && ring_ != nullptr && count_ > 0) {
                    commit();
                }
                ring_ = other.ring_;
                start_ticket_ = other.start_ticket_;
                count_ = other.count_;
                committed_ = other.committed_;
                other.ring_ = nullptr;
                other.count_ = 0;
                other.committed_ = true;
            }
            return *this;
        }

        size_t size() const noexcept { return count_; }
        bool empty() const noexcept { return count_ == 0; }

        template <typename... Args>
        void construct_at(size_t index, Args&&... args) {
            assert(index < count_ && "Index out of lease range");
            uint64_t ticket = start_ticket_ + index;
            Slot& slot = ring_->buffer_[ticket & ring_->mask_];
            ::new (static_cast<void*>(slot.ptr())) T(std::forward<Args>(args)...);
        }

        void commit() {
            if (committed_ || ring_ == nullptr) return;
            // Publish batch to consumers: sequence transitions from ticket to ticket + 1
            for (size_t i = 0; i < count_; ++i) {
                uint64_t ticket = start_ticket_ + i;
                Slot& slot = ring_->buffer_[ticket & ring_->mask_];
                // release barrier guarantees the constructed object is visible
                // before slot.sequence is updated
                slot.sequence.store(ticket + 1, std::memory_order_release);
            }
            committed_ = true;
        }
    };

    // Consumer Lease representing contiguous ownership of consumable slots
    class ConsumerLease {
        LockFreeRingBufferCore* ring_{nullptr};
        uint64_t start_ticket_{0};
        size_t count_{0};
        bool committed_{false};

    public:
        ConsumerLease() noexcept = default;

        ConsumerLease(LockFreeRingBufferCore* ring, uint64_t start_ticket, size_t count) noexcept
            : ring_(ring), start_ticket_(start_ticket), count_(count), committed_(false) {}

        ~ConsumerLease() {
            if (!committed_ && ring_ != nullptr && count_ > 0) {
                commit();
            }
        }

        ConsumerLease(ConsumerLease&& other) noexcept
            : ring_(other.ring_), start_ticket_(other.start_ticket_),
              count_(other.count_), committed_(other.committed_) {
            other.ring_ = nullptr;
            other.count_ = 0;
            other.committed_ = true;
        }

        ConsumerLease& operator=(ConsumerLease&& other) noexcept {
            if (this != &other) {
                if (!committed_ && ring_ != nullptr && count_ > 0) {
                    commit();
                }
                ring_ = other.ring_;
                start_ticket_ = other.start_ticket_;
                count_ = other.count_;
                committed_ = other.committed_;
                other.ring_ = nullptr;
                other.count_ = 0;
                other.committed_ = true;
            }
            return *this;
        }

        size_t size() const noexcept { return count_; }
        bool empty() const noexcept { return count_ == 0; }

        T& get(size_t index) noexcept {
            assert(index < count_ && "Index out of lease range");
            uint64_t ticket = start_ticket_ + index;
            return *(ring_->buffer_[ticket & ring_->mask_].ptr());
        }

        const T& get(size_t index) const noexcept {
            assert(index < count_ && "Index out of lease range");
            uint64_t ticket = start_ticket_ + index;
            return *(ring_->buffer_[ticket & ring_->mask_].ptr());
        }

        T move_out(size_t index) noexcept {
            assert(index < count_ && "Index out of lease range");
            uint64_t ticket = start_ticket_ + index;
            Slot& slot = ring_->buffer_[ticket & ring_->mask_];
            T value = std::move(*slot.ptr());
            std::destroy_at(slot.ptr());
            return value;
        }

        void commit() {
            if (committed_ || ring_ == nullptr) return;
            // Advance slot sequence to ticket + capacity, making it available for next write lap
            for (size_t i = 0; i < count_; ++i) {
                uint64_t ticket = start_ticket_ + i;
                Slot& slot = ring_->buffer_[ticket & ring_->mask_];
                // release barrier ensures consumer is completely done reading/destroying the slot
                slot.sequence.store(ticket + ring_->capacity_, std::memory_order_release);
            }
            committed_ = true;
        }
    };

    // Zero-Copy Batch Reservation for Producers
    std::optional<ProducerLease> reserve_produce_batch(size_t requested_count) {
        if (requested_count == 0 || requested_count > capacity_) {
            return std::nullopt;
        }

        uint64_t current_head = head_.load(std::memory_order_relaxed);
        while (true) {
            uint64_t current_tail = tail_.load(std::memory_order_acquire);
            // Check capacity headroom
            if (current_head + requested_count > current_tail + capacity_) {
                return std::nullopt; // Queue saturated
            }

            if (head_.compare_exchange_weak(
                    current_head, current_head + requested_count,
                    std::memory_order_relaxed, std::memory_order_relaxed)) {
                break;
            }
            // current_head refreshed automatically on failure
        }

        // Wait-free / bounded spin on slot sequence verification
        for (size_t i = 0; i < requested_count; ++i) {
            uint64_t ticket = current_head + i;
            Slot& slot = buffer_[ticket & mask_];
            // Wait for slot to reach expected generation for writing
            while (slot.sequence.load(std::memory_order_acquire) != ticket) {
                #if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
                #elif defined(__aarch64__)
                asm volatile("yield" ::: "memory");
                #else
                std::this_thread::yield();
                #endif
            }
        }

        return ProducerLease(this, current_head, requested_count);
    }

    // Zero-Copy Batch Reservation for Consumers
    std::optional<ConsumerLease> reserve_consume_batch(size_t requested_count) {
        if (requested_count == 0 || requested_count > capacity_) {
            return std::nullopt;
        }

        uint64_t current_tail = tail_.load(std::memory_order_relaxed);
        while (true) {
            uint64_t current_head = head_.load(std::memory_order_acquire);
            if (current_tail >= current_head) {
                return std::nullopt; // Queue empty
            }

            size_t available = static_cast<size_t>(current_head - current_tail);
            size_t actual_count = std::min(requested_count, available);

            if (tail_.compare_exchange_weak(
                    current_tail, current_tail + actual_count,
                    std::memory_order_relaxed, std::memory_order_relaxed)) {

                // Wait for all producer writes in reserved batch to be published
                for (size_t i = 0; i < actual_count; ++i) {
                    uint64_t ticket = current_tail + i;
                    Slot& slot = buffer_[ticket & mask_];
                    while (slot.sequence.load(std::memory_order_acquire) != ticket + 1) {
                        #if defined(__x86_64__) || defined(_M_X64)
                        _mm_pause();
                        #elif defined(__aarch64__)
                        asm volatile("yield" ::: "memory");
                        #else
                        std::this_thread::yield();
                        #endif
                    }
                }
                return ConsumerLease(this, current_tail, actual_count);
            }
        }
    }

private:
    static constexpr size_t next_power_of_two(size_t n) noexcept {
        if (n <= 1) return 1;
        --n;
        n |= n >> 1;
        n |= n >> 2;
        n |= n >> 4;
        n |= n >> 8;
        n |= n >> 16;
        n |= n >> 32;
        return n + 1;
    }
};

// ============================================================================
// 3. NUMA-AWARE MULTI-LANE PARTITIONED WORK-STEALING CONTAINER
// ============================================================================

template <typename T>
class NumaBoundedMPMCQueue {
public:
    using LeaseProducer = typename LockFreeRingBufferCore<T>::ProducerLease;
    using LeaseConsumer = typename LockFreeRingBufferCore<T>::ConsumerLease;

private:
    const size_t num_lanes_;
    std::vector<std::unique_ptr<LockFreeRingBufferCore<T>>> sub_rings_;

public:
    explicit NumaBoundedMPMCQueue(size_t num_lanes, size_t capacity_per_lane)
        : num_lanes_(std::max<size_t>(1, num_lanes)) {
        sub_rings_.reserve(num_lanes_);
        for (size_t i = 0; i < num_lanes_; ++i) {
            sub_rings_.push_back(std::make_unique<LockFreeRingBufferCore<T>>(capacity_per_lane));
        }
    }

    size_t num_lanes() const noexcept { return num_lanes_; }
    size_t capacity_per_lane() const noexcept { return sub_rings_[0]->capacity(); }
    size_t total_capacity() const noexcept { return num_lanes_ * capacity_per_lane(); }

    // Direct Batch Produce to primary lane with round-robin work-overflow failover
    std::optional<LeaseProducer> reserve_produce(size_t preferred_lane, size_t count) {
        size_t lane = preferred_lane % num_lanes_;
        for (size_t attempt = 0; attempt < num_lanes_; ++attempt) {
            auto lease = sub_rings_[lane]->reserve_produce_batch(count);
            if (lease.has_value()) {
                return lease;
            }
            lane = (lane + 1) % num_lanes_; // Lane saturated: failover to neighbor
        }
        return std::nullopt;
    }

    // Work-Stealing Batch Consume: inspects preferred lane, steals from others on empty
    std::optional<LeaseConsumer> reserve_consume(size_t preferred_lane, size_t count) {
        size_t lane = preferred_lane % num_lanes_;
        for (size_t attempt = 0; attempt < num_lanes_; ++attempt) {
            auto lease = sub_rings_[lane]->reserve_consume_batch(count);
            if (lease.has_value()) {
                return lease;
            }
            lane = (lane + 1) % num_lanes_; // Work-stealing across sub-rings
        }
        return std::nullopt;
    }
};

} // namespace numa_concurrent

#endif // NUMA_EBR_RING_BUFFER_HPP
