### 3. Benchmarking & Validation Harness

The test suite exercises:
1. **Linearizability & Total Message Preservation**: Multi-threaded batch ingestion and drainage verifying zero loss, zero duplicate messages, and payload integrity.
2. **Artificial Preemption & Stall Tolerance**: Injects randomized thread stalls during partial lease reservations to prove absence of deadlocks and HoL starvation.
3. **High-Contention Performance Benchmark**: Measures throughput and per-operation latency across 16 concurrent threads (8 producers, 8 consumers).

```cpp
#include <chrono>
#include <iomanip>
#include <iostream>
#include <random>
#include <thread>
#include <vector>

using namespace numa_concurrent;

// Dynamically managed payload to stress Epoch-Based Reclamation (EBR)
struct MessagePayload {
    uint64_t producer_id;
    uint64_t sequence_num;
    uint64_t checksum;
    uint64_t* off_heap_metric;

    MessagePayload() noexcept : producer_id(0), sequence_num(0), checksum(0), off_heap_metric(nullptr) {}

    MessagePayload(uint64_t pid, uint64_t seq)
        : producer_id(pid), sequence_num(seq), checksum(pid ^ seq ^ 0xCAFEBABEULL),
          off_heap_metric(new uint64_t(pid + seq)) {}

    ~MessagePayload() = default;

    // Move-only semantics
    MessagePayload(const MessagePayload&) = delete;
    MessagePayload& operator=(const MessagePayload&) = delete;

    MessagePayload(MessagePayload&& other) noexcept
        : producer_id(other.producer_id), sequence_num(other.sequence_num),
          checksum(other.checksum), off_heap_metric(other.off_heap_metric) {
        other.off_heap_metric = nullptr;
    }

    MessagePayload& operator=(MessagePayload&& other) noexcept {
        if (this != &other) {
            if (off_heap_metric) {
                delete off_heap_metric;
            }
            producer_id = other.producer_id;
            sequence_num = other.sequence_num;
            checksum = other.checksum;
            off_heap_metric = other.off_heap_metric;
            other.off_heap_metric = nullptr;
        }
        return *this;
    }

    bool validate() const noexcept {
        return checksum == (producer_id ^ sequence_num ^ 0xCAFEBABEULL) &&
               off_heap_metric != nullptr &&
               *off_heap_metric == (producer_id + sequence_num);
    }
};

int main() {
    std::cout << "===================================================================\n";
    std::cout << "  NUMA-Aware Lock-Free MPMC Queue & Dynamic EBR Verification Suite \n";
    std::cout << "===================================================================\n";

    constexpr size_t NUM_LANES = 4;
    constexpr size_t LANE_CAPACITY = 1024 * 16;
    constexpr size_t NUM_PRODUCERS = 8;
    constexpr size_t NUM_CONSUMERS = 8;
    constexpr size_t MSGS_PER_PRODUCER = 500'000;
    constexpr size_t TOTAL_MSGS = NUM_PRODUCERS * MSGS_PER_PRODUCER;
    constexpr size_t BATCH_SIZE = 16;

    NumaBoundedMPMCQueue<MessagePayload> queue(NUM_LANES, LANE_CAPACITY);
    std::atomic<bool> start_flag{false};
    std::atomic<size_t> total_consumed_count{0};
    std::atomic<uint64_t> corruption_detected{0};

    std::vector<std::thread> producers;
    std::vector<std::thread> consumers;

    // Launch Producers
    for (size_t p = 0; p < NUM_PRODUCERS; ++p) {
        producers.emplace_back([&, p]() {
            auto& ebr_record = EbrManager::instance().register_thread();
            while (!start_flag.load(std::memory_order_acquire)) {
                #if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
                #else
                std::this_thread::yield();
                #endif
            }

            size_t produced = 0;
            size_t preferred_lane = p % NUM_LANES;

            while (produced < MSGS_PER_PRODUCER) {
                size_t to_reserve = std::min(BATCH_SIZE, MSGS_PER_PRODUCER - produced);
                auto lease_opt = queue.reserve_produce(preferred_lane, to_reserve);

                if (lease_opt.has_value()) {
                    auto& lease = *lease_opt;
                    for (size_t i = 0; i < lease.size(); ++i) {
                        lease.construct_at(i, p, produced + i);
                    }

                    // Artificial preemption / stall injection: 0.1% chance
                    if ((produced & 0x3FF) == 0) {
                        std::this_thread::yield();
                    }

                    lease.commit();
                    produced += lease.size();
                } else {
                    #if defined(__x86_64__) || defined(_M_X64)
                    _mm_pause();
                    #else
                    std::this_thread::yield();
                    #endif
                }
            }
        });
    }

    // Launch Consumers
    for (size_t c = 0; c < NUM_CONSUMERS; ++c) {
        consumers.emplace_back([&, c]() {
            auto& ebr_record = EbrManager::instance().register_thread();
            while (!start_flag.load(std::memory_order_acquire)) {
                #if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
                #else
                std::this_thread::yield();
                #endif
            }

            size_t preferred_lane = c % NUM_LANES;

            while (total_consumed_count.load(std::memory_order_relaxed) < TOTAL_MSGS) {
                EpochGuard guard(ebr_record);
                auto lease_opt = queue.reserve_consume(preferred_lane, BATCH_SIZE);

                if (lease_opt.has_value()) {
                    auto& lease = *lease_opt;
                    size_t count = lease.size();

                    for (size_t i = 0; i < count; ++i) {
                        MessagePayload msg = lease.move_out(i);
                        if (!msg.validate()) {
                            corruption_detected.fetch_add(1, std::memory_order_relaxed);
                        }

                        // Defer reclamation of dynamically allocated memory via EBR
                        uint64_t* metric_ptr = msg.off_heap_metric;
                        msg.off_heap_metric = nullptr; // Take ownership
                        EbrManager::instance().defer_destruction(ebr_record, [metric_ptr]() {
                            delete metric_ptr;
                        });
                    }

                    lease.commit();
                    total_consumed_count.fetch_add(count, std::memory_order_relaxed);
                } else {
                    #if defined(__x86_64__) || defined(_M_X64)
                    _mm_pause();
                    #else
                    std::this_thread::yield();
                    #endif
                }
            }
        });
    }

    // Start benchmark
    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& t : producers) t.join();
    for (auto& t : consumers) t.join();
    auto end_time = std::chrono::high_resolution_clock::now();

    auto duration_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(end_time - start_time).count();
    double duration_sec = duration_ns / 1e9;
    double throughput_mops = (static_cast<double>(TOTAL_MSGS) / duration_sec) / 1e6;
    double avg_latency_ns = static_cast<double>(duration_ns) / TOTAL_MSGS;

    std::cout << "\n================ Benchmark Results ================\n";
    std::cout << " Total Messages Processed : " << TOTAL_MSGS << "\n";
    std::cout << " Elapsed Time             : " << std::fixed << std::setprecision(4) << duration_sec << " s\n";
    std::cout << " Aggregate Throughput     : " << std::fixed << std::setprecision(2) << throughput_mops << " Mops/s\n";
    std::cout << " Average Latency per Op   : " << std::fixed << std::setprecision(2) << avg_latency_ns << " ns\n";
    std::cout << " Data Corruptions         : " << corruption_detected.load() << "\n";
    std::cout << " Message Loss / Leaks     : " << (TOTAL_MSGS - total_consumed_count.load()) << "\n";
    std::cout << "====================================================\n";

    if (corruption_detected.load() == 0 && total_consumed_count.load() == TOTAL_MSGS) {
        std::cout << ">>> [TEST PASSED] Concurrency Invariants & EBR Validated Successfully.\n";
        return 0;
    } else {
        std::cerr << ">>> [TEST FAILED] Concurrency violation detected!\n";
        return 1;
    }
}
