### 2. Complete C++20 Implementation

```cpp
#ifndef NUMA_EBR_RING_BUFFER_HPP
#define NUMA_EBR_RING_BUFFER_HPP

#include <iostream>
#include <atomic>
#include <memory>
#include <new>
#include <vector>
#include <array>
#include <optional>
#include <span>
#include <thread>
#include <chrono>
#include <cassert>
#include <cstring>
#include <utility>
#include <type_traits>

// Dual-cacheline padding constant to prevent adjacent-line HW prefetcher false sharing.
inline constexpr size_t CACHELINE_SIZE = 128;

#if defined(__cpp_lib_hardware_interference_size)
    inline constexpr size_t HARDWARE_DESTRUCTIVE_SIZE = 
        std::max<size_t>(CACHELINE_SIZE, std::hardware_destructive_interference_size);
#else
    inline constexpr size_t HARDWARE_DESTRUCTIVE_SIZE = CACHELINE_SIZE;
#endif

// ============================================================================
// SECTION 1: Lock-Free Epoch-Based Memory Reclamation (EBR)
// ============================================================================

class EpochManager {
public:
    static constexpr size_t NUM_EPOCHS = 3;
    static constexpr uint64_t INACTIVE_EPOCH = std::numeric_limits<uint64_t>::max();

    struct alignas(HARDWARE_DESTRUCTIVE_SIZE) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{INACTIVE_EPOCH};
        std::atomic<ThreadControlBlock*> next{nullptr};
        std::atomic<bool> registered{false};
    };

    struct RetiredNode {
        void* data{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    class alignas(HARDWARE_DESTRUCTIVE_SIZE) LocalEpochContext {
    public:
        ThreadControlBlock* tcb{nullptr};
        std::array<RetiredNode*, NUM_EPOCHS> retire_lists{nullptr, nullptr, nullptr};
        size_t ops_since_gc{0};

        ~LocalEpochContext() {
            // Evacuate and reclaim all remaining nodes on thread termination
            for (size_t i = 0; i < NUM_EPOCHS; ++i) {
                reclaim_list(retire_lists[i]);
                retire_lists[i] = nullptr;
            }
            if (tcb) {
                tcb->local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
                tcb->registered.store(false, std::memory_order_release);
            }
        }

        static void reclaim_list(RetiredNode* head) {
            while (head) {
                RetiredNode* next = head->next;
                if (head->deleter && head->data) {
                    head->deleter(head->data);
                }
                delete head;
                head = next;
            }
        }
    };

private:
    alignas(HARDWARE_DESTRUCTIVE_SIZE) std::atomic<uint64_t> global_epoch_{0};
    alignas(HARDWARE_DESTRUCTIVE_SIZE) std::atomic<ThreadControlBlock*> tcb_head_{nullptr};

    EpochManager() = default;

public:
    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    ~EpochManager() {
        ThreadControlBlock* curr = tcb_head_.load(std::memory_order_relaxed);
        while (curr) {
            ThreadControlBlock* next = curr->next.load(std::memory_order_relaxed);
            delete curr;
            curr = next;
        }
    }

    ThreadControlBlock* register_thread() {
        // Recycle inactive TCB if available, otherwise allocate new
        ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire);
        while (curr) {
            bool expected = false;
            if (!curr->registered.load(std::memory_order_relaxed) &&
                curr->registered.compare_exchange_strong(expected, true, 
                                                         std::memory_order_acq_rel, 
                                                         std::memory_order_relaxed)) {
                return curr;
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        auto* new_tcb = new ThreadControlBlock();
        new_tcb->registered.store(true, std::memory_order_relaxed);

        ThreadControlBlock* old_head = tcb_head_.load(std::memory_order_relaxed);
        do {
            new_tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!tcb_head_.compare_exchange_weak(old_head, new_tcb,
                                                  std::memory_order_release,
                                                  std::memory_order_relaxed));
        return new_tcb;
    }

    static LocalEpochContext& get_local_context() {
        thread_local static LocalEpochContext ctx;
        if (!ctx.tcb) {
            ctx.tcb = instance().register_thread();
        }
        return ctx;
    }

    void enter_critical() {
        LocalEpochContext& ctx = get_local_context();
        uint64_t current_global = global_epoch_.load(std::memory_order_acquire);
        ctx.tcb->local_epoch.store(current_global, std::memory_order_release);
    }

    void exit_critical() {
        LocalEpochContext& ctx = get_local_context();
        ctx.tcb->local_epoch.store(INACTIVE_EPOCH, std::memory_order_release);

        if (++ctx.ops_since_gc >= 64) {
            ctx.ops_since_gc = 0;
            try_advance_and_reclaim();
        }
    }

    template <typename T>
    void defer_reclaim(T* ptr) {
        if (!ptr) return;
        LocalEpochContext& ctx = get_local_context();
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed) % NUM_EPOCHS;

        auto* node = new RetiredNode();
        node->data = static_cast<void*>(ptr);
        node->deleter = [](void* p) { delete static_cast<T*>(p); };
        node->next = ctx.retire_lists[g_epoch];
        ctx.retire_lists[g_epoch] = node;
    }

    void try_advance_and_reclaim() {
        LocalEpochContext& ctx = get_local_context();
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);

        // Check if all active threads have caught up to global epoch
        ThreadControlBlock* curr = tcb_head_.load(std::memory_order_acquire);
        while (curr) {
            if (curr->registered.load(std::memory_order_relaxed)) {
                uint64_t local = curr->local_epoch.load(std::memory_order_acquire);
                if (local != INACTIVE_EPOCH && local != g_epoch) {
                    return; // Thread still in older epoch; abort advance
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        // Advance global epoch
        uint64_t next_epoch = (g_epoch + 1);
        if (global_epoch_.compare_exchange_strong(g_epoch, next_epoch, 
                                                 std::memory_order_acq_rel, 
                                                 std::memory_order_relaxed)) {
            // Reclaim retired memory from epoch (next_epoch + 1) % 3 (i.e. epoch - 2)
            size_t safe_epoch = (next_epoch + 1) % NUM_EPOCHS;
            RetiredNode* nodes = ctx.retire_lists[safe_epoch];
            ctx.retire_lists[safe_epoch] = nullptr;
            LocalEpochContext::reclaim_list(nodes);
        }
    }
};

class EpochGuard {
public:
    EpochGuard() { EpochManager::instance().enter_critical(); }
    ~EpochGuard() { EpochManager::instance().exit_critical(); }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// SECTION 2: Bounded MPMC Core with Zero-Copy Batch Lease Semantics
// ============================================================================

template <typename T>
class ProducerLease;

template <typename T>
class ConsumerLease;

template <typename T>
class LockFreeRingBufferCore {
    static_assert(std::is_nothrow_destructible_v<T>, "T must be nothrow destructible");

public:
    struct alignas(HARDWARE_DESTRUCTIVE_SIZE) Slot {
        std::atomic<uint64_t> sequence;
        alignas(alignof(T)) std::byte storage[sizeof(T)];

        T* get_ptr() noexcept {
            return reinterpret_cast<T*>(storage);
        }

        const T* get_ptr() const noexcept {
            return reinterpret_cast<const T*>(storage);
        }
    };

    explicit LockFreeRingBufferCore(size_t capacity)
        : capacity_(next_power_of_two(capacity)),
          mask_(capacity_ - 1),
          slots_(std::make_unique<Slot[]>(capacity_)) {
        for (size_t i = 0; i < capacity_; ++i) {
            slots_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    ~LockFreeRingBufferCore() {
        // Destroy elements that were committed but not consumed
        uint64_t head = head_ticket_.load(std::memory_order_relaxed);
        uint64_t tail = tail_ticket_.load(std::memory_order_relaxed);
        for (uint64_t t = head; t < tail; ++t) {
            Slot& slot = slots_[t & mask_];
            if (slot.sequence.load(std::memory_order_relaxed) == t + 1) {
                std::destroy_at(slot.get_ptr());
            }
        }
    }

    LockFreeRingBufferCore(const LockFreeRingBufferCore&) = delete;
    LockFreeRingBufferCore& operator=(const LockFreeRingBufferCore&) = delete;

    size_t capacity() const noexcept { return capacity_; }

    auto reserve_produce_batch(size_t count) -> std::optional<ProducerLease<T>> {
        if (count == 0 || count > capacity_) return std::nullopt;

        uint64_t current_tail = tail_ticket_.load(std::memory_order_relaxed);
        while (true) {
            uint64_t current_head = head_ticket_.load(std::memory_order_acquire);

            // Bounded headroom validation
            if (current_tail + count > current_head + capacity_) {
                return std::nullopt; // Queue full or cannot satisfy full batch
            }

            // Verify slots in proposed batch are available (sequence == ticket)
            bool slots_available = true;
            for (size_t i = 0; i < count; ++i) {
                uint64_t ticket = current_tail + i;
                Slot& slot = slots_[ticket & mask_];
                uint64_t seq = slot.sequence.load(std::memory_order_acquire);
                if (seq != ticket) {
                    slots_available = false;
                    break;
                }
            }

            if (!slots_available) {
                // Refresh local tail estimation
                current_tail = tail_ticket_.load(std::memory_order_relaxed);
                continue;
            }

            if (tail_ticket_.compare_exchange_weak(current_tail, current_tail + count,
                                                   std::memory_order_relaxed,
                                                   std::memory_order_relaxed)) {
                return ProducerLease<T>(this, current_tail, count);
            }
        }
    }

    auto reserve_consume_batch(size_t count) -> std::optional<ConsumerLease<T>> {
        if (count == 0 || count > capacity_) return std::nullopt;

        uint64_t current_head = head_ticket_.load(std::memory_order_relaxed);
        while (true) {
            uint64_t current_tail = tail_ticket_.load(std::memory_order_acquire);

            if (current_head >= current_tail) {
                return std::nullopt; // Queue empty
            }

            size_t available = static_cast<size_t>(current_tail - current_head);
            size_t actual_count = std::min(count, available);

            // Verify that slots up to actual_count are committed (sequence == ticket + 1)
            size_t ready_count = 0;
            for (size_t i = 0; i < actual_count; ++i) {
                uint64_t ticket = current_head + i;
                Slot& slot = slots_[ticket & mask_];
                uint64_t seq = slot.sequence.load(std::memory_order_acquire);
                if (seq == ticket + 1) {
                    ready_count++;
                } else {
                    break; // Contiguous readable prefix terminated
                }
            }

            if (ready_count == 0) {
                return std::nullopt; // Producers reserved tickets but have not completed commit
            }

            if (head_ticket_.compare_exchange_weak(current_head, current_head + ready_count,
                                                   std::memory_order_relaxed,
                                                   std::memory_order_relaxed)) {
                return ConsumerLease<T>(this, current_head, ready_count);
            }
        }
    }

private:
    friend class ProducerLease<T>;
    friend class ConsumerLease<T>;

    static size_t next_power_of_two(size_t n) {
        size_t p = 1;
        while (p < n) p <<= 1;
        return p;
    }

    const size_t capacity_;
    const size_t mask_;
    std::unique_ptr<Slot[]> slots_;

    alignas(HARDWARE_DESTRUCTIVE_SIZE) std::atomic<uint64_t> tail_ticket_{0};
    alignas(HARDWARE_DESTRUCTIVE_SIZE) std::atomic<uint64_t> head_ticket_{0};
};

// ============================================================================
// SECTION 3: Zero-Copy RAII Leases with Commit Semantics
// ============================================================================

template <typename T>
class ProducerLease {
public:
    ProducerLease(LockFreeRingBufferCore<T>* ring, uint64_t start_ticket, size_t count) noexcept
        : ring_(ring), start_ticket_(start_ticket), count_(count), committed_(false) {}

    ~ProducerLease() {
        if (!committed_) {
            commit();
        }
    }

    ProducerLease(const ProducerLease&) = delete;
    ProducerLease& operator=(const ProducerLease&) = delete;

    ProducerLease(ProducerLease&& other) noexcept
        : ring_(other.ring_),
          start_ticket_(other.start_ticket_),
          count_(other.count_),
          committed_(other.committed_) {
        other.ring_ = nullptr;
        other.committed_ = true;
    }

    ProducerLease& operator=(ProducerLease&& other) noexcept {
        if (this != &other) {
            if (!committed_) commit();
            ring_ = other.ring_;
            start_ticket_ = other.start_ticket_;
            count_ = other.count_;
            committed_ = other.committed_;
            other.ring_ = nullptr;
            other.committed_ = true;
        }
        return *this;
    }

    size_t size() const noexcept { return count_; }

    template <typename... Args>
    void emplace(size_t index, Args&&... args) {
        assert(index < count_ && "ProducerLease out-of-bounds access");
        assert(!committed_ && "Cannot write to committed lease");
        uint64_t ticket = start_ticket_ + index;
        auto& slot = ring_->slots_[ticket & ring_->mask_];
        ::new (static_cast<void*>(slot.storage)) T(std::forward<Args>(args)...);
    }

    void set(size_t index, T value) {
        emplace(index, std::move(value));
    }

    void commit() noexcept {
        if (committed_ || !ring_) return;

        // Slot sequence increment to (ticket + 1) publishes the slot directly.
        // memory_order_release guarantees all writes to slot::storage happen-before
        // consumers observe sequence == ticket + 1.
        for (size_t i = 0; i < count_; ++i) {
            uint64_t ticket = start_ticket_ + i;
            auto& slot = ring_->slots_[ticket & ring_->mask_];
            slot.sequence.store(ticket + 1, std::memory_order_release);
        }
        committed_ = true;
    }

private:
    LockFreeRingBufferCore<T>* ring_;
    uint64_t start_ticket_{0};
    size_t count_{0};
    bool committed_{false};
};

template <typename T>
class ConsumerLease {
public:
    ConsumerLease(LockFreeRingBufferCore<T>* ring, uint64_t start_ticket, size_t count) noexcept
        : ring_(ring), start_ticket_(start_ticket), count_(count), committed_(false) {}

    ~ConsumerLease() {
        if (!committed_) {
            commit();
        }
    }

    ConsumerLease(const ConsumerLease&) = delete;
    ConsumerLease& operator=(const ConsumerLease&) = delete;

    ConsumerLease(ConsumerLease&& other) noexcept
        : ring_(other.ring_),
          start_ticket_(other.start_ticket_),
          count_(other.count_),
          committed_(other.committed_) {
        other.ring_ = nullptr;
        other.committed_ = true;
    }

    ConsumerLease& operator=(ConsumerLease&& other) noexcept {
        if (this != &other) {
            if (!committed_) commit();
            ring_ = other.ring_;
            start_ticket_ = other.start_ticket_;
            count_ = other.count_;
            committed_ = other.committed_;
            other.ring_ = nullptr;
            other.committed_ = true;
        }
        return *this;
    }

    size_t size() const noexcept { return count_; }

    const T& get(size_t index) const noexcept {
        assert(index < count_ && "ConsumerLease out-of-bounds access");
        uint64_t ticket = start_ticket_ + index;
        return *ring_->slots_[ticket & ring_->mask_].get_ptr();
    }

    T extract(size_t index) {
        assert(index < count_ && "ConsumerLease out-of-bounds access");
        uint64_t ticket = start_ticket_ + index;
        auto& slot = ring_->slots_[ticket & ring_->mask_];
        T item = std::move(*slot.get_ptr());
        std::destroy_at(slot.get_ptr());
        return item;
    }

    void commit() noexcept {
        if (committed_ || !ring_) return;

        // Advance slot sequence to (ticket + capacity) with release barrier.
        // Happens-before ensures slot reads/destruction complete before next producer overwrites.
        for (size_t i = 0; i < count_; ++i) {
            uint64_t ticket = start_ticket_ + i;
            auto& slot = ring_->slots_[ticket & ring_->mask_];
            slot.sequence.store(ticket + ring_->capacity_, std::memory_order_release);
        }
        committed_ = true;
    }

private:
    LockFreeRingBufferCore<T>* ring_;
    uint64_t start_ticket_{0};
    size_t count_{0};
    bool committed_{false};
};

// ============================================================================
// SECTION 4: NUMA Partitioned Ring Topology with Work-Stealing Arbiter
// ============================================================================

template <typename T, size_t NUM_PARTITIONS = 4>
class NumaRingBuffer {
public:
    explicit NumaRingBuffer(size_t per_partition_capacity) {
        for (size_t i = 0; i < NUM_PARTITIONS; ++i) {
            partitions_[i] = std::make_unique<LockFreeRingBufferCore<T>>(per_partition_capacity);
        }
    }

    auto reserve_produce_batch(size_t partition_hint, size_t count) 
        -> std::optional<std::pair<size_t, ProducerLease<T>>> {
        size_t partition = partition_hint % NUM_PARTITIONS;

        // 1. Attempt primary NUMA-local partition
        auto lease = partitions_[partition]->reserve_produce_batch(count);
        if (lease.has_value()) {
            return std::make_pair(partition, std::move(*lease));
        }

        // 2. Local partition saturated; arbitrate across alternate NUMA partitions
        for (size_t i = 1; i < NUM_PARTITIONS; ++i) {
            size_t target = (partition + i) % NUM_PARTITIONS;
            lease = partitions_[target]->reserve_produce_batch(count);
            if (lease.has_value()) {
                return std::make_pair(target, std::move(*lease));
            }
        }
        return std::nullopt;
    }

    auto reserve_consume_batch(size_t partition_hint, size_t count)
        -> std::optional<std::pair<size_t, ConsumerLease<T>>> {
        size_t partition = partition_hint % NUM_PARTITIONS;

        // 1. Attempt primary NUMA-local partition
        auto lease = partitions_[partition]->reserve_consume_batch(count);
        if (lease.has_value()) {
            return std::make_pair(partition, std::move(*lease));
        }

        // 2. Steal from adjacent NUMA partitions
        for (size_t i = 1; i < NUM_PARTITIONS; ++i) {
            size_t target = (partition + i) % NUM_PARTITIONS;
            lease = partitions_[target]->reserve_consume_batch(count);
            if (lease.has_value()) {
                return std::make_pair(target, std::move(*lease));
            }
        }
        return std::nullopt;
    }

    size_t partition_count() const noexcept { return NUM_PARTITIONS; }

private:
    std::array<std::unique_ptr<LockFreeRingBufferCore<T>>, NUM_PARTITIONS> partitions_;
};

#endif // NUMA_EBR_RING_BUFFER_HPP
