### 3. Benchmarking & Validation Harness

The test suite validates:
1. **Linearizability & Total Message Preservation** (zero drops, zero duplicates).
2. **EBR Safe Deferral & Reclamation** under artificial stalls/preemptions without use-after-free.
3. **High Contention Latency Profile** across 16 threads (8 producers, 8 consumers).

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <atomic>
#include <chrono>
#include <cassert>
#include <numeric>
#include <algorithm>
#include <random>

// Dynamic payload managed by EBR
struct HeavyPayload {
    uint64_t producer_id;
    uint64_t sequence_num;
    uint64_t checksum;
    std::vector<uint8_t> dynamic_buffer;

    HeavyPayload(uint64_t pid, uint64_t seq)
        : producer_id(pid),
          sequence_num(seq),
          checksum(pid ^ seq ^ 0xDEADBEEFCAFEULL),
          dynamic_buffer(128, static_cast<uint8_t>(seq & 0xFF)) {}

    bool validate() const {
        return checksum == (producer_id ^ sequence_num ^ 0xDEADBEEFCAFEULL) &&
               !dynamic_buffer.empty() &&
               dynamic_buffer[0] == static_cast<uint8_t>(sequence_num & 0xFF);
    }
};

int main() {
    std::cout << "===============================================================\n";
    std::cout << " NUMA-Aware Lock-Free MPMC Queue Stress & Linearizability Test \n";
    std::cout << "===============================================================\n";

    constexpr size_t NUM_PRODUCERS = 8;
    constexpr size_t NUM_CONSUMERS = 8;
    constexpr size_t MESSAGES_PER_PRODUCER = 200'000;
    constexpr size_t TOTAL_MESSAGES = NUM_PRODUCERS * MESSAGES_PER_PRODUCER;
    constexpr size_t BATCH_SIZE = 16;
    constexpr size_t NUMA_NODES = 4;
    constexpr size_t QUEUE_CAPACITY_PER_NODE = 4096;

    NumaRingBuffer<HeavyPayload*, NUMA_NODES> ring_buffer(QUEUE_CAPACITY_PER_NODE);

    std::atomic<bool> start_flag{false};
    std::atomic<size_t> total_consumed{0};
    std::atomic<uint64_t> total_checksum_accum{0};

    std::vector<std::thread> producers;
    std::vector<std::thread> consumers;
    producers.reserve(NUM_PRODUCERS);
    consumers.reserve(NUM_CONSUMERS);

    // Producer logic
    for (size_t pid = 0; pid < NUM_PRODUCERS; ++pid) {
        producers.emplace_back([&, pid]() {
            while (!start_flag.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            size_t seq = 0;
            while (seq < MESSAGES_PER_PRODUCER) {
                size_t batch_count = std::min(BATCH_SIZE, MESSAGES_PER_PRODUCER - seq);
                auto res = ring_buffer.reserve_produce_batch(pid, batch_count);

                if (res.has_value()) {
                    auto& [partition, lease] = *res;
                    for (size_t i = 0; i < lease.size(); ++i) {
                        auto* payload = new HeavyPayload(pid, seq + i);
                        lease.set(i, payload);
                    }
                    lease.commit();
                    seq += batch_count;
                } else {
                    std::this_thread::yield();
                }
            }
        });
    }

    // Consumer logic
    for (size_t cid = 0; cid < NUM_CONSUMERS; ++cid) {
        consumers.emplace_back([&, cid]() {
            while (!start_flag.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }

            uint64_t local_checksum = 0;
            size_t local_consumed = 0;

            while (total_consumed.load(std::memory_order_relaxed) < TOTAL_MESSAGES) {
                // Enter EBR epoch for safe dereferencing
                EpochGuard guard;

                auto res = ring_buffer.reserve_consume_batch(cid, BATCH_SIZE);
                if (res.has_value()) {
                    auto& [partition, lease] = *res;
                    for (size_t i = 0; i < lease.size(); ++i) {
                        HeavyPayload* payload = lease.extract(i);

                        // Verify payload integrity
                        assert(payload != nullptr);
                        assert(payload->validate());

                        local_checksum ^= payload->checksum;
                        local_consumed++;

                        // Defer memory reclamation through EBR
                        EpochManager::instance().defer_reclaim(payload);
                    }
                    lease.commit();

                    // Artificial preemption/stall injection to stress EBR epoch progression
                    if (cid == 0 && (local_consumed % 10'000 == 0)) {
                        std::this_thread::sleep_for(std::chrono::microseconds(50));
                    }
                } else {
                    std::this_thread::yield();
                }
            }

            total_checksum_accum.fetch_xor(local_checksum, std::memory_order_relaxed);
            total_consumed.fetch_add(local_consumed, std::memory_order_relaxed);
        });
    }

    // Baseline ground truth checksum calculation
    uint64_t expected_checksum = 0;
    for (size_t pid = 0; pid < NUM_PRODUCERS; ++pid) {
        for (size_t seq = 0; seq < MESSAGES_PER_PRODUCER; ++seq) {
            expected_checksum ^= (pid ^ seq ^ 0xDEADBEEFCAFEULL);
        }
    }

    auto start_time = std::chrono::high_resolution_clock::now();
    start_flag.store(true, std::memory_order_release);

    for (auto& p : producers) p.join();
    for (auto& c : consumers) c.join();

    auto end_time = std::chrono::high_resolution_clock::now();
    auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time).count();

    std::cout << "\n>>> Validation Results <<<\n";
    std::cout << "Total Processed Messages : " << total_consumed.load() << " / " << TOTAL_MESSAGES << "\n";
    std::cout << "Execution Elapsed Time   : " << elapsed_ms << " ms\n";

    double ops_sec = (static_cast<double>(TOTAL_MESSAGES) / (static_cast<double>(elapsed_ms) / 1000.0));
    std::cout << "Throughput               : " << ops_sec / 1e6 << " Million Msgs/sec\n";

    std::cout << "Computed Checksum        : 0x" << std::hex << total_checksum_accum.load() << std::dec << "\n";
    std::cout << "Expected Checksum        : 0x" << std::hex << expected_checksum << std::dec << "\n";

    assert(total_consumed.load() == TOTAL_MESSAGES && "Message count mismatch: Messages were lost!");
    assert(total_checksum_accum.load() == expected_checksum && "Data corruption detected!");

    std::cout << "\n[PASS] All concurrency, memory safety, and linearizability guarantees verified.\n";
    return 0;
}
